ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT / "tools" / "mindustry_godot_transpiler"))

from mindustry_port.playable import build_playable_manifest


class PlayableManifestTests(unittest.TestCase):
    RUNTIME_OWNER_REGISTRY_CHAIN = [
        "SourceRuntimeOwnerRegistry.gd",
        "SourceRuntimeOwnerGameplayRegistry.gd",
        "SourceRuntimeOwnerUnitBuildingRegistry.gd",
        "SourceRuntimeOwnerUnitDestroyRegistry.gd",
        "SourceRuntimeOwnerBuilderRegistry.gd",
        "SourceRuntimeOwnerConstructRegistry.gd",
        "SourceRuntimeOwnerUnitPayloadRegistry.gd",
        "SourceRuntimeOwnerBuildPayloadRegistry.gd",
        "SourceRuntimeOwnerSyncRegistry.gd",
        "SourceRuntimeOwnerAbilityRegistry.gd",
        "SourceRuntimeOwnerPowerRegistry.gd",
        "SourceRuntimeOwnerTurretRegistry.gd",
        "SourceRuntimeOwnerBuildingRegistry.gd",
        "SourceRuntimeOwnerConsumeRegistry.gd",
        "SourceRuntimeOwnerBlockRegistry.gd",
    ]

    def _method_body(self, source: str, signature: str) -> str:
        if signature not in source and "class_name PortGame" in source:
            source = self._port_compatibility_surface_source(source, signature)
        body = source.split(signature, 1)[1]
        for boundary in ("\nfunc ", "\nstatic func ", "\nextends "):
            body = body.split(boundary, 1)[0]
        return body

    def _static_method_body(self, source: str, signature: str, normalize_build_payload_keys: bool = True) -> str:
        body = source.split(signature, 1)[1].split("\nstatic func ", 1)[0]
        if normalize_build_payload_keys and "class_name SourceBuildPayloadState" in source:
            # Normalize aliased dictionary-key syntax for legacy assertions; the
            # owning source-text file is checked separately for the aliases.
            aliases = {
                "SOURCE_BUILD_PAYLOAD_SOURCE_OWNER_KEY": "source_owner",
                "SOURCE_BUILD_PAYLOAD_SOURCE_KEY": "source",
                "SOURCE_BUILD_PAYLOAD_CLASS_EXPR_KEY": "class_expr",
                "SOURCE_BUILD_PAYLOAD_FIELD_EXPR_KEY": "field_expr",
                "SOURCE_BUILD_PAYLOAD_IMPORT_EXPR_KEY": "import_expr",
                "SOURCE_BUILD_PAYLOAD_OVERRIDE_EXPR_KEY": "override_expr",
                "SOURCE_BUILD_PAYLOAD_METHOD_KEY": "method",
                "SOURCE_BUILD_PAYLOAD_RETURN_EXPR_KEY": "return_expr",
                "SOURCE_BUILD_PAYLOAD_BUILD_BLOCK_KEY": "build_block",
                "SOURCE_BUILD_PAYLOAD_CALL_KEY": "call",
                "SOURCE_BUILD_PAYLOAD_BLOCK_KEY": "block",
                "SOURCE_BUILD_PAYLOAD_TEAM_KEY": "team",
                "SOURCE_BUILD_PAYLOAD_CONSTRUCTOR_KEY": "constructor",
                "SOURCE_BUILD_PAYLOAD_BUILD_ASSIGN_EXPR_KEY": "build_assign_expr",
                "SOURCE_BUILD_PAYLOAD_TILE_ASSIGN_EXPR_KEY": "tile_assign_expr",
                "SOURCE_BUILD_PAYLOAD_CREATE_CALL_KEY": "create_call",
                "SOURCE_BUILD_PAYLOAD_TILE_AFTER_KEY": "tile_after",
                "SOURCE_BUILD_PAYLOAD_BUILD_KEY": "build",
                "SOURCE_BUILD_PAYLOAD_BUILD_AFTER_KEY": "build_after",
                "SOURCE_BUILD_PAYLOAD_OTHER_IS_BUILD_PAYLOAD_KEY": "other_is_build_payload",
                "SOURCE_BUILD_PAYLOAD_OTHER_BLOCK_KEY": "other_block",
                "SOURCE_BUILD_PAYLOAD_CONTENT_EQUALS_KEY": "content_equals",
                "SOURCE_BUILD_PAYLOAD_CONTENT_KEY": "content",
                "SOURCE_BUILD_PAYLOAD_BUILD_TIME_KEY": "buildTime",
                "SOURCE_BUILD_PAYLOAD_REQUIREMENTS_KEY": "requirements",
                "SOURCE_BUILD_PAYLOAD_X_KEY": "x",
                "SOURCE_BUILD_PAYLOAD_Y_KEY": "y",
                "SOURCE_BUILD_PAYLOAD_BUILD_BLOCK_SIZE_KEY": "build_block_size",
                "SOURCE_BUILD_PAYLOAD_SOURCE_TILESIZE_KEY": "source_tilesize",
                "SOURCE_BUILD_PAYLOAD_SIZE_KEY": "size",
                "SOURCE_BUILD_PAYLOAD_PAYLOAD_BLOCK_WRITE_EXPR_KEY": "payload_block_write_expr",
                "SOURCE_BUILD_PAYLOAD_BLOCK_ID_WRITE_EXPR_KEY": "block_id_write_expr",
                "SOURCE_BUILD_PAYLOAD_VERSION_WRITE_EXPR_KEY": "version_write_expr",
                "SOURCE_BUILD_PAYLOAD_WRITE_ALL_EXPR_KEY": "write_all_expr",
                "SOURCE_BUILD_PAYLOAD_PAYLOAD_BLOCK_KEY": "payload_block",
                "SOURCE_BUILD_PAYLOAD_BUILD_BLOCK_ID_KEY": "build_block_id",
                "SOURCE_BUILD_PAYLOAD_BUILD_VERSION_KEY": "build_version",
                "SOURCE_BUILD_PAYLOAD_WRITE_ALL_CALLED_KEY": "write_all_called",
                "SOURCE_BUILD_PAYLOAD_WRITE_CALLS_KEY": "write_calls",
                "SOURCE_BUILD_PAYLOAD_WRITE_METHOD_KEY": "method",
                "SOURCE_BUILD_PAYLOAD_VALUE_KEY": "value",
                "SOURCE_BUILD_PAYLOAD_CALLED_KEY": "called",
                "SOURCE_BUILD_PAYLOAD_ROTATION_KEY": "rotation",
                "SOURCE_BUILD_PAYLOAD_SET_EXPR_KEY": "set_expr",
                "SOURCE_BUILD_PAYLOAD_SET_CALLED_KEY": "set_called",
                "SOURCE_BUILD_PAYLOAD_SET_CALL_KEY": "set_call",
                "SOURCE_BUILD_PAYLOAD_GENERATED_OWNER_KEY": "generated_owner",
                "SOURCE_BUILD_PAYLOAD_RESULT_KEY": "result",
                "SOURCE_BUILD_PAYLOAD_CANONICAL_KEY": "canonical",
                "SOURCE_BUILD_PAYLOAD_MATCHES_KEY": "matches",
                "SOURCE_BUILD_PAYLOAD_DEFAULTED_ARG_KEY": "defaulted_arg",
            }
            for constant, key in aliases.items():
                body = body.replace(constant + ":", '"' + key + '":')
        return body

    def _facade_call_matches(self, bridge_body: str, facade_call: str) -> bool:
        if facade_call in bridge_body:
            return True
        consume_registry_call = facade_call.replace("return source_consume_", "return source_consume_module_registry.source_consume_", 1)
        return consume_registry_call in bridge_body

    def _assert_runtime_proof_uses_canonical_finalizer(self, source: str, proof_name: str) -> None:
        self.assertIn('const runtime_proof_state := preload("res://tools/runtime_proofs/RuntimeProofState.gd")', source)
        self.assertIn(f'runtime_proof_state.write_proof("{proof_name}", proof)', source)
        self.assertIn("await get_tree().process_frame", source)
        self.assertIn("get_tree().quit(runtime_proof_state.exit_code(proof))", source)
        self.assertNotIn("await get_tree().create_timer(60.0).timeout", source)
        self.assertNotIn("get_tree().quit(0)", source)

    def _assert_generated_bridge_moved_to_module(
        self,
        port_source: str,
        module_source: str,
        port_signature: str,
        module_signature: str,
        facade_call: str,
        script_load: str,
        generated_call: str,
        canonical_call: str,
        source_owner: str,
        generated_owner: str,
        matches_expr: str,
        source_owner_is_expression: bool = False,
    ) -> None:
        port_surface_source = self._port_compatibility_surface_source(port_source, port_signature)
        bridge_body = self._method_body(port_surface_source, port_signature)
        self.assertIn(port_signature, port_surface_source)
        if module_signature not in module_source and "source_consume_item_attribute_generated_state" in facade_call:
            module_source = (ROOT / "godot-mindustry" / "src" / "game" / "SourceConsumeItemAttributeGeneratedState.gd").read_text(encoding="utf-8")
        self.assertIn(module_signature, module_source)
        module_body = self._static_method_body(module_source, module_signature, normalize_build_payload_keys=False)
        self.assertTrue(self._facade_call_matches(bridge_body, facade_call), f"{facade_call} not found in facade body")
        self.assertNotIn(script_load, bridge_body)
        self.assertNotIn(generated_call.split(" = ", 1)[-1], bridge_body)
        if 'const source_generated_class_runtime := preload("res://src/game/SourceGeneratedClassRuntime.gd")' in module_source:
            java_name = script_load.split('"', 2)[1]
            method_segment = generated_call.split("instance.", 1)[1]
            generated_method = method_segment.split("(", 1)[0]
            generated_args = method_segment.split("(", 1)[1].rsplit(")", 1)[0]
            if java_name == "res://src/generated/classes/mindustry/world/blocks/payloads/BuildPayload.gd" and "class_name SourceBuildPayloadState" in module_source:
                build_payload_method_consts = {
                    "java_method_block_0": ("SOURCE_BUILD_PAYLOAD_BLOCK_JAVA_METHOD", "SOURCE_BUILD_PAYLOAD_BLOCK_GENERATED_OWNER"),
                    "java_constructor_BuildPayload_0": ("SOURCE_BUILD_PAYLOAD_CONSTRUCTOR_BLOCK_TEAM_JAVA_METHOD", "SOURCE_BUILD_PAYLOAD_CONSTRUCTOR_BLOCK_TEAM_GENERATED_OWNER"),
                    "java_constructor_BuildPayload_1": ("SOURCE_BUILD_PAYLOAD_CONSTRUCTOR_BUILD_JAVA_METHOD", "SOURCE_BUILD_PAYLOAD_CONSTRUCTOR_BUILD_GENERATED_OWNER"),
                    "java_method_contentEquals_3": ("SOURCE_BUILD_PAYLOAD_CONTENT_EQUALS_JAVA_METHOD", "SOURCE_BUILD_PAYLOAD_CONTENT_EQUALS_GENERATED_OWNER"),
                    "java_method_content_4": ("SOURCE_BUILD_PAYLOAD_CONTENT_JAVA_METHOD", "SOURCE_BUILD_PAYLOAD_CONTENT_GENERATED_OWNER"),
                    "java_method_requirements_7": ("SOURCE_BUILD_PAYLOAD_REQUIREMENTS_JAVA_METHOD", "SOURCE_BUILD_PAYLOAD_REQUIREMENTS_GENERATED_OWNER"),
                    "java_method_buildTime_8": ("SOURCE_BUILD_PAYLOAD_BUILD_TIME_JAVA_METHOD", "SOURCE_BUILD_PAYLOAD_BUILD_TIME_GENERATED_OWNER"),
                    "java_method_x_9": ("SOURCE_BUILD_PAYLOAD_X_JAVA_METHOD", "SOURCE_BUILD_PAYLOAD_X_GENERATED_OWNER"),
                    "java_method_y_10": ("SOURCE_BUILD_PAYLOAD_Y_JAVA_METHOD", "SOURCE_BUILD_PAYLOAD_Y_GENERATED_OWNER"),
                    "java_method_size_11": ("SOURCE_BUILD_PAYLOAD_SIZE_JAVA_METHOD", "SOURCE_BUILD_PAYLOAD_SIZE_GENERATED_OWNER"),
                    "java_method_write_13": ("SOURCE_BUILD_PAYLOAD_WRITE_JAVA_METHOD", "SOURCE_BUILD_PAYLOAD_WRITE_GENERATED_OWNER"),
                    "java_method_set_14": ("SOURCE_BUILD_PAYLOAD_SET_JAVA_METHOD", "SOURCE_BUILD_PAYLOAD_SET_GENERATED_OWNER"),
                }
                self.assertIn(generated_method, build_payload_method_consts)
                method_const, owner_const = build_payload_method_consts[generated_method]
                self.assertIn(f'var result = _build_payload_call({method_const}, {generated_args})', module_body)
                self.assertIn("static func _build_payload_call(generated_method: String, generated_args: Array) -> Variant:", module_source)
                self.assertIn("source_generated_class_runtime.call_java_method(BUILD_PAYLOAD_GENERATED_CLASS, generated_method, generated_args, null)", module_source)
                self.assertIn("SOURCE_BUILD_PAYLOAD_GENERATED_CLASS", module_source)
                self.assertIn('const source_payload_source_text_state := preload("res://src/game/SourcePayloadSourceTextState.gd")', module_source)
