    def _assert_runtime_bridge_moved_to_module(
        self,
        port_source: str,
        module_source: str,
        port_signature: str,
        module_signature: str,
        facade_call: str,
        java_name: str,
        generated_method: str,
        generated_args: str,
        canonical_call: str,
        source_owner: str,
        generated_owner: str,
        metadata_arg: str = "",
        source_owner_is_expression: bool = False,
        generated_owner_expression: str = "",
    ) -> None:
        port_surface_source = self._port_compatibility_surface_source(port_source, port_signature)
        bridge_body = self._method_body(port_surface_source, port_signature)
        module_body = self._static_method_body(module_source, module_signature)
        self.assertIn(port_signature, port_surface_source)
        self.assertIn(module_signature, module_source)
        self.assertIn(facade_call, bridge_body)
        self.assertNotIn("source_generated_class_runtime.call_java_method", bridge_body)
        self.assertNotIn("ResourceLoader.load(", bridge_body)
        self._assert_generated_bridge_uses_runtime(module_source, module_body, java_name, generated_method, generated_args, metadata_arg)
        self.assertIn(canonical_call, module_body)
        if source_owner_is_expression or source_owner.startswith("source_runtime_owner_registry."):
            expected_source_owner = source_owner
        elif source_owner.startswith("port_game."):
            expected_source_owner = "source_runtime_owner_registry.PORT_GAME_" + source_owner.removeprefix("port_game.").upper()
