    def _assert_source_consts_in_helper_not_port(self, port_source: str, helper_source: str, const_lines: list[str]) -> None:
        for const_line in const_lines:
            self.assertIn(const_line, helper_source)
            const_name = const_line.split(" := ", 1)[0].replace("const ", "")
            self.assertNotIn(f"const {const_name} :=", port_source)

    def _assert_source_consts_in_owner_not_helper(self, port_source: str, owner_source: str, helper_source: str, const_lines: list[str]) -> None:
        for const_line in const_lines:
            self.assertIn(const_line, owner_source)
            const_name = const_line.split(" := ", 1)[0].replace("const ", "")
            self.assertNotIn(f"const {const_name} :=", port_source)
            self.assertNotIn(const_line, helper_source)

    def _runtime_owner_registry_canonical_source(self) -> str:
        return "\n".join(source for _, source in self._runtime_owner_registry_chain_sources())

    def _runtime_owner_registry_chain_sources(self) -> list[tuple[Path, str]]:
        source_root = ROOT / "godot-mindustry" / "src" / "game"
        registry_path = source_root / "SourceRuntimeOwnerRegistry.gd"
        sources: list[tuple[Path, str]] = []
        seen: set[Path] = set()
        while registry_path.exists() and registry_path not in seen:
            seen.add(registry_path)
            source = registry_path.read_text(encoding="utf-8")
            sources.append((registry_path, source))
            match = re.search(r'^\ufeff?extends "res://src/game/([^"]+)"', source, flags=re.MULTILINE)
            if not match:
                break
            registry_path = source_root / match.group(1)

        return sources

    def _assert_runtime_owner_registry_chain(self) -> None:
        actual_chain = [path.name for path, _ in self._runtime_owner_registry_chain_sources()]
        self.assertEqual(self.RUNTIME_OWNER_REGISTRY_CHAIN, actual_chain)

    def _assert_runtime_owner_registry_values_unique(self) -> None:
        owner_values: dict[str, str] = {}
        duplicates: list[str] = []
        for source_path, source in self._runtime_owner_registry_chain_sources():
            for match in re.finditer(r'^const\s+(\w+)\s*:=\s*"([^"]+)"', source, flags=re.MULTILINE):
                const_name, owner_value = match.groups()
                if owner_value in owner_values:
                    duplicates.append(f"{owner_value}: {owner_values[owner_value]} and {const_name} in {source_path.name}")
                owner_values[owner_value] = const_name

        self.assertEqual([], duplicates)

    def _port_compatibility_surface_source(self, port_source: str, signature: str) -> str:
        if signature in port_source or "class_name PortGame" not in port_source:
            return port_source
        return port_source + "\n" + self._port_game_port_bridge_chain_source()

    def test_source_state_source_owners_use_runtime_owner_registry(self):
        offenders: list[str] = []
        source_root = ROOT / "godot-mindustry" / "src" / "game"
        for source_path in sorted(source_root.rglob("*.gd")):
            if source_path.name == "SourceRuntimeOwnerRegistry.gd":
                continue
            for line_no, line in enumerate(source_path.read_text(encoding="utf-8").splitlines(), 1):
                if '"source_owner": "' in line:
                    offenders.append(f"{source_path.relative_to(ROOT)}:{line_no}: {line.strip()}")

        self.assertEqual([], offenders)

    def test_runtime_owner_registry_routes_block_domain_through_canonical_registry(self):
        registry = ROOT / "godot-mindustry" / "src" / "game" / "SourceRuntimeOwnerRegistry.gd"
        power_registry = ROOT / "godot-mindustry" / "src" / "game" / "SourceRuntimeOwnerPowerRegistry.gd"
