    def test_unit_payload_dump_generated_bridge_uses_unit_payload_registry_metadata(self):
        unit_payload_registry = ROOT / "godot-mindustry" / "src" / "game" / "SourceRuntimeOwnerUnitPayloadRegistry.gd"
        source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourcePayloadSourceTextState.gd"
        generated_bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitPayloadDumpGeneratedBridgeState.gd"
        unit_payload_registry_source = unit_payload_registry.read_text(encoding="utf-8") if unit_payload_registry.exists() else ""
        source_text_source = source_text.read_text(encoding="utf-8") if source_text.exists() else ""
        generated_bridge_source = generated_bridge.read_text(encoding="utf-8")

        self.assertIn('const SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_METHOD := "java_method_dump_13"', source_text_source)
        self.assertIn('const SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_OWNER := "unit_payload.java_method_dump_13"', source_text_source)
        self.assertIn('const source_payload_source_text_state := preload("res://src/game/SourcePayloadSourceTextState.gd")', unit_payload_registry_source)
        self.assertIn("const SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_METHOD := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_METHOD", unit_payload_registry_source)
        self.assertIn("const SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_OWNER := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_OWNER", unit_payload_registry_source)
        self.assertNotIn('const SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_METHOD := "java_method_dump_13"', unit_payload_registry_source)
        self.assertNotIn('const SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_OWNER := "unit_payload.java_method_dump_13"', unit_payload_registry_source)
        self.assertNotIn('const SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_METHOD := "java_method_dump_13"', generated_bridge_source)
        self.assertNotIn('const SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_OWNER := "unit_payload.java_method_dump_13"', generated_bridge_source)
        self.assertIn("const SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_METHOD := source_runtime_owner_registry.SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_METHOD", generated_bridge_source)
        self.assertIn("const SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_OWNER := source_runtime_owner_registry.SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_OWNER", generated_bridge_source)

