    def _source_building_destruction_helper_source(self):
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingDestructionState.gd"
        destruction_source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingDestructionSourceTextState.gd"
        building_source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingSourceTextState.gd"
        reactive = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingDestructionReactiveState.gd"
        generated = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingDestructionGeneratedState.gd"
        source = ""
        if destruction_source_text.exists():
            source += destruction_source_text.read_text(encoding="utf-8") + "\n"
        if building_source_text.exists():
            source += building_source_text.read_text(encoding="utf-8") + "\n"
        if reactive.exists():
            source += reactive.read_text(encoding="utf-8") + "\n"
        if generated.exists():
            source += generated.read_text(encoding="utf-8") + "\n"
        source += helper.read_text(encoding="utf-8")
        return source

    def test_remaining_generated_bridges_use_canonical_source_text_headquarters(self):
        cases = [
            {
                "module": "SourceBuildingDestructionState.gd",
                "headquarter": 'const source_block_source_text_state := preload("res://src/game/SourceBlockSourceTextState.gd")',
                "constant": "SOURCE_BUILD_GENERATED_CLASS",
                "alias": "const SOURCE_BUILD_GENERATED_CLASS := source_block_source_text_state.SOURCE_BUILD_GENERATED_CLASS",
                "helper_signature": "static func _build_call(generated_method: String, generated_args: Array) -> Variant:",
                "runtime_call": "source_generated_class_runtime.call_java_method(SOURCE_BUILD_GENERATED_CLASS, generated_method, generated_args, null)",
                "helper_call": "var result = _build_call(SOURCE_BUILDING_DESTRUCTION_BEGIN_BREAK_JAVA_METHOD, [valid_break, tile_has_building, prev_healthf, previous_rotation, previous_instant_deconstruct, previous_size, unit_has_controller_name, controller_name])",
                "literal": 'call_java_method("res://src/generated/classes/mindustry/world/Build.gd"',
            },
            {
                "module": "SourceBuildingDisplayState.gd",
                "headquarter": 'const source_building_source_text_state := preload("res://src/game/SourceBuildingSourceTextState.gd")',
                "constant": "SOURCE_BUILDING_COMP_GENERATED_CLASS",
                "alias": "const SOURCE_BUILDING_COMP_GENERATED_CLASS := source_building_source_text_state.SOURCE_BUILDING_COMP_GENERATED_CLASS",
                "helper_signature": "static func _building_comp_call(generated_method: String, generated_args: Array) -> Variant:",
                "runtime_call": "source_generated_class_runtime.call_java_method(SOURCE_BUILDING_COMP_GENERATED_CLASS, generated_method, generated_args, null)",
                "helper_call": "var result = _building_comp_call(SOURCE_BUILDING_DISPLAY_UI_GATES_JAVA_METHOD, [block_ui_icon, localized_name, team_is_derelict, team_is_player, team_emoji, derelict_label, block_category, block_display_flow, net_active, has_last_accessed])",
                "literal": 'call_java_method("res://src/generated/classes/mindustry/entities/comp/BuildingComp.gd"',
            },
            {
                "module": "SourceBuildingTetherState.gd",
                "headquarter": 'const source_entity_comp_source_text_state := preload("res://src/game/SourceEntityCompSourceTextState.gd")',
                "constant": "SOURCE_BUILDING_TETHER_COMP_GENERATED_CLASS",
                "alias": "const SOURCE_BUILDING_TETHER_COMP_GENERATED_CLASS := source_entity_comp_source_text_state.SOURCE_BUILDING_TETHER_COMP_GENERATED_CLASS",
                "helper_signature": "static func _building_tether_comp_call(generated_method: String, generated_args: Array) -> Variant:",
                "runtime_call": "source_generated_class_runtime.call_java_method(SOURCE_BUILDING_TETHER_COMP_GENERATED_CLASS, generated_method, generated_args, null)",
                "helper_call": "var result = _building_tether_comp_call(SOURCE_BUILDING_TETHER_UPDATE_JAVA_METHOD, [building_exists, building_is_valid, building_team_value, team_value, unit_id])",
                "literal": 'call_java_method("res://src/generated/classes/mindustry/entities/comp/BuildingTetherComp.gd"',
            },
            {
                "module": "SourceTurretOutputsItemsState.gd",
                "headquarter": 'const source_turret_source_text_state := preload("res://src/game/SourceTurretSourceTextState.gd")',
                "constant": "SOURCE_TURRET_GENERATED_CLASS",
                "alias": "const SOURCE_TURRET_GENERATED_CLASS := source_turret_source_text_state.SOURCE_TURRET_GENERATED_CLASS",
                "helper_signature": "static func _turret_call(generated_method: String, generated_args: Array) -> Variant:",
                "runtime_call": "source_generated_class_runtime.call_java_method(SOURCE_TURRET_GENERATED_CLASS, generated_method, generated_args, null)",
                "helper_call": "var result = _turret_call(SOURCE_TURRET_OUTPUTS_ITEMS_JAVA_METHOD, [])",
                "literal": 'call_java_method("res://src/generated/classes/mindustry/world/blocks/defense/turrets/Turret.gd"',
            },
        ]
        for case in cases:
            module_path = ROOT / "godot-mindustry" / "src" / "game" / case["module"]
            module_source = module_path.read_text(encoding="utf-8")
            self.assertIn(case["headquarter"], module_source)
            self.assertIn(case["alias"], module_source)
            self.assertIn(case["helper_signature"], module_source)
            self.assertIn(case["runtime_call"], module_source)
            self.assertIn(case["helper_call"], module_source)
            self.assertNotIn(case["literal"], module_source)

