        self.assertIn("static func _liquid_turret_call(generated_method: String, generated_args: Array) -> Variant:", module_source)
        self.assertIn("source_generated_class_runtime.call_java_method(SOURCE_LIQUID_TURRET_GENERATED_CLASS, generated_method, generated_args, null)", module_source)
        if "class_name SourceLiquidTurretInitState" in module_source and generated_method == "java_method_init_2":
            self.assertIn("const SOURCE_LIQUID_TURRET_INIT_JAVA_METHOD := source_turret_source_text_state.SOURCE_LIQUID_TURRET_INIT_JAVA_METHOD", module_source)
            self.assertIn("const SOURCE_LIQUID_TURRET_INIT_GENERATED_OWNER := source_turret_source_text_state.SOURCE_LIQUID_TURRET_INIT_GENERATED_OWNER", module_source)
