            self.assertIn("var result = _liquid_turret_call(SOURCE_LIQUID_TURRET_INIT_JAVA_METHOD, [" + generated_args + "])", module_body)
            self.assertIn('"generated_owner": SOURCE_LIQUID_TURRET_INIT_GENERATED_OWNER', module_body)
