    def test_campaign_shell_state_uses_canonical_bundle_planets_and_source_owner(self):
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceCampaignShellState.gd"
        owner_registry = ROOT / "godot-mindustry" / "src" / "game" / "SourceRuntimeOwnerGameplayRegistry.gd"
        bundle = ROOT / "godot-mindustry" / "assets" / "core" / "assets" / "bundles" / "bundle.properties"
        source = module.read_text(encoding="utf-8") if module.exists() else ""
        owner_source = owner_registry.read_text(encoding="utf-8")
        bundle_source = bundle.read_text(encoding="utf-8")

        self.assertTrue(module.exists(), "SourceCampaignShellState.gd must own campaign shell canonical state")
        self.assertIn("class_name SourceCampaignShellState", source)
        self.assertIn('const SOURCE_BUNDLE_PATH := "res://assets/core/assets/bundles/bundle.properties"', source)
        self.assertIn('const SOURCE_SERPULO_PLANET_SPRITE := "res://assets/core/assets/sprites/planets/serpulo.png"', source)
        self.assertIn('const SOURCE_EREKIR_PLANET_SPRITE := "res://assets/core/assets/sprites/planets/erekir.png"', source)
        self.assertIn('const SOURCE_SERPULO_MAP_ROOT := "res://assets/core/assets/maps/serpulo"', source)
        self.assertIn("static func bundle_text_state(bundle_text: String) -> Dictionary:", source)
        self.assertIn("static func campaign_shell_state(bundle_text: String) -> Dictionary:", source)
        self.assertIn('"source_owner": source_runtime_owner_registry.PORT_GAME_SOURCE_CAMPAIGN_SHELL_STATE', source)
        self.assertIn('PORT_GAME_SOURCE_CAMPAIGN_SHELL_STATE := "port_game.source_campaign_shell_state"', owner_source)
        for key in ("campaign.select", "campaign.serpulo", "campaign.erekir", "planetmap", "launchcore"):
            self.assertIn(key, bundle_source)
            self.assertIn(f'"{key}"', source)
        self.assertNotIn("Mindustry Godot slice", source)

