        self.assertIn('"top_block_name_matches": int(tile_state.get("block_name_counts", {}).get("spore-wall", 0)) == 27841', proof_source)
        self.assertIn('"core_block_name_matches": int(tile_state.get("block_name_counts", {}).get("core-shard", 0)) == 9', proof_source)
        self.assertIn('"initial_build_carries_tile_state": initial_build_tile_state == tile_state', proof_source)
        self.assertIn('"registry_valid": bool(registry_state.get("errors", []).is_empty())', proof_source)
