    def _actual_port_game_port_bridge_chain(self):
        game_dir = ROOT / "godot-mindustry" / "src" / "game"
        chain = []
        current = "PortGame.gd"
        seen = set()
        while current and current not in seen:
            seen.add(current)
            chain.append(current)
            source_path = game_dir / current
            if not source_path.exists():
                break
            first_line = source_path.read_text(encoding="utf-8").splitlines()[0]
            marker = 'extends "res://src/game/'
            if marker not in first_line:
                break
            current = first_line.split(marker, 1)[1].split('"', 1)[0]
        return chain

