    def test_port_game_requires_playable_content_tile_size_from_ssot(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        runtime_config = ROOT / "godot-mindustry" / "src" / "game" / "SourceGameConfigRuntimeState.gd"
        proof = ROOT / "godot-mindustry" / "tools" / "runtime_proofs" / "GameConfigRuntimeModuleProof.gd"
        source = self._port_game_unit_payload_dump_source()
        runtime_source = runtime_config.read_text(encoding="utf-8") if runtime_config.exists() else ""
        proof_source = proof.read_text(encoding="utf-8") if proof.exists() else ""

        self.assertTrue(runtime_config.exists(), "source_game_config_runtime_state.gd must own playable_content config bootstrap wiring")
        self.assertTrue(proof.exists(), "GameConfigRuntimeModuleProof.gd must prove playable_content config bootstrap wiring")
        self.assertIn('const source_game_config_runtime_state := preload("res://src/game/SourceGameConfigRuntimeState.gd")', source)
        self.assertIn("source_game_config_runtime_state.load_config(self)", source)
        self.assertIn("class_name SourceGameConfigRuntimeState", runtime_source)
        self.assertIn("static func load_config(game: Object) -> void:", runtime_source)
        self.assertIn('const source_ssot_accessor_runtime_state := preload("res://src/game/SourceSsotAccessorRuntimeState.gd")', runtime_source)
        self.assertIn('var document := source_ssot_accessor_runtime_state.playable_content_document_state()', runtime_source)
        self.assertNotIn('var document := source_ssot_catalog.load_document("playable_content")', runtime_source)
        self.assertIn('if not bool(document.get("loaded", false)):', runtime_source)
        self.assertIn('game.set("tile_size", int(config["tile_size"]))', runtime_source)
        self.assertIn("GAME_CONFIG_RUNTIME_MODULE_PROOF", proof_source)
        self.assertIn("source_game_config_runtime_state.load_config(game)", proof_source)
        self.assertIn('const source_ssot_accessor_runtime_state := preload("res://src/game/SourceSsotAccessorRuntimeState.gd")', proof_source)
        self.assertIn("source_ssot_accessor_runtime_state.canonical_headquarter_registry_state()", proof_source)
        self.assertNotIn('preload("res://src/generated/SourceSsotCatalog.gd")', proof_source)
        self.assertIn('"one_headquarter_per_ssot"', proof_source)
        self.assertIn('"registry_valid"', proof_source)
        self.assertNotIn('if not config.has("tile_size"):', source)
