    def test_turret_stats_bars_delegates_ammo_stats_bars_to_module(self):
        facade = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretStatsBarsState.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretAmmoStatsBarsState.gd"
