    def test_source_generated_class_runtime_rejects_container_scalar_mismatches_before_equality(self):
        runtime = ROOT / "godot-mindustry" / "src" / "game" / "SourceGeneratedClassRuntime.gd"
        source = runtime.read_text(encoding="utf-8")
        generated_body = self._static_method_body(source, "static func generated_state_matches_generated_subset(result: Variant, canonical: Variant) -> bool:")
        canonical_body = self._static_method_body(source, "static func generated_state_matches_canonical_subset(result: Variant, canonical: Variant, ignored_keys: Array = []) -> bool:")

        self.assertIn("static func generated_state_matches_generated_subset(result: Variant, canonical: Variant) -> bool:", source)
        self.assertIn("static func generated_state_matches_canonical_subset(result: Variant, canonical: Variant, ignored_keys: Array = []) -> bool:", source)
        self.assertIn("if (result is Dictionary) != (canonical is Dictionary):", generated_body)
        self.assertIn("if (result is Array) != (canonical is Array):", generated_body)
        self.assertIn("if (result is Dictionary) != (canonical is Dictionary):", canonical_body)
        self.assertIn("if (result is Array) != (canonical is Array):", canonical_body)
        self.assertIn("if ignored_keys.has(key):", canonical_body)
        self.assertIn("generated_state_matches_canonical_subset(result.get(key), canonical.get(key), [])", canonical_body)
        self.assertIn("\treturn false", generated_body)
        self.assertIn("\treturn false", canonical_body)

    def test_port_game_generated_state_matchers_delegate_to_shared_runtime(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        runtime = ROOT / "godot-mindustry" / "src" / "game" / "SourceGeneratedClassRuntime.gd"
        source = port_game.read_text(encoding="utf-8") + "\n" + self._port_game_port_bridge_chain_source()
        runtime_source = runtime.read_text(encoding="utf-8")
        subset_body = self._method_body(source, "func generated_state_matches_generated_subset(result: Variant, canonical: Dictionary, ignored_keys: Array = []) -> bool:")
        nan_body = self._method_body(source, "func generated_state_matches_generated_subset_or_nan(result: Variant, canonical: Dictionary, nan_key: String, identity_key: String, ignored_keys: Array = []) -> bool:")

        self.assertIn('const source_generated_class_runtime := preload("res://src/game/SourceGeneratedClassRuntime.gd")', source)
        self.assertIn("static func generated_subset_ignored_keys(ignored_keys: Array = []) -> Array:", runtime_source)
        self.assertIn('var runtime_ignored_keys := ["source_owner"]', runtime_source)
        self.assertIn("runtime_ignored_keys.append_array(ignored_keys)", runtime_source)
        self.assertIn("static func generated_state_matches_generated_subset_ignoring_source_owner(result: Variant, canonical: Variant, ignored_keys: Array = []) -> bool:", runtime_source)
        self.assertIn("return generated_state_matches_canonical_subset(result, canonical, generated_subset_ignored_keys(ignored_keys))", runtime_source)
        self.assertIn("static func generated_state_matches_generated_subset_or_nan_ignoring_source_owner(result: Variant, canonical: Variant, nan_key: String, identity_key: String, ignored_keys: Array = []) -> bool:", runtime_source)
        self.assertIn("return generated_state_matches_canonical_subset_or_nan(result, canonical, nan_key, identity_key, generated_subset_ignored_keys(ignored_keys))", runtime_source)
        self.assertIn("return source_generated_class_runtime.generated_state_matches_generated_subset_ignoring_source_owner(result, canonical, ignored_keys)", subset_body)
        self.assertNotIn('var runtime_ignored_keys := ["source_owner"]', subset_body)
        self.assertNotIn("runtime_ignored_keys.append_array(ignored_keys)", subset_body)
        self.assertNotIn("for key in canonical.keys()", subset_body)
        self.assertNotIn("result.has(key)", subset_body)
        self.assertIn("return source_generated_class_runtime.generated_state_matches_generated_subset_or_nan_ignoring_source_owner(result, canonical, nan_key, identity_key, ignored_keys)", nan_body)
        self.assertNotIn('var runtime_ignored_keys := ["source_owner"]', nan_body)
        self.assertNotIn("runtime_ignored_keys.append_array(ignored_keys)", nan_body)
        self.assertNotIn("result_nan", nan_body)
        self.assertNotIn("canonical_nan", nan_body)

    def test_port_game_routes_root_facades_through_port_bridge(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourcePortGameFacadePortBridge.gd"
        port_source = port_game.read_text(encoding="utf-8")
        bridge_source = bridge.read_text(encoding="utf-8") if bridge.exists() else ""

        self.assertTrue(bridge.exists(), "SourcePortGameFacadePortBridge.gd must own root PortGame compatibility facades")
        self.assertIn('extends "res://src/game/SourcePortGameFacadePortBridge.gd"', port_source)
        self.assertIn('extends "res://src/game/SourcePortGameRootStatePortBridge.gd"', bridge_source)
        self.assertIn("SourcePortGameFacadePortBridge.gd", self._actual_port_game_port_bridge_chain())
        self.assertNotIn("class_name SourcePortGameFacadePortBridge", bridge_source)

        moved_preloads = (
            "source_generated_class_runtime",
            "source_block_footprint",
            "source_block_placement",
            "source_projector_boost_state",
        )
        for preload_name in moved_preloads:
            with self.subTest(preload=preload_name):
                self.assertIn(f"const {preload_name} := preload(", bridge_source)
                self.assertNotIn(f"const {preload_name} := preload(", port_source)

        expected_delegates = {
            "func place_selected_block_at_mouse() -> void:": "place_selected_block_at_world(get_global_mouse_position())",
            "func place_selected_block_at_cell(x: int, y: int) -> bool:": "return place_selected_block_at_world(grid_to_world(Vector2i(x, y)))",
            "func place_selected_block_at_world(world_pos: Vector2) -> bool:": "return source_block_placement.game_place_selected_block_at_world(self, world_pos)",
            "func add_source_block(parent: Node, block_id: String, cell: Vector2i) -> void:": "source_block_placement.add_source_block(self, parent, block_id, cell)",
            "func occupied_cells(cell: Vector2i, block) -> Array[Vector2i]:": "return source_block_footprint.occupied_cells(cell, block_size(block))",
            "func can_place_block_at_cell(block, cell: Vector2i) -> bool:": 'var state := source_block_placement.game_can_place_state(self, block, cell)',
            "func boost_mend_projector_at_cell(x: int, y: int) -> bool:": "return source_projector_boost_state.apply_projector_boost_at_cell(self, x, y, source_projector_boost_state.PROJECTOR_KIND_MEND, booster_items, optional_efficiency)",
            "func boost_overdrive_projector_at_cell(x: int, y: int) -> bool:": "return source_projector_boost_state.apply_projector_boost_at_cell(self, x, y, source_projector_boost_state.PROJECTOR_KIND_OVERDRIVE, booster_items, optional_efficiency)",
            "func generated_state_matches_generated_subset(result: Variant, canonical: Dictionary, ignored_keys: Array = []) -> bool:": "return source_generated_class_runtime.generated_state_matches_generated_subset_ignoring_source_owner(result, canonical, ignored_keys)",
            "func generated_state_matches_generated_subset_or_nan(result: Variant, canonical: Dictionary, nan_key: String, identity_key: String, ignored_keys: Array = []) -> bool:": "return source_generated_class_runtime.generated_state_matches_generated_subset_or_nan_ignoring_source_owner(result, canonical, nan_key, identity_key, ignored_keys)",
        }
        for signature, delegate in expected_delegates.items():
            with self.subTest(signature=signature):
                self.assertNotIn(signature, port_source)
                method_body = self._method_body(bridge_source, signature)
                self.assertIn(delegate, method_body)
                if signature.startswith("func boost_mend_projector_at_cell"):
                    self.assertIn('var booster_items: Dictionary = get("mend_projector_booster_items")', method_body)
                    self.assertIn('var optional_efficiency: Dictionary = get("mend_projector_optional_efficiency")', method_body)
                if signature.startswith("func boost_overdrive_projector_at_cell"):
                    self.assertIn('var booster_items: Dictionary = get("overdrive_projector_booster_items")', method_body)
                    self.assertIn('var optional_efficiency: Dictionary = get("overdrive_projector_optional_efficiency")', method_body)

