                self.assertIsNotNone(re.search(pattern, bridge_source, flags=re.MULTILINE), f"{state_name} must live in the combat state bridge")
                self.assertIsNone(re.search(pattern, root_source, flags=re.MULTILINE), f"{state_name} must not live in the root state bridge")

