    def test_source_thermal_generator_method_literals_are_canonical_source_text(self):
        source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceThermalGeneratorSourceTextState.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceThermalGeneratorState.gd"
        source_text_source = source_text.read_text(encoding="utf-8") if source_text.exists() else ""
        module_source = module.read_text(encoding="utf-8")

        self.assertTrue(source_text.exists(), "SourceThermalGeneratorSourceTextState.gd must own ThermalGenerator source-text literals")
        self.assertIn("class_name SourceThermalGeneratorSourceTextState", source_text_source)
        for const_name, literal in {
            "SOURCE_THERMAL_GENERATOR_DRAW_LIGHT_METHOD": '"public void drawLight(){"',
            "SOURCE_THERMAL_GENERATOR_SET_STATS_METHOD": '"public void setStats(){"',
        }.items():
            with self.subTest(const_name=const_name):
                self.assertIn(f"const {const_name} := {literal}", source_text_source)
                self.assertIn(f"const {const_name} := source_thermal_generator_source_text_state.{const_name}", module_source)
                self.assertNotIn(f"const {const_name} := {literal}", module_source)

        self.assertIn('const source_thermal_generator_source_text_state := preload("res://src/game/SourceThermalGeneratorSourceTextState.gd")', module_source)
        self.assertNotIn('"method": "public void drawLight(){', module_source)
        self.assertNotIn('"method": "public void setStats(){', module_source)

