        bridge_source = bridge.read_text(encoding="utf-8") if bridge.exists() else ""

        self.assertTrue(bridge.exists(), "SourcePlacedPowerRuntimePortBridge.gd must own placed power runtime wrappers")
        self.assertIn('extends "res://src/game/SourcePlacedPowerRuntimePortBridge.gd"', world_bridge_source)
        self.assertIn('extends "res://src/game/SourceBulletTypePortBridge.gd"', bridge_source)
        self.assertIn("SourcePlacedPowerRuntimePortBridge.gd", self._actual_port_game_port_bridge_chain())
        self.assertIn('const source_placed_power_graph_state := preload("res://src/game/SourcePlacedPowerGraphState.gd")', bridge_source)
        self.assertIn('const source_placed_power_battery_runtime_state := preload("res://src/game/SourcePlacedPowerBatteryRuntimeState.gd")', bridge_source)
        self.assertIn('const source_placed_power_distribution_runtime_state := preload("res://src/game/SourcePlacedPowerDistributionRuntimeState.gd")', bridge_source)
        self.assertNotIn('const source_placed_power_graph_state := preload("res://src/game/SourcePlacedPowerGraphState.gd")', port_source)
        self.assertNotIn('const source_placed_power_battery_runtime_state := preload("res://src/game/SourcePlacedPowerBatteryRuntimeState.gd")', port_source)
        self.assertNotIn('const source_placed_power_distribution_runtime_state := preload("res://src/game/SourcePlacedPowerDistributionRuntimeState.gd")', port_source)

        delegations = {
            "func placed_power_graph_role_counts() -> Dictionary:": "\treturn source_placed_power_graph_state.game_role_counts_state(self)",
            "func placed_power_needed_state() -> Dictionary:": "\treturn source_placed_power_graph_state.game_needed_state(self)",
            "func placed_power_produced_state() -> Dictionary:": "\treturn source_placed_power_graph_state.game_produced_state(self)",
            "func placed_power_battery_state() -> Dictionary:": "\treturn source_placed_power_graph_state.game_battery_state(self)",
            "func placed_power_battery_runtime_state() -> Dictionary:": "\treturn source_placed_power_battery_runtime_state.game_summary_state(self)",
            "func placed_power_distribution_runtime_state() -> Dictionary:": "\treturn source_placed_power_distribution_runtime_state.game_summary_state(self)",
            "func placed_power_runtime_state() -> Dictionary:": "\treturn source_placed_power_graph_state.game_runtime_state(self)",
        }
        for signature, delegation in delegations.items():
            self.assertNotIn(signature, port_source)
            self.assertIn(signature, bridge_source)
            self.assertIn(delegation, self._method_body(bridge_source, signature))

