    def test_source_consume_power_state_source_text_owns_literals(self):
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceConsumePowerState.gd"
        source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceConsumeSourceTextState.gd"
        module_source = module.read_text(encoding="utf-8")
