        self.assertTrue(source_text.exists(), "SourceConsumeSourceTextState.gd must own consumer source-text literals")
        self.assertIn("class_name SourceConsumeSourceTextState", source_text_source)
        self.assertIn('const source_consume_source_text_state := preload("res://src/game/SourceConsumeSourceTextState.gd")', module_source)
        for const_name, literal_value in {
            "SOURCE_CONSUME_POWER_SOURCE": "core/src/mindustry/world/consumers/ConsumePower.java",
            "SOURCE_CONSUME_POWER_CONDITION_SOURCE": "core/src/mindustry/world/consumers/ConsumePowerCondition.java",
            "SOURCE_CONSUME_POWER_DYNAMIC_SOURCE": "core/src/mindustry/world/consumers/ConsumePowerDynamic.java",
            "SOURCE_CONSUME_POWER_BLOCK_SOURCE": "core/src/mindustry/world/Block.java",
            "SOURCE_CONSUME_POWER_REQUESTED_POWER_METHOD": "public float requestedPower(Building entity){",
            "SOURCE_CONSUME_POWER_REQUESTED_POWER_BUFFERED_EXPR": "(1f - entity.power.status) * capacity",
            "SOURCE_CONSUME_POWER_REQUESTED_POWER_UNBUFFERED_EXPR": "usage * (entity.shouldConsume() ? 1f : 0f)",
            "SOURCE_CONSUME_POWER_APPLY_METHOD": "public void apply(Block block){",
            "SOURCE_CONSUME_POWER_APPLY_HAS_POWER_ASSIGNMENT_EXPR": "block.hasPower = true;",
            "SOURCE_CONSUME_POWER_APPLY_CONS_POWER_ASSIGNMENT_EXPR": "block.consPower = this;",
            "SOURCE_CONSUME_POWER_IGNORE_METHOD": "public boolean ignore(){",
            "SOURCE_CONSUME_POWER_IGNORE_RETURN_EXPR": "return buffered;",
            "SOURCE_CONSUME_POWER_EFFICIENCY_METHOD": "public float efficiency(Building build){",
            "SOURCE_CONSUME_POWER_EFFICIENCY_RETURN_EXPR": "return build.power.status;",
            "SOURCE_CONSUME_POWER_DISPLAY_METHOD": "public void display(Stats stats){",
            "SOURCE_CONSUME_POWER_DISPLAY_BUFFERED_GUARD_EXPR": "if(buffered){",
            "SOURCE_CONSUME_POWER_DISPLAY_USAGE_GUARD_EXPR": "}else if(usage > 0f){",
            "SOURCE_CONSUME_POWER_DISPLAY_CAPACITY_STATS_ADD_EXPR": "stats.add(Stat.powerCapacity, capacity, StatUnit.none);",
            "SOURCE_CONSUME_POWER_DISPLAY_USAGE_STATS_ADD_EXPR": "stats.add(Stat.powerUse, usage * 60f, StatUnit.powerSecond);",
            "SOURCE_CONSUME_POWER_STAT_POWER_USE": "Stat.powerUse",
            "SOURCE_CONSUME_POWER_STAT_POWER_CAPACITY": "Stat.powerCapacity",
            "SOURCE_CONSUME_POWER_STAT_UNIT_POWER_SECOND": "StatUnit.powerSecond",
            "SOURCE_CONSUME_POWER_STAT_UNIT_NONE": "StatUnit.none",
            "SOURCE_CONSUME_POWER_CONDITION_REQUESTED_POWER_METHOD": "public float requestedPower(Building entity){",
            "SOURCE_CONSUME_POWER_CONDITION_REQUESTED_POWER_RETURN_EXPR": "return consume.get(entity) ? usage : 0f;",
            "SOURCE_CONSUME_POWER_DYNAMIC_REQUESTED_POWER_METHOD": "public float requestedPower(Building entity){",
            "SOURCE_CONSUME_POWER_DYNAMIC_REQUESTED_POWER_RETURN_EXPR": "return usage.get(entity);",
            "SOURCE_CONSUME_POWER_DYNAMIC_DISPLAY_METHOD": "public void display(Stats stats){",
            "SOURCE_CONSUME_POWER_DYNAMIC_DISPLAY_GUARD_EXPR": "if(displayedPowerUsage != 0f){",
            "SOURCE_CONSUME_POWER_DYNAMIC_DISPLAY_STATS_ADD_EXPR": "stats.add(Stat.powerUse, displayedPowerUsage * 60f, StatUnit.powerSecond);",
        }.items():
            literal_token = literal_value.replace('"', '\\"')
            self.assertIn(f'const {const_name} := "{literal_token}"', source_text_source)
            self.assertIn(f"const {const_name} := source_consume_source_text_state.{const_name}", module_source)
            self.assertNotIn(f'const {const_name} := "{literal_token}"', module_source)

