                'var script = load("res://src/generated/classes/mindustry/world/consumers/ConsumeItemDynamic.gd")',
                "var result = instance.java_method_rebuild_2([item_ids, item_stack_amounts, item_amounts, building_has_items, multiplier_get_build])",
                "var canonical = source_consume_item_dynamic_state.rebuild_state(item_ids, item_stack_amounts, item_amounts, building_has_items, multiplier_get_build, source_ui_pad_right)",
                "source_runtime_owner_registry.PORT_GAME_SOURCE_CONSUME_ITEM_DYNAMIC_REBUILD_STATE",
                "consume_item_dynamic.rebuild",
