        self.assertNotIn('call_java_method(SOURCE_CONSUME_ITEM_DYNAMIC_GENERATED_CLASS, "java_constructor_ConsumeItemDynamic_0"', generated_module_source)
        self.assertNotIn('call_java_method(SOURCE_CONSUME_ITEM_DYNAMIC_GENERATED_CLASS, "java_method_apply_0"', generated_module_source)
        self.assertNotIn('call_java_method(SOURCE_CONSUME_ITEM_DYNAMIC_GENERATED_CLASS, "java_method_build_1"', generated_module_source)
        self.assertNotIn('call_java_method(SOURCE_CONSUME_ITEM_DYNAMIC_GENERATED_CLASS, "java_method_rebuild_2"', generated_module_source)
