    def test_source_power_graph_battery_distribution_logic_is_owned_by_module(self):
        facade = ROOT / "godot-mindustry" / "src" / "game" / "SourcePowerGraphBalanceState.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourcePowerGraphBatteryDistributionState.gd"

        self.assertTrue(module.exists(), "SourcePowerGraphBatteryDistributionState.gd must own PowerGraph battery/distribution logic")
        facade_source = facade.read_text(encoding="utf-8")
        module_source = module.read_text(encoding="utf-8")

        self.assertIn("class_name SourcePowerGraphBatteryDistributionState", module_source)
        self.assertIn('const source_power_graph_battery_distribution_state := preload("res://src/game/SourcePowerGraphBatteryDistributionState.gd")', facade_source)
        expected_delegations = {
            "static func battery_state(batteries: Array) -> Dictionary:": "return source_power_graph_battery_distribution_state.battery_state(batteries)",
            "static func use_batteries_state(batteries: Array, needed: float) -> Dictionary:": "return source_power_graph_battery_distribution_state.use_batteries_state(batteries, needed)",
            "static func charge_batteries_state(batteries: Array, excess: float) -> Dictionary:": "return source_power_graph_battery_distribution_state.charge_batteries_state(batteries, excess)",
            "static func distribute_power_state(consumers: Array, needed: float, produced: float, charged: bool, last_power_stored: float) -> Dictionary:": "return source_power_graph_battery_distribution_state.distribute_power_state(consumers, needed, produced, charged, last_power_stored)",
            "static func update_battery_distribute_state(consumers: Array, producers: Array, batteries: Array, power_needed: float, power_produced: float, last_power_produced: float, last_power_stored: float) -> Dictionary:": "return source_power_graph_battery_distribution_state.update_battery_distribute_state(consumers, producers, batteries, power_needed, power_produced, last_power_produced, last_power_stored)",
        }
        for signature, delegation in expected_delegations.items():
            with self.subTest(signature=signature):
                self.assertIn(signature, module_source)
                self.assertIn(delegation, self._method_body(facade_source, signature))

        facade_literals = self._method_body(facade_source, "static func update_battery_distribute_state(consumers: Array, producers: Array, batteries: Array, power_needed: float, power_produced: float, last_power_produced: float, last_power_stored: float) -> Dictionary:")
        self.assertNotIn('"nonempty_guard": "if(!(consumers.size == 0 && producers.size == 0 && batteries.size == 0)){"', facade_literals)
        for signature in expected_delegations.keys():
            facade_body = self._method_body(facade_source, signature)
            self.assertNotIn("var source_batteries: Array = []", facade_body)
            self.assertNotIn("var source_consumers: Array = []", facade_body)
        self.assertIn('"nonempty_guard": SOURCE_POWER_GRAPH_UPDATE_NONEMPTY_GUARD', module_source)
        self.assertIn('"coverage_expr": SOURCE_POWER_GRAPH_DISTRIBUTE_POWER_COVERAGE_EXPR', module_source)
        self.assertIn("const SOURCE_POWER_GRAPH_UPDATE_NONEMPTY_GUARD := source_power_graph_source_text_state.SOURCE_POWER_GRAPH_UPDATE_NONEMPTY_GUARD", module_source)
        self.assertIn("const SOURCE_POWER_GRAPH_DISTRIBUTE_POWER_COVERAGE_EXPR := source_power_graph_source_text_state.SOURCE_POWER_GRAPH_DISTRIBUTE_POWER_COVERAGE_EXPR", module_source)
        self.assertNotIn('"nonempty_guard": "if(!(consumers.size == 0 && producers.size == 0 && batteries.size == 0)){"', module_source)
        self.assertNotIn('"coverage_expr": "float coverage = Mathf.zero(needed) && Mathf.zero(produced) && !charged && Mathf.zero(lastPowerStored) ? 0f : Mathf.zero(needed) ? 1f : Math.min(1, produced / needed);"', module_source)

