    def test_source_building_lifecycle_team_state_owns_change_team_runtime(self):
        facade = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingLifecycleState.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingLifecycleTeamState.gd"
        source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingSourceTextState.gd"
        facade_source = facade.read_text(encoding="utf-8") if facade.exists() else ""
        module_source = module.read_text(encoding="utf-8") if module.exists() else ""
        source_text_source = source_text.read_text(encoding="utf-8") if source_text.exists() else ""

        self.assertTrue(module.exists(), "SourceBuildingLifecycleTeamState.gd must own Building changeTeam runtime")
        self.assertIn("class_name SourceBuildingLifecycleTeamState", module_source)
        self.assertIn('const source_building_lifecycle_team_state := preload("res://src/game/SourceBuildingLifecycleTeamState.gd")', facade_source)
        for const_name, literal_value in {
            "SOURCE_BUILDING_LIFECYCLE_TEAM_JAVA_METHOD_CHANGE_TEAM_180": "java_method_changeTeam_180",
            "SOURCE_BUILDING_LIFECYCLE_TEAM_JAVA_METHOD_CHANGE_TEAM_181": "java_method_changeTeam_181",
            "SOURCE_BUILDING_LIFECYCLE_TEAM_GENERATED_OWNER_CHANGE_TEAM_180": "building_comp.java_method_changeTeam_180",
            "SOURCE_BUILDING_LIFECYCLE_TEAM_GENERATED_OWNER_CHANGE_TEAM_181": "building_comp.java_method_changeTeam_181",
        }.items():
            self.assertIn(f'const {const_name} := "{literal_value}"', source_text_source)
            self.assertIn(f"const {const_name} := source_building_source_text_state.{const_name}", module_source)
            self.assertNotIn(f'const {const_name} := "{literal_value}"', module_source)
        delegations = {
            "static func change_team_delegate_state(next_team: Variant) -> Dictionary:": "\treturn source_building_lifecycle_team_state.change_team_delegate_state(next_team)",
            "static func change_team_initial_state(current_team: Variant, next_team: Variant, force_team: Variant, was_valid: bool) -> Dictionary:": "\treturn source_building_lifecycle_team_state.change_team_initial_state(current_team, next_team, force_team, was_valid)",
            "static func change_team_power_proximity_state(power_present: bool, update_power: bool, old_graph: Variant, team: Variant) -> Dictionary:": "\treturn source_building_lifecycle_team_state.change_team_power_proximity_state(power_present, update_power, old_graph, team)",
            "static func change_team_power_links_state(link_count: int, team: Variant, old_graph: Variant) -> Dictionary:": "\treturn source_building_lifecycle_team_state.change_team_power_links_state(link_count, team, old_graph)",
            "static func change_team_final_state(was: bool, last_team: Variant) -> Dictionary:": "\treturn source_building_lifecycle_team_state.change_team_final_state(was, last_team)",
            "static func generated_change_team_delegate_bridge_state(next_team: Variant) -> Dictionary:": "\treturn source_building_lifecycle_team_state.generated_change_team_delegate_bridge_state(next_team)",
            "static func generated_change_team_initial_bridge_state(current_team: Variant, next_team: Variant, force_team: Variant, was_valid: bool) -> Dictionary:": "\treturn source_building_lifecycle_team_state.generated_change_team_initial_bridge_state(current_team, next_team, force_team, was_valid)",
            "static func generated_change_team_power_proximity_bridge_state(current_team: Variant, next_team: Variant, force_team: Variant, was_valid: bool, power_present: bool, update_power: bool, old_graph: Variant) -> Dictionary:": "\treturn source_building_lifecycle_team_state.generated_change_team_power_proximity_bridge_state(current_team, next_team, force_team, was_valid, power_present, update_power, old_graph)",
            "static func generated_change_team_power_links_bridge_state(current_team: Variant, next_team: Variant, force_team: Variant, was_valid: bool, power_present: bool, update_power: bool, old_graph: Variant, link_count: int) -> Dictionary:": "\treturn source_building_lifecycle_team_state.generated_change_team_power_links_bridge_state(current_team, next_team, force_team, was_valid, power_present, update_power, old_graph, link_count)",
            "static func generated_change_team_final_bridge_state(current_team: Variant, next_team: Variant, force_team: Variant, was_valid: bool, power_present: bool, update_power: bool, old_graph: Variant, link_count: int) -> Dictionary:": "\treturn source_building_lifecycle_team_state.generated_change_team_final_bridge_state(current_team, next_team, force_team, was_valid, power_present, update_power, old_graph, link_count)",
        }
        for signature, delegation in delegations.items():
            with self.subTest(signature=signature):
                facade_body = self._static_method_body(facade_source, signature)
                self.assertIn(delegation, facade_body)
                self.assertIn(signature, module_source)
        self.assertIn('"source_owner": source_runtime_owner_registry.PORT_GAME_SOURCE_BUILDING_CHANGE_TEAM_INITIAL_STATE', module_source)
        self.assertIn('"source_owner": source_runtime_owner_registry.PORT_GAME_SOURCE_BUILDING_CHANGE_TEAM_POWER_LINKS_STATE', module_source)
        self.assertNotIn(', "java_method_changeTeam_180",', module_source)
        self.assertNotIn(', "java_method_changeTeam_181",', module_source)
        self.assertNotIn('"generated_owner": "building_comp.java_method_changeTeam_180"', module_source)
        self.assertNotIn('"generated_owner": "building_comp.java_method_changeTeam_181"', module_source)
        self.assertNotIn("source_generated_class_runtime.call_java_method", self._static_method_body(facade_source, "static func generated_change_team_initial_bridge_state(current_team: Variant, next_team: Variant, force_team: Variant, was_valid: bool) -> Dictionary:"))

