    def test_port_game_routes_playable_world_runtime_through_port_bridge(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        input_viewport_bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourceInputViewportPortBridge.gd"
        bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourcePlayableWorldRuntimePortBridge.gd"
        port_source = port_game.read_text(encoding="utf-8")
        input_viewport_bridge_source = input_viewport_bridge.read_text(encoding="utf-8") if input_viewport_bridge.exists() else ""
        bridge_source = bridge.read_text(encoding="utf-8") if bridge.exists() else ""

        self.assertTrue(bridge.exists(), "SourcePlayableWorldRuntimePortBridge.gd must own playable world runtime wrappers")
        self.assertIn('extends "res://src/game/SourceWorldGridPortBridge.gd"', input_viewport_bridge_source)
        self.assertIn('extends "res://src/game/SourcePlacedPowerRuntimePortBridge.gd"', bridge_source)
        self.assertIn('extends "res://src/game/SourceCoreInventoryPortBridge.gd"', self._game_bootstrap_port_bridge_source())
        self.assertIn('extends "res://src/game/SourceGameSimulationPortBridge.gd"', self._gameplay_runtime_port_bridge_source())
        self.assertIn('extends "res://src/game/SourceGamePresentationPortBridge.gd"', self._game_simulation_port_bridge_source())
        self.assertIn("SourcePlayableWorldRuntimePortBridge.gd", self._actual_port_game_port_bridge_chain())
        self.assertIn('const source_world_terrain_runtime_state_script := preload("res://src/game/SourceWorldTerrainRuntimeState.gd")', bridge_source)
        self.assertIn('const source_world_initial_build_runtime_state_script := preload("res://src/game/SourceWorldInitialBuildRuntimeState.gd")', bridge_source)
        self.assertIn('const source_item_transport_runtime_state_script := preload("res://src/game/SourceItemTransportRuntimeState.gd")', bridge_source)
        self.assertNotIn('const source_world_terrain_runtime_state_script := preload("res://src/game/SourceWorldTerrainRuntimeState.gd")', port_source)
        self.assertNotIn('const source_world_initial_build_runtime_state_script := preload("res://src/game/SourceWorldInitialBuildRuntimeState.gd")', port_source)
        self.assertNotIn('const source_item_transport_runtime_state_script := preload("res://src/game/SourceItemTransportRuntimeState.gd")', port_source)

        delegations = {
            "func build_world() -> void:": "\tsource_world_initial_build_runtime_state_script.build_world(self)",
            "func source_world_terrain_runtime_state() -> Dictionary:": "\treturn source_world_terrain_runtime_state_script.game_terrain_plan_state(self)",
            "func source_world_initial_build_runtime_state() -> Dictionary:": "\treturn source_world_initial_build_runtime_state_script.game_initial_build_plan_state(self)",
            "func source_item_transport_bootstrap_state() -> Dictionary:": "\treturn source_item_transport_runtime_state_script.game_bootstrap_state(self)",
            "func source_item_transport_runtime_state(progress_before: float, progress_delta: float) -> Dictionary:": "\treturn source_item_transport_runtime_state_script.game_transport_positions_state(self, progress_before, progress_delta)",
        }
        for signature, delegation in delegations.items():
            self.assertNotIn(signature, port_source)
            self.assertIn(signature, bridge_source)
            self.assertIn(delegation, self._method_body(bridge_source, signature))

