    def test_source_drill_production_runtime_state_keeps_batch_sequence_ssot(self):
        source = self._port_game_drill_production_runtime_source()

        self.assertIn("static func production_state(current_progress_fraction: float, drill_delay: float, output_delta: float, dominant_items: int, items_total: int, item_capacity: int, output_batch_fn: Callable, progress_fraction_fn: Callable) -> Dictionary:", source)
        self.assertIn("var raw_progress_before_delta := current_progress_fraction * drill_delay", source)
        self.assertIn("var raw_progress := raw_progress_before_delta + output_delta", source)
        self.assertIn("var output_batch: Dictionary = output_batch_fn.call(raw_progress, drill_delay, dominant_items, items_total, item_capacity)", source)
        self.assertIn("var offload_amount := int(output_batch.get(SOURCE_DRILL_OUTPUT_BATCH_AMOUNT_KEY, 0))", source)
