    def test_source_drill_inventory_runtime_callbacks_are_owned_by_module(self):
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceDrillInventoryRuntimeState.gd"
        source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceDrillInventorySourceTextState.gd"
        proof_script = ROOT / "godot-mindustry" / "tools" / "runtime_proofs" / "DrillInventoryCallbackModuleProof.gd"
        source = module.read_text(encoding="utf-8")
        source_text_source = source_text.read_text(encoding="utf-8") if source_text.exists() else ""
        proof_source = proof_script.read_text(encoding="utf-8")
        callbacks_body = self._method_body(source, "static func default_callbacks_state(game: Object) -> Dictionary:")

        self.assertIn("static func runtime_method_names(game: Object) -> Dictionary:", source)
        self.assertIn('if game.has_method("_drill_inventory_method_names"):', source)
        self.assertIn("static func runtime_method_name(method_names: Dictionary, key: String, fallback_name: String) -> String:", source)
        self.assertIn("var method_names := runtime_method_names(game)", callbacks_body)
        expected_callbacks = {
            "SOURCE_DRILL_INVENTORY_ITEM_COUNT": ("item_count", "drill_item_count"),
            "SOURCE_DRILL_INVENTORY_CORE_ACCEPT": ("core_accept", "source_core_accept_item"),
            "SOURCE_DRILL_INVENTORY_CORE_HANDLE": ("core_handle", "source_core_handle_item"),
            "SOURCE_DRILL_INVENTORY_REMOVE_ITEM": ("remove_item", "remove_drill_item"),
            "SOURCE_DRILL_INVENTORY_INCREMENT_DUMP": ("increment_dump", "increment_drill_dump"),
        }
        self.assertNotIn('Callable(game, "source_', callbacks_body)
        for prefix, (key, method_name) in expected_callbacks.items():
            with self.subTest(key=key):
                self.assertIn(f'const {prefix}_KEY := "{key}"', source_text_source)
                self.assertIn(f'const {prefix}_FALLBACK := "{method_name}"', source_text_source)
                self.assertIn(f'const {prefix}_KEY := source_drill_inventory_source_text_state.{prefix}_KEY', source)
                self.assertIn(f'const {prefix}_FALLBACK := source_drill_inventory_source_text_state.{prefix}_FALLBACK', source)
                self.assertIn(f"{prefix}_KEY: Callable(game, runtime_method_name(method_names, {prefix}_KEY, {prefix}_FALLBACK))", callbacks_body)
        self.assertIn("func _drill_inventory_method_names() -> Dictionary:", proof_source)
        self.assertIn('source_drill_inventory_runtime_state.SOURCE_DRILL_INVENTORY_CORE_HANDLE_KEY: "proof_core_handle_item"', proof_source)
        self.assertIn('"override_callbacks_match"', proof_source)

