        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockRequirementsPortBridge.gd"

        self.assertTrue(bridge.exists(), "SourceBlockRequirementsPortBridge.gd must own Block requirements compatibility wrappers")
        port_source = port_game.read_text(encoding="utf-8")
        bridge_source = bridge.read_text(encoding="utf-8") if bridge.exists() else ""
        chain_source = self._port_game_port_bridge_chain_source()

        self.assertIn('extends "res://src/game/SourceBlockResearchRequirementsPortBridge.gd"', bridge_source)
        self.assertIn('extends "res://src/game/SourceBlockRequirementsPortBridge.gd"', (ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretAmmoPortBridge.gd").read_text(encoding="utf-8"))
        self.assertIn("SourceBlockRequirementsPortBridge.gd", self._actual_port_game_port_bridge_chain())
        self.assertIn("func can_afford(block) -> bool:", chain_source)
        self.assertIn("func spend_requirements(block) -> void:", chain_source)
        self.assertIn("func requirements_text(block) -> String:", chain_source)
        self.assertNotIn("func can_afford(block) -> bool:", port_source)
        self.assertNotIn("func spend_requirements(block) -> void:", port_source)
        self.assertNotIn("func requirements_text(block) -> String:", port_source)
        self.assertNotIn('const source_block_requirements_state := preload("res://src/game/SourceBlockRequirementsState.gd")', port_source)
        self.assertIn('const source_block_requirements_state := preload("res://src/game/SourceBlockRequirementsState.gd")', bridge_source)

        delegations = {
            "func can_afford(block) -> bool:": "\treturn source_block_requirements_state.game_can_afford(self, block)",
            "func spend_requirements(block) -> void:": "\tsource_block_requirements_state.game_spend_requirements(self, block)",
            "func requirements_text(block) -> String:": "\treturn source_block_requirements_state.block_requirements_text(block)",
            "func source_block_setup_requirements_simple_state(cat: Variant, stacks: Variant) -> Dictionary:": "\treturn source_block_requirements_state.setup_requirements_simple_state(cat, stacks)",
            "func generated_block_setup_requirements_simple_bridge_state(cat: Variant, stacks: Variant) -> Dictionary:": "\treturn source_block_requirements_state.generated_block_setup_requirements_simple_bridge_state(cat, stacks)",
            "func source_block_setup_requirements_visible_state(cat: Variant, build_visibility: Variant, stacks: Variant) -> Dictionary:": "\treturn source_block_requirements_state.setup_requirements_visible_state(cat, build_visibility, stacks)",
            "func generated_block_setup_requirements_visible_bridge_state(cat: Variant, build_visibility: Variant, stacks: Variant) -> Dictionary:": "\treturn source_block_requirements_state.generated_block_setup_requirements_visible_bridge_state(cat, build_visibility, stacks)",
            "func source_block_requirements_unlocked_state(cat: Variant, stacks: Variant, unlocked: bool) -> Dictionary:": "\treturn source_block_requirements_state.requirements_unlocked_state(cat, stacks, unlocked)",
            "func generated_block_requirements_unlocked_bridge_state(cat: Variant, stacks: Variant, unlocked: bool) -> Dictionary:": "\treturn source_block_requirements_state.generated_block_requirements_unlocked_bridge_state(cat, stacks, unlocked)",
            "func source_block_requirements_simple_state(cat: Variant, stacks: Variant) -> Dictionary:": "\treturn source_block_requirements_state.requirements_simple_state(cat, stacks)",
            "func generated_block_requirements_simple_bridge_state(cat: Variant, stacks: Variant) -> Dictionary:": "\treturn source_block_requirements_state.generated_block_requirements_simple_bridge_state(cat, stacks)",
            "func source_block_requirements_visible_state(cat: Variant, build_visibility: Variant, stacks: Variant) -> Dictionary:": "\treturn source_block_requirements_state.requirements_visible_state(cat, build_visibility, stacks)",
            "func generated_block_requirements_visible_bridge_state(cat: Variant, build_visibility: Variant, stacks: Variant) -> Dictionary:": "\treturn source_block_requirements_state.generated_block_requirements_visible_bridge_state(cat, build_visibility, stacks)",
        }
        for signature, delegation in delegations.items():
            self.assertIn(signature, bridge_source)
            self.assertIn(delegation, self._method_body(bridge_source, signature))

