    def test_source_hud_runtime_state_aligns_build_format_arguments(self):
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceHudRuntimeState.gd"
        helper_source = helper.read_text(encoding="utf-8") if helper.exists() else ""
        hud_text_body = helper_source.split("static func hud_text_state(game: Object, requirements_text_fn: Callable) -> Dictionary:", 1)[1].split("static func hud_text", 1)[0]
        format_line = next(line for line in helper_source.splitlines() if line.startswith("const SOURCE_HUD_TEXT_FORMAT :="))
        format_text = format_line.split(':= "', 1)[1].rsplit('"', 1)[0]
        format_argument_lines = hud_text_body.split("SOURCE_HUD_TEXT_FORMAT % [", 1)[1].split("\n\t]", 1)[0].splitlines()
        format_arguments = [line.strip().rstrip(",") for line in format_argument_lines if line.strip()]

        self.assertIn('var selected_implementation_name: String = source_selected_build_state.implementation_name(selected) if selected else "none"', helper_source)
        self.assertIn("selected_implementation_name", format_arguments)
        self.assertLess(format_arguments.index("selected_cost"), format_arguments.index("selected_implementation_name"))
        self.assertLess(format_arguments.index("selected_implementation_name"), format_arguments.index('str(game.call("playable_core_item_name"))'))
        self.assertEqual(format_text.count("%"), len(format_arguments))

