    def test_port_game_delegates_factory_step_previews_to_runtime_module(self):
        source = self._port_game_factory_runtime_source()
        transport_body = source.split("func step_factory_transport(seconds: float) -> Dictionary:", 1)[1].split("func step_factory_drill", 1)[0]
        drill_body = source.split("func step_factory_drill(seconds: float) -> Dictionary:", 1)[1].split("func factory_runtime_state", 1)[0]

        self.assertIn("static func transport_step_context(game: Object, seconds: float, factory_cells: Dictionary, fallback_cell: Vector2i) -> Dictionary:", source)
        self.assertIn("static func drill_step_context(game: Object, seconds: float, drill_cell: Vector2i) -> Dictionary:", source)
        self.assertIn("static func game_transport_step_state(game: Object, seconds: float) -> Dictionary:", source)
        self.assertIn("static func game_drill_step_state(game: Object, seconds: float) -> Dictionary:", source)
        self.assertIn("static func transport_step_state(step_context: Dictionary) -> Dictionary:", source)
        self.assertIn("static func drill_step_state(step_context: Dictionary) -> Dictionary:", source)
        self.assertIn("return source_gameplay_factory_runtime_state.game_transport_step_state(self, seconds)", transport_body)
        self.assertIn("return source_gameplay_factory_runtime_state.game_drill_step_state(self, seconds)", drill_body)
        self.assertNotIn("var step_context := {", transport_body)
        self.assertNotIn("var step_context := {", drill_body)
