        self.assertIn("static func overdrive_phase_real_boost(block) -> float:", selected_source)
        self.assertIn('if block == null or implementation_name(block) != "OverdriveProjector":', selected_source)
        self.assertIn("return source_overdrive_projector_state.real_boost(block)", selected_source)
        self.assertIn("return source_overdrive_projector_state.real_boost(block, 1.0)", selected_source)
        self.assertIn('"selected_build_overdrive_real_boost": game.call("selected_build_overdrive_real_boost")', summary_source)
