    def test_source_overdrive_projector_source_text_state_owns_real_boost_and_boost_bar_literals(self):
        owner = ROOT / "godot-mindustry" / "src" / "game" / "SourceOverdriveProjectorSourceTextState.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceOverdriveProjectorState.gd"
        owner_source = owner.read_text(encoding="utf-8") if owner.exists() else ""
        module_source = module.read_text(encoding="utf-8") if module.exists() else ""

        self.assertTrue(owner.exists(), "SourceOverdriveProjectorSourceTextState.gd must own OverdriveProjector source-text literals")
        self.assertIn("class_name SourceOverdriveProjectorSourceTextState", owner_source)
        for const_name, literal in {
            "SOURCE_OVERDRIVE_PROJECTOR_REAL_BOOST_METHOD": '"public float realBoost(){\\n            return (speedBoost + phaseHeat * speedBoostPhase) * efficiency;\\n        }"',
            "SOURCE_OVERDRIVE_PROJECTOR_REAL_BOOST_RETURN": '"return (speedBoost + phaseHeat * speedBoostPhase) * efficiency;"',
            "SOURCE_OVERDRIVE_PROJECTOR_REAL_BOOST_SPEED_BOOST_FIELD": '"public float speedBoost = 1.5f;"',
            "SOURCE_OVERDRIVE_PROJECTOR_REAL_BOOST_SPEED_BOOST_PHASE_FIELD": '"public float speedBoostPhase = 0.75f;"',
            "SOURCE_OVERDRIVE_PROJECTOR_REAL_BOOST_PHASE_HEAT_FIELD": '"public float heat, charge = Mathf.random(reload), phaseHeat, smoothEfficiency, useProgress;"',
            "SOURCE_OVERDRIVE_PROJECTOR_TARGET_FILTER_BOOST_BRANCH": '"if(charge >= reload){\\n                float realRange = range + phaseHeat * phaseRangeBoost;"',
            "SOURCE_OVERDRIVE_PROJECTOR_BOOST_BAR_METHOD": '"public void setBars(){"',
            "SOURCE_OVERDRIVE_PROJECTOR_BOOST_BAR_ADD_BAR": '"addBar(\\"boost\\", (OverdriveBuild entity) -> new Bar(() -> Core.bundle.format(\\"bar.boost\\", Mathf.round(Math.max((entity.realBoost() * 100 - 100), 0))), () -> Pal.accent, () -> entity.realBoost() / (hasBoost ? speedBoost + speedBoostPhase : speedBoost)));"',
            "SOURCE_OVERDRIVE_PROJECTOR_BOOST_BAR_REAL_BOOST_CALL": '"entity.realBoost()"',
            "SOURCE_OVERDRIVE_PROJECTOR_BOOST_BAR_DENOMINATOR": '"hasBoost ? speedBoost + speedBoostPhase : speedBoost"',
            "SOURCE_OVERDRIVE_PROJECTOR_BOOST_BAR_SPEED_BOOST_FIELD": '"public float speedBoost = 1.5f;"',
            "SOURCE_OVERDRIVE_PROJECTOR_BOOST_BAR_SPEED_BOOST_PHASE_FIELD": '"public float speedBoostPhase = 0.75f;"',
            "SOURCE_OVERDRIVE_PROJECTOR_BOOST_BAR_HAS_BOOST_FIELD": '"public boolean hasBoost = true;"',
        }.items():
            with self.subTest(const_name=const_name):
                self.assertIn(f"const {const_name} := {literal}", owner_source)
                self.assertIn(f"const {const_name} := source_overdrive_projector_source_text_state.{const_name}", module_source)
                self.assertNotIn(f"const {const_name} := {literal}", module_source)

