    def test_port_game_delegates_building_time_default_accessors_to_module(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingTimeState.gd"
        bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingTimePortBridge.gd"
        building_comp = ROOT / "godot-mindustry" / "src" / "generated" / "classes" / "mindustry" / "entities" / "comp" / "BuildingComp.gd"

        helper_source = helper.read_text(encoding="utf-8")
        bridge_source = bridge.read_text(encoding="utf-8")
        building_comp_source = building_comp.read_text(encoding="utf-8")
        port_source = port_game.read_text(encoding="utf-8")

        for method_name in (
            "time_scale_state",
            "warmup_state",
            "total_progress_state",
            "progress_state",
            "generated_time_scale_bridge_state",
            "generated_warmup_bridge_state",
            "generated_total_progress_bridge_state",
            "generated_progress_bridge_state",
        ):
            self.assertIn("static func " + method_name, helper_source)
        delegations = {
            "func source_building_time_scale_state(current_time_scale: float) -> float:": "\treturn source_building_time_state.time_scale_state(current_time_scale)",
            "func source_building_warmup_state() -> float:": "\treturn source_building_time_state.warmup_state()",
            "func source_building_total_progress_state(source_time: float) -> float:": "\treturn source_building_time_state.total_progress_state(source_time)",
            "func source_building_progress_state() -> float:": "\treturn source_building_time_state.progress_state()",
            "func generated_building_comp_time_scale_bridge_state(current_time_scale: float) -> Dictionary:": "\treturn source_building_time_state.generated_time_scale_bridge_state(current_time_scale)",
            "func generated_building_comp_warmup_bridge_state() -> Dictionary:": "\treturn source_building_time_state.generated_warmup_bridge_state()",
            "func generated_building_comp_total_progress_bridge_state(source_time: float) -> Dictionary:": "\treturn source_building_time_state.generated_total_progress_bridge_state(source_time)",
            "func generated_building_comp_progress_bridge_state() -> Dictionary:": "\treturn source_building_time_state.generated_progress_bridge_state()",
        }
        for signature, delegation in delegations.items():
            with self.subTest(signature=signature):
                self.assertNotIn(signature, port_source)
                self.assertIn(delegation, self._method_body(bridge_source, signature))
        for signature in (
            "func java_method_timeScale_49(_args: Array = []) -> Variant:",
            "func java_method_warmup_50(_args: Array = []) -> Variant:",
            "func java_method_totalProgress_51(_args: Array = []) -> Variant:",
            "func java_method_progress_52(_args: Array = []) -> Variant:",
        ):
            self.assertIn(signature, building_comp_source)

