        self.assertIn("static func apply_overdrive_boost_to_sprite(game, target, intensity: float, duration: float) -> Dictionary:", overdrive_source)
        self.assertIn('return source_overdrive_projector_state.find_overdrive_boost_target(self, overdrive_cell, overdrive_projector, phase_heat)', boost_target_body)
        self.assertIn('return source_overdrive_projector_state.apply_overdrive_boost_to_sprite(self, target, intensity, duration)', boost_apply_body)
        self.assertIn('var filter_state: Dictionary = game.call("source_overdrive_projector_target_filter_state", overdrive_projector, target_block, distance, phase_heat)', overdrive_runtime_source)
        self.assertIn("var boost_input := source_overdrive_boost_state.boost_input(target, target_block, source_block_defaults.TIME_SCALE_DEFAULT, source_block_defaults.CAN_OVERDRIVE_DEFAULT)", overdrive_runtime_source)
