        self.assertNotIn('last_overdrive_projector_boosted_block_id = str(boosted_state.get("block_id", ""))', boost_apply_body)
        self.assertNotIn('last_overdrive_projector_boosted_cell = boosted_state.get("cell", Vector2i.ZERO)', boost_apply_body)
