    def test_port_game_uses_source_bullet_speed(self):
        bullet_defaults = ROOT / "godot-mindustry" / "src" / "game" / "SourceBulletDefaults.gd"
        bullet_runtime_state = ROOT / "godot-mindustry" / "src" / "game" / "SourceBulletRuntimeState.gd"
        bullet_runtime_core = ROOT / "godot-mindustry" / "src" / "game" / "SourceBulletRuntime.gd"
        bullet_type_create_state = ROOT / "godot-mindustry" / "src" / "game" / "SourceBulletTypeCreateState.gd"
        source = self._port_game_bullet_runtime_and_type_create_source()
        bullet_source = bullet_defaults.read_text(encoding="utf-8") if bullet_defaults.exists() else ""
        bullet_runtime_state_source = bullet_runtime_state.read_text(encoding="utf-8") if bullet_runtime_state.exists() else ""
        bullet_runtime_core_source = bullet_runtime_core.read_text(encoding="utf-8") if bullet_runtime_core.exists() else ""
        bullet_type_create_source = bullet_type_create_state.read_text(encoding="utf-8") if bullet_type_create_state.exists() else ""
        summary_source = self._runtime_summary_source()

        self.assertIn("func source_bullet_world_speed(data: Dictionary) -> float:", source)
        self.assertIn('const SOURCE_BULLET_WORLD_SPEED_COMMENT := "/** Speed in units/tick. */"', source)
        self.assertIn('const SOURCE_BULLET_WORLD_SPEED_FIELD := "public float speed = 1f;"', source)
        self.assertIn('const SOURCE_BULLET_WORLD_SPEED_STAT_CASE := "case speed -> type.speed * 60f / tilesize;"', source)
        self.assertIn('const SOURCE_BULLET_WORLD_SPEED_KEY := "speed"', source)
        self.assertIn("const WORLD_SPEED_DEFAULT := 1.0", bullet_source)
        self.assertIn("const TICKS_PER_SECOND := 60.0", bullet_source)
        self.assertNotIn("const SOURCE_BULLET_WORLD_SPEED_DEFAULT :=", source)
        self.assertIn("const SOURCE_BULLET_WORLD_SPEED_TICKS_PER_SECOND := source_bullet_defaults.TICKS_PER_SECOND", source)
        self.assertIn("func source_bullet_world_speed_per_tick(data: Dictionary) -> float:", source)
        self.assertIn("return float(data.get(SOURCE_BULLET_WORLD_SPEED_KEY, source_bullet_defaults.WORLD_SPEED_DEFAULT))", source)
        self.assertIn("return world_speed_per_tick(data) * SOURCE_BULLET_WORLD_SPEED_TICKS_PER_SECOND", source)
        self.assertTrue(bullet_runtime_state.exists(), "SourceBulletRuntimeState.gd must own shared bullet velocity source-text constants")
        velocity_source_text = {
            "SOURCE_BULLET_VELOCITY_SPEED_FIELD": '"public float speed = 1f;"',
            "SOURCE_BULLET_VELOCITY_INIT_VEL_CALL": '"bullet.initVel(angle, speed * velocityScl * (velocityScaleRandMin != 1f || velocityScaleRandMax != 1f ? Mathf.random(velocityScaleRandMin, velocityScaleRandMax) : 1f));"',
            "SOURCE_BULLET_VELOCITY_COMP_INIT_VEL_METHOD": '"public void initVel(float angle, float amount){"',
            "SOURCE_BULLET_VELOCITY_COMP_TRNS": '"vel.trns(angle, amount);"',
            "SOURCE_BULLET_VELOCITY_COMP_ROTATION": '"rotation = angle;"',
            "SOURCE_BULLET_VELOCITY_VECTOR_FIELD": '"Vec2 vel = new Vec2();"',
            "SOURCE_BULLET_VELOCITY_VECTOR_INIT_TRNS": '"vel.trns(angle, amount);"',
            "SOURCE_BULLET_VELOCITY_VECTOR_VEC2_TRNS_METHOD": '"public Vec2 trns(float angle, float amount){"',
            "SOURCE_BULLET_VELOCITY_VECTOR_VEC2_TRNS_RETURN": '"return set(amount, 0).rotate(angle);"',
            "SOURCE_BULLET_VELOCITY_VECTOR_EXISTING_SOURCE": '"existing Vec2 velocity"',
            "SOURCE_BULLET_VELOCITY_VECTOR_TRNS_SOURCE": '"vel.trns(angle, amount)"',
        }
        self.assertIn('const source_bullet_runtime_state := preload("res://src/game/SourceBulletRuntimeState.gd")', bullet_runtime_core_source)
        self.assertIn('const source_bullet_runtime_state := preload("res://src/game/SourceBulletRuntimeState.gd")', bullet_type_create_source)
        for const_name, literal in velocity_source_text.items():
            with self.subTest(bullet_velocity_source_text=const_name):
                self.assertIn(f"const {const_name} := source_bullet_source_text_state.{const_name}", bullet_runtime_state_source)
                self.assertNotIn(f"const {const_name} := {literal}", bullet_runtime_state_source)
                self.assertIn(f"const {const_name} := source_bullet_runtime_state.{const_name}", bullet_runtime_core_source)
                self.assertNotIn(f"const {const_name} := {literal}", bullet_runtime_core_source)
                if "VELOCITY_VECTOR" in const_name:
                    self.assertIn(f"const {const_name} := source_bullet_runtime_state.{const_name}", bullet_type_create_source)
                    self.assertNotIn(f"const {const_name} := {literal}", bullet_type_create_source)
        self.assertIn("func source_bullet_velocity(data: Dictionary, shoot_angle_degrees: float) -> Vector2:", source)
        self.assertIn('"speed": float(bullet_spawn_state.get("speed", 0.0))', source)
        self.assertIn("var velocity_state := source_math_state.source_angles_trns_vec(shoot_angle_degrees, world_speed(data), 0.0)", source)
        velocity_body = source.split("static func velocity(data: Dictionary, shoot_angle_degrees: float) -> Vector2:", 1)[1].split("\nstatic func ", 1)[0]
        self.assertNotIn("Vector2.RIGHT.rotated(deg_to_rad(shoot_angle_degrees))", velocity_body)
        self.assertIn("func source_bullet_velocity_vector_state(velocity_state: Dictionary) -> Dictionary:", source)
        self.assertIn('"source": SOURCE_BULLET_VELOCITY_VECTOR_EXISTING_SOURCE', source)
        self.assertIn('"source": SOURCE_BULLET_VELOCITY_VECTOR_TRNS_SOURCE', source)
        self.assertNotIn('float(data.get("speed", 2.5)) * float(tile_size) * 4.0', source)
        self.assertIn("func selected_turret_ammo_world_speed() -> float:", source)
        self.assertIn('return source_turret_runtime_state.selected_ammo_world_speed_for_game(self)', source)
        self.assertIn('"selected_turret_ammo_world_speed": game.call("selected_turret_ammo_world_speed")', summary_source)

