    def test_source_bullet_runtime_scalar_accessors_are_sharded_to_runtime_state(self):
        runtime = ROOT / "godot-mindustry" / "src" / "game" / "SourceBulletRuntime.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBulletRuntimeState.gd"
        proof = ROOT / "godot-mindustry" / "tools" / "runtime_proofs" / "BulletRuntimeModuleProof.gd"
        runtime_source = runtime.read_text(encoding="utf-8")
        module_source = module.read_text(encoding="utf-8")
        proof_source = proof.read_text(encoding="utf-8")

        self.assertIn('const source_bullet_runtime_state := preload("res://src/game/SourceBulletRuntimeState.gd")', runtime_source)
        delegations = {
            "static func range_change(data: Dictionary, _defaults: source_bullet_defaults) -> float:": (
                "\treturn source_bullet_runtime_state.range_change(data)",
                "static func range_change(data: Dictionary) -> float:",
                "defaults.range_change_default()",
            ),
            "static func inaccuracy(data: Dictionary, _defaults: source_bullet_defaults) -> float:": (
                "\treturn source_bullet_runtime_state.inaccuracy(data)",
                "static func inaccuracy(data: Dictionary) -> float:",
                "defaults.inaccuracy_default()",
            ),
            "static func lifetime_seconds(data: Dictionary, _defaults: source_bullet_defaults, _tick_rate: float) -> float:": (
                "\treturn source_bullet_runtime_state.lifetime_seconds(data)",
                "static func lifetime_seconds(data: Dictionary) -> float:",
                "defaults.lifetime_default()",
            ),
            "static func world_speed(data: Dictionary, _defaults: source_bullet_defaults, _tick_rate: float) -> float:": (
                "\treturn source_bullet_runtime_state.world_speed(data)",
                "static func world_speed(data: Dictionary) -> float:",
                "defaults.speed_default()",
            ),
            "static func velocity(data: Dictionary, _defaults: source_bullet_defaults, _tick_rate: float, shoot_angle_degrees: float) -> Vector2:": (
                "\treturn source_bullet_runtime_state.velocity(data, shoot_angle_degrees)",
                "static func velocity(data: Dictionary, shoot_angle_degrees: float) -> Vector2:",
                "Vector2.RIGHT.rotated",
            ),
            "static func hit_size(data: Dictionary, _defaults: source_bullet_defaults) -> float:": (
                "\treturn source_bullet_runtime_state.hit_size(data)",
                "static func hit_size(data: Dictionary) -> float:",
                "defaults.hit_size_default()",
            ),
            "static func damage(data: Dictionary, _defaults: source_bullet_defaults) -> float:": (
                "\treturn source_bullet_runtime_state.damage(data)",
                "static func damage(data: Dictionary) -> float:",
                "defaults.damage_default()",
            ),
            "static func ammo_multiplier(data: Dictionary, _defaults: source_bullet_defaults) -> float:": (
                "\treturn source_bullet_runtime_state.ammo_multiplier(data)",
                "static func ammo_multiplier(data: Dictionary) -> float:",
                "defaults.ammo_multiplier_default()",
            ),
            "static func reload_multiplier(data: Dictionary, _defaults: source_bullet_defaults) -> float:": (
                "\treturn source_bullet_runtime_state.reload_multiplier(data)",
                "static func reload_multiplier(data: Dictionary) -> float:",
                "defaults.reload_multiplier_default()",
            ),
            "static func scale(data: Dictionary, _defaults: source_bullet_defaults, texture_size: Vector2) -> Vector2:": (
                "\treturn source_bullet_runtime_state.scale(data, texture_size)",
                "static func scale(data: Dictionary, texture_size: Vector2) -> Vector2:",
                "defaults.width_default()",
            ),
        }
        for signature, expected in delegations.items():
            delegation, module_signature, inline_source = expected
            runtime_body = self._static_method_body(runtime_source, signature)
            self.assertIn(delegation, runtime_body)
            self.assertNotIn(inline_source, runtime_body)
            self.assertIn(module_signature, module_source)

        proof_matches = proof_source.split('proof["matches"] = ', 1)[1].split("\n", 1)[0]
        for proof_key in (
            '"runtime_scalar_range_change_matches"',
            '"runtime_scalar_inaccuracy_matches"',
            '"runtime_scalar_lifetime_seconds_matches"',
            '"runtime_scalar_world_speed_matches"',
            '"runtime_scalar_velocity_matches"',
            '"runtime_scalar_hit_size_matches"',
            '"runtime_scalar_damage_matches"',
            '"runtime_scalar_ammo_multiplier_matches"',
            '"runtime_scalar_reload_multiplier_matches"',
            '"runtime_scalar_scale_matches"',
        ):
            self.assertIn(proof_key, proof_source)
            self.assertIn(proof_key, proof_matches)

