    def test_source_turret_ammo_manifest_owns_manifest_runtime(self):
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretAmmoState.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretAmmoManifestState.gd"
        helper_source = helper.read_text(encoding="utf-8") if helper.exists() else ""
        module_source = module.read_text(encoding="utf-8") if module.exists() else ""

        self.assertTrue(module.exists(), "SourceTurretAmmoManifestState.gd must own turret ammo manifest runtime")
        self.assertIn('const source_turret_ammo_manifest_state := preload("res://src/game/SourceTurretAmmoManifestState.gd")', helper_source)

        delegations = {
            "static func liquid_turret_ammo_state(objects: Array) -> Dictionary:": "\treturn source_turret_ammo_manifest_state.liquid_turret_ammo_state(objects)",
            "static func generated_liquid_turret_ammo_bridge_state(objects: Array) -> Dictionary:": "\treturn source_turret_ammo_manifest_state.generated_liquid_turret_ammo_bridge_state(objects)",
            "static func item_turret_ammo_state(objects: Array) -> Dictionary:": "\treturn source_turret_ammo_manifest_state.item_turret_ammo_state(objects)",
            "static func generated_item_turret_ammo_bridge_state(objects: Array) -> Dictionary:": "\treturn source_turret_ammo_manifest_state.generated_item_turret_ammo_bridge_state(objects)",
            "static func continuous_liquid_turret_ammo_state(objects: Array) -> Dictionary:": "\treturn source_turret_ammo_manifest_state.continuous_liquid_turret_ammo_state(objects)",
            "static func generated_continuous_liquid_turret_ammo_bridge_state(objects: Array) -> Dictionary:": "\treturn source_turret_ammo_manifest_state.generated_continuous_liquid_turret_ammo_bridge_state(objects)",
        }
        for signature, delegation in delegations.items():
            helper_body = self._static_method_body(helper_source, signature)
            self.assertIn(delegation, helper_body)
            self.assertIn(signature, module_source)

        self.assertNotIn("static func _ammo_manifest_state(", helper_source)
        self.assertIn("static func _ammo_manifest_state(source_owner: String, field: String, comment: String, method: String, assignment_expr: String, objects: Array) -> Dictionary:", module_source)
        self.assertIn('"source_owner": source_runtime_owner_registry.PORT_GAME_SOURCE_ITEM_TURRET_AMMO_STATE', module_source)
        self.assertIn("var matches: bool = source_generated_class_runtime.generated_state_matches_generated_subset(result, canonical)", module_source)

    def test_port_game_turret_cell_registry_uses_canonical_runtime_module(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        conveyor_bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourceConveyorRuntimePortBridge.gd"
        bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretCellRegistryPortBridge.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretCellRegistryState.gd"
        proof = ROOT / "godot-mindustry" / "tools" / "runtime_proofs" / "TurretCellRegistryModuleProof.gd"
        raw_port_source = port_game.read_text(encoding="utf-8")
        source = raw_port_source + "\n" + self._port_game_port_bridge_chain_source()
        conveyor_bridge_source = conveyor_bridge.read_text(encoding="utf-8") if conveyor_bridge.exists() else ""
        bridge_source = bridge.read_text(encoding="utf-8") if bridge.exists() else ""
        module_source = module.read_text(encoding="utf-8") if module.exists() else ""
        proof_source = proof.read_text(encoding="utf-8") if proof.exists() else ""

        self.assertTrue(bridge.exists(), "SourceTurretCellRegistryPortBridge.gd must own turret cell registry PortGame facade wrappers")
        register_body = self._method_body(bridge_source, "func register_turret_cell(cell: Vector2i, block) -> void:")
        unregister_body = self._method_body(bridge_source, "func unregister_turret_cell(cell: Vector2i) -> void:")
        self.assertTrue(module.exists(), "source_turret_cell_registry_state.gd must own turret cell registry mutation")
        self.assertTrue(proof.exists(), "TurretCellRegistryModuleProof.gd must prove turret cell registry mutation")
        self.assertIn('extends "res://src/game/SourceTurretCellRegistryPortBridge.gd"', conveyor_bridge_source)
        self.assertIn('extends "res://src/game/SourcePlacedBlockPortBridge.gd"', bridge_source)
        self.assertIn("SourceTurretCellRegistryPortBridge.gd", self._actual_port_game_port_bridge_chain())
        self.assertIn('const source_turret_cell_registry_state := preload("res://src/game/SourceTurretCellRegistryState.gd")', bridge_source)
        self.assertNotIn('const source_turret_cell_registry_state := preload("res://src/game/SourceTurretCellRegistryState.gd")', raw_port_source)
        self.assertIn("class_name SourceTurretCellRegistryState", module_source)
        self.assertIn("static func register_turret_cell(game: Object, cell: Vector2i, block) -> void:", module_source)
        self.assertIn("static func unregister_turret_cell(game: Object, cell: Vector2i) -> void:", module_source)
        self.assertIn("source_turret_cell_registry_state.register_turret_cell(self, cell, block)", bridge_source)
        self.assertIn("source_turret_cell_registry_state.unregister_turret_cell(self, cell)", bridge_source)
        self.assertNotIn("func register_turret_cell(cell: Vector2i, block) -> void:", raw_port_source)
        self.assertNotIn("func unregister_turret_cell(cell: Vector2i) -> void:", raw_port_source)
        self.assertNotIn("turret_cooldowns[key] = 0.0", register_body)
        self.assertNotIn("turret_cells.append(cell)", register_body)
        self.assertNotIn("turret_barrel_counters.erase(key)", unregister_body)
        self.assertIn("TURRET_CELL_REGISTRY_MODULE_PROOF", proof_source)
        self.assertIn("source_turret_cell_registry_state.register_turret_cell(game, cell, block)", proof_source)
        self.assertIn("source_turret_cell_registry_state.unregister_turret_cell(game, cell)", proof_source)
        self.assertIn("source_ssot_accessor_runtime_state.canonical_headquarter_registry_state()", proof_source)
        self.assertIn('"registry_valid"', proof_source)
        self.assertIn('"matches"', proof_source)

