    def test_source_turret_selected_ammo_runtime_owns_selected_ammo_helpers(self):
        runtime_state = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretRuntimeState.gd"
        selected_ammo_state = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretSelectedAmmoRuntimeState.gd"
        runtime_source = runtime_state.read_text(encoding="utf-8")
        selected_ammo_source = selected_ammo_state.read_text(encoding="utf-8") if selected_ammo_state.exists() else ""

        self.assertTrue(selected_ammo_state.exists(), "SourceTurretSelectedAmmoRuntimeState.gd must own selected turret ammo runtime helpers")
        self.assertIn("class_name SourceTurretSelectedAmmoRuntimeState", selected_ammo_source)
        self.assertIn('const source_turret_selected_ammo_runtime_state := preload("res://src/game/SourceTurretSelectedAmmoRuntimeState.gd")', runtime_source)
        self.assertIn("static func default_callbacks_state(game: Object) -> Dictionary:", selected_ammo_source)
        self.assertIn("static func selected_ammo_payload(turret) -> Dictionary:", selected_ammo_source)
        self.assertIn("static func selected_ammo_sprite(turret, default_sprite: String) -> String:", selected_ammo_source)
        self.assertIn("static func selected_ammo_world_speed_for_game(game: Object) -> float:", selected_ammo_source)
        self.assertIn("static func selected_total_ammo_for_game(game: Object) -> int:", selected_ammo_source)
        self.assertIn("static func selected_loaded_ammo_item_for_game(game: Object) -> String:", selected_ammo_source)

        expected_delegates = {
            "static func selected_ammo_payload(turret) -> Dictionary:": "return source_turret_selected_ammo_runtime_state.selected_ammo_payload(turret)",
            "static func selected_ammo_sprite(turret, default_sprite: String) -> String:": "return source_turret_selected_ammo_runtime_state.selected_ammo_sprite(turret, default_sprite)",
            "static func selected_ammo_world_speed_for_game(game: Object) -> float:": "return source_turret_selected_ammo_runtime_state.selected_ammo_world_speed_for_game(game)",
            "static func selected_total_ammo_for_game(game: Object) -> int:": "return source_turret_selected_ammo_runtime_state.selected_total_ammo_for_game(game)",
            "static func selected_loaded_ammo_item_for_game(game: Object) -> String:": "return source_turret_selected_ammo_runtime_state.selected_loaded_ammo_item_for_game(game)",
        }
        for signature, delegate in expected_delegates.items():
            with self.subTest(signature=signature):
                runtime_body = self._static_method_body(runtime_source, signature)
                self.assertIn(delegate, runtime_body)

        for implementation_marker in [
            "var ammo_value = properties.get(SOURCE_TURRET_SELECTED_AMMO_KEY, [])",
            "return float(world_speed_fn.call(data)) if not data.is_empty() and world_speed_fn.is_valid() else 0.0",
            "return selected_ammo_stack_count(game.get(SOURCE_TURRET_SELECTED_AMMO_STACKS_KEY), selected_turret_cell_key(game))",
            "return str(stack.get(SOURCE_TURRET_SELECTED_ITEM_KEY, \"\")) if typeof(stack) == TYPE_DICTIONARY else \"\"",
        ]:
            with self.subTest(implementation_marker=implementation_marker):
                self.assertIn(implementation_marker, selected_ammo_source)
                self.assertNotIn(implementation_marker, runtime_source)

