    def test_source_turret_runtime_selected_ammo_callbacks_use_registry(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        runtime_state = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretRuntimeState.gd"
        selected_ammo_state = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretSelectedAmmoRuntimeState.gd"
        selected_ammo_source_text_state = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretSelectedAmmoSourceTextState.gd"
        source = self._port_game_turret_runtime_source()
        port_source = port_game.read_text(encoding="utf-8")
        runtime_source = runtime_state.read_text(encoding="utf-8")
        selected_ammo_source = selected_ammo_state.read_text(encoding="utf-8")
        selected_ammo_source_text = selected_ammo_source_text_state.read_text(encoding="utf-8") if selected_ammo_source_text_state.exists() else ""

        self.assertIn("static func default_callbacks_state(game: Object) -> Dictionary:", runtime_source)
        callbacks_body = self._method_body(runtime_source, "static func default_callbacks_state(game: Object) -> Dictionary:")
        selected_callbacks_body = self._method_body(selected_ammo_source, "static func default_callbacks_state(game: Object) -> Dictionary:")
        expected_callbacks = {
            "SOURCE_TURRET_RUNTIME_LIFETIME_SECONDS": ("lifetime_seconds", "source_bullet_lifetime_seconds"),
            "SOURCE_TURRET_RUNTIME_WORLD_SPEED": ("world_speed", "source_bullet_world_speed"),
            "SOURCE_TURRET_RUNTIME_DIMENSIONS": ("dimensions", "source_bullet_dimensions"),
            "SOURCE_TURRET_RUNTIME_HIT_SIZE": ("hit_size", "source_bullet_hit_size"),
            "SOURCE_TURRET_RUNTIME_DAMAGE": ("damage", "source_bullet_damage"),
            "SOURCE_TURRET_RUNTIME_AMMO_MULTIPLIER": ("ammo_multiplier", "source_bullet_ammo_multiplier"),
            "SOURCE_TURRET_RUNTIME_RELOAD_MULTIPLIER": ("reload_multiplier", "source_bullet_reload_multiplier"),
            "SOURCE_TURRET_RUNTIME_RANGE_CHANGE": ("range_change", "source_bullet_range_change"),
        }
        self.assertIn("static func runtime_method_names(game: Object) -> Dictionary:", runtime_source)
        self.assertIn("if game.has_method(SOURCE_TURRET_RUNTIME_METHOD_NAMES_METHOD):", selected_ammo_source)
        self.assertIn("static func runtime_method_name(method_names: Dictionary, key: String, fallback_name: String) -> String:", runtime_source)
        self.assertIn("return source_turret_selected_ammo_runtime_state.default_callbacks_state(game)", callbacks_body)
        self.assertIn("var method_names := runtime_method_names(game)", selected_callbacks_body)
        self.assertNotIn('Callable(game, "source_', callbacks_body)
        for prefix, (key, method_name) in expected_callbacks.items():
            with self.subTest(key=key):
                self.assertIn(f'const {prefix}_KEY := "{key}"', selected_ammo_source_text)
                self.assertIn(f'const {prefix}_FALLBACK := "{method_name}"', selected_ammo_source_text)
                self.assertIn(f"const {prefix}_KEY := source_turret_selected_ammo_source_text_state.{prefix}_KEY", selected_ammo_source)
                self.assertIn(f"const {prefix}_FALLBACK := source_turret_selected_ammo_source_text_state.{prefix}_FALLBACK", selected_ammo_source)
                self.assertIn(f"{prefix}_KEY: Callable(game, runtime_method_name(method_names, {prefix}_KEY, {prefix}_FALLBACK))", selected_callbacks_body)

        expected_delegates = {
            "func selected_turret_ammo_lifetime_seconds() -> float:": 'return source_turret_runtime_state.selected_ammo_lifetime_seconds_for_game(self)',
            "func selected_turret_ammo_world_speed() -> float:": 'return source_turret_runtime_state.selected_ammo_world_speed_for_game(self)',
            "func selected_turret_ammo_dimensions() -> Dictionary:": 'return source_turret_runtime_state.selected_ammo_dimensions_for_game(self)',
            "func selected_turret_ammo_hit_size() -> float:": 'return source_turret_runtime_state.selected_ammo_hit_size_for_game(self)',
            "func selected_turret_ammo_damage() -> float:": 'return source_turret_runtime_state.selected_ammo_damage_for_game(self)',
            "func selected_turret_ammo_multiplier() -> float:": 'return source_turret_runtime_state.selected_ammo_multiplier_for_game(self)',
            "func selected_turret_ammo_reload_multiplier() -> float:": 'return source_turret_runtime_state.selected_ammo_reload_multiplier_for_game(self)',
            "func selected_turret_ammo_range_change() -> float:": 'return source_turret_runtime_state.selected_ammo_range_change_for_game(self)',
        }
        for signature, delegate in expected_delegates.items():
            with self.subTest(signature=signature):
                method_body = self._method_body(source, signature)
                self.assertIn(delegate, method_body)
                self.assertNotIn("var callbacks := source_turret_runtime_state.default_callbacks_state(self)", method_body)
                self.assertNotIn("Callable(self,", method_body)
                self.assertNotIn(signature, port_source)

        expected_game_helpers = {
            "lifetime_seconds": "static func selected_ammo_lifetime_seconds_for_game(game: Object) -> float:",
            "world_speed": "static func selected_ammo_world_speed_for_game(game: Object) -> float:",
            "dimensions": "static func selected_ammo_dimensions_for_game(game: Object) -> Dictionary:",
            "hit_size": "static func selected_ammo_hit_size_for_game(game: Object) -> float:",
            "damage": "static func selected_ammo_damage_for_game(game: Object) -> float:",
            "ammo_multiplier": "static func selected_ammo_multiplier_for_game(game: Object) -> float:",
            "reload_multiplier": "static func selected_ammo_reload_multiplier_for_game(game: Object) -> float:",
            "range_change": "static func selected_ammo_range_change_for_game(game: Object) -> float:",
        }
        for key, helper_signature in expected_game_helpers.items():
            with self.subTest(helper=key):
                self.assertIn(helper_signature, selected_ammo_source)
                helper_body = self._method_body(selected_ammo_source, helper_signature)
                self.assertNotIn('callbacks.get("', helper_body)

