    def test_source_turret_runtime_property_stats_owns_property_stat_runtime(self):
        runtime_state = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretRuntimeState.gd"
        runtime_core = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretRuntime.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretRuntimePropertyStatsState.gd"
        source_text_state = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretSourceTextState.gd"
        runtime_source = runtime_state.read_text(encoding="utf-8") if runtime_state.exists() else ""
        runtime_core_source = runtime_core.read_text(encoding="utf-8") if runtime_core.exists() else ""
        module_source = module.read_text(encoding="utf-8") if module.exists() else ""

        self.assertTrue(module.exists(), "SourceTurretRuntimePropertyStatsState.gd must own turret property stat runtime")
