        proof_scene = ROOT / "godot-mindustry" / "tools" / "runtime_proofs" / "TurretCombatModuleProof.tscn"

        self.assertTrue(combat_state.exists())
        self.assertTrue(aim_state.exists())
        self.assertTrue(aim_callback_state.exists(), "SourceTurretAimCallbackState.gd must own turret aim callback keys and wrappers")
        self.assertTrue(proof_script.exists())
        self.assertTrue(proof_scene.exists())
        combat_source = combat_state.read_text(encoding="utf-8")
        aim_source = aim_state.read_text(encoding="utf-8") if aim_state.exists() else ""
        aim_callback_source = aim_callback_state.read_text(encoding="utf-8") if aim_callback_state.exists() else ""
        proof_source = proof_script.read_text(encoding="utf-8")
        callbacks_body = self._method_body(aim_source, "static func default_callbacks_state(game: Object) -> Dictionary:")
        self.assertIn("TURRET_COMBAT_MODULE_PROOF", proof_source)
        self.assertIn('const source_turret_aim_state := preload("res://src/game/SourceTurretAimState.gd")', combat_source)
        self.assertIn('const source_turret_aim_callback_state := preload("res://src/game/SourceTurretAimCallbackState.gd")', aim_source)
        self.assertIn("static func runtime_method_names(game: Object) -> Dictionary:", aim_source)
        self.assertIn('if game.has_method("_turret_combat_method_names"):', aim_source)
        self.assertNotIn('if game.has_method("_turret_combat_method_names"):', combat_source)
        self.assertIn("static func runtime_method_name(method_names: Dictionary, key: String, fallback_name: String) -> String:", aim_source)
        self.assertIn("var method_names := runtime_method_names(game)", callbacks_body)
        self.assertNotIn('Callable(game, "source_', callbacks_body)
        self.assertIn("class_name SourceTurretAimCallbackState", aim_callback_source)
        self.assertIn('const source_geometry_callback_registry := preload("res://src/game/SourceGeometryCallbackRegistry.gd")', aim_callback_source)
        self.assertIn("static func callback_registry() -> Dictionary:", aim_callback_source)
        self.assertIn('const SOURCE_MOVE_ANGLE_TOWARD_CANONICAL_WRAPPER := "source_arc_angles_move_toward(current_degrees, target_degrees, max_delta)"', aim_callback_source)
        self.assertIn("const SOURCE_MOVE_ANGLE_TOWARD_CANONICAL_WRAPPER := source_turret_aim_callback_state.SOURCE_MOVE_ANGLE_TOWARD_CANONICAL_WRAPPER", aim_source)
