    def test_port_game_exposes_turret_simulation_runtime_proof(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretSimulationState.gd"
        source = port_game.read_text(encoding="utf-8") + "\n" + self._port_game_port_bridge_chain_source()
        module_source = module.read_text(encoding="utf-8")
        proof_script = ROOT / "godot-mindustry" / "tools" / "runtime_proofs" / "TurretSimulationModuleProof.gd"
        proof_scene = ROOT / "godot-mindustry" / "tools" / "runtime_proofs" / "TurretSimulationModuleProof.tscn"
        turret_body = self._method_body(source, "func simulate_turrets(delta: float) -> void:")

        self.assertIn("func simulate_turrets(delta: float) -> void:", source)
        self.assertIn("\tsource_game_simulation_turret_state.simulate_turrets(self, delta)", turret_body)
        self.assertNotIn("for cell in turret_cells:", turret_body)
        self.assertIn("static func simulate_turrets(game, delta: float) -> void:", module_source)
        self.assertIn("for cell in turret_cells:", module_source)
        self.assertIn("var fire_context := turret_fire_context(game, cell, key, duo, delta, callbacks)", module_source)
        self.assertIn("var turret_step_state := turret_fire_from_context(fire_context)", module_source)
        self.assertIn("static func turret_fire_state(cell: Vector2i, delta: float, turret, current_rotation: float, cooldown: float, data: Dictionary, callbacks: Dictionary, tick_rate: float) -> Dictionary:", module_source)
        self.assertIn("static func turret_fire_context(game, cell: Vector2i, key: String, turret, seconds: float, callbacks: Dictionary) -> Dictionary:", module_source)
