    def test_port_game_source_drill_delay_matches_get_drill_time(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockMetadataState.gd"
