        self._assert_source_consts_in_helper_not_port(source, drill_runtime_source, [
            'const SOURCE_DRILL_DELAY_METHOD := "public float getDrillTime(Item item){"',
            'const SOURCE_DRILL_DELAY_RESULT := "return (drillTime + hardnessDrillMultiplier * item.hardness) / drillMultipliers.get(item, 1f);"',
            'const SOURCE_DRILL_DELAY_HARDNESS_MULTIPLIER_FIELD := "public float hardnessDrillMultiplier = 50f;"',
            'const SOURCE_DRILL_DELAY_DRILL_TIME_COMMENT := "Base time to drill one ore, in frames."',
            'const SOURCE_DRILL_DELAY_DRILL_TIME_FIELD := "public float drillTime = 300;"',
            'const SOURCE_DRILL_DELAY_DRILL_MULTIPLIERS_COMMENT := "Multipliers of drill speed for each item. Defaults to 1."',
            'const SOURCE_DRILL_DELAY_DRILL_MULTIPLIERS_FIELD := "public ObjectFloatMap<Item> drillMultipliers = new ObjectFloatMap<>();"',
            'const SOURCE_DRILL_DELAY_ITEM_HARDNESS_COMMENT := "drill hardness of the item"',
            'const SOURCE_DRILL_DELAY_ITEM_HARDNESS_FIELD := "public int hardness = 0;"',
        ])
        self.assertIn("const SOURCE_DRILL_DELAY_DRILL_TIME_DEFAULT := source_factory_defaults.DRILL_DELAY_DRILL_TIME_DEFAULT", helper_source)
        self.assertIn("const SOURCE_DRILL_DELAY_ITEM_HARDNESS_DEFAULT := source_factory_defaults.DRILL_DELAY_ITEM_HARDNESS_DEFAULT", helper_source)
        self.assertNotIn("const SOURCE_DRILL_DELAY_DRILL_TIME_DEFAULT :=", source)
        self.assertNotIn("const SOURCE_DRILL_DELAY_ITEM_HARDNESS_DEFAULT :=", source)
        self.assertIn("static func block_drill_delay_state(block_id: String, item_id: String, content_catalog) -> Dictionary:", helper_source)
        self.assertIn("var block_props := block_properties(block)", helper_source)
        self.assertIn("var item_props := block_properties(item)", helper_source)
        self.assertIn('var drill_multipliers = block_props.get("drillMultipliers", {})', helper_source)
        self.assertIn("var drill_multiplier := 1.0", helper_source)
        self.assertIn("drill_multiplier = float(drill_multipliers.get(item_id, 1.0))", helper_source)
        self.assertIn('float(block_props.get("drillTime", SOURCE_DRILL_DELAY_DRILL_TIME_DEFAULT))', helper_source)
        self.assertIn('float(item_props.get("hardness", SOURCE_DRILL_DELAY_ITEM_HARDNESS_DEFAULT))', helper_source)
        self.assertNotIn('SOURCE_DRILL_HARDNESS_MULTIPLIER * float(item.properties.get("hardness", SOURCE_DRILL_DELAY_ITEM_HARDNESS_DEFAULT))', source)
        delay_body = self._method_body(source, "func source_drill_delay(block_id: String, item_id: String) -> float:")
        self.assertIn("return source_drill_runtime_state_script.drill_delay(block_id, item_id, content_catalog, source_drill_runtime_port_bridge_factory_defaults.DRILL_HARDNESS_MULTIPLIER)", delay_body)
        self.assertNotIn("var delay_state := source_block_metadata_state.block_drill_delay_state(block_id, item_id, content_catalog)", delay_body)
        self.assertIn("static func drill_delay(block_id: String, item_id: String, content_catalog, hardness_multiplier: float) -> float:", drill_runtime_source)
        self.assertIn("var delay_state := source_block_metadata_state.block_drill_delay_state(block_id, item_id, content_catalog)", drill_runtime_source)
        self.assertIn('float(delay_state.get("drill_time", source_block_metadata_state.SOURCE_DRILL_DELAY_DRILL_TIME_DEFAULT))', drill_runtime_source)
        self.assertIn('float(delay_state.get("item_hardness", source_block_metadata_state.SOURCE_DRILL_DELAY_ITEM_HARDNESS_DEFAULT))', drill_runtime_source)
        self.assertIn('float(delay_state.get("drill_multiplier", 1.0))', drill_runtime_source)

