        self.assertIn('var result = source_generated_class_runtime.call_java_method(SOURCE_DRILL_GENERATED_CLASS, SOURCE_DRILL_GET_DRILL_TIME_JAVA_METHOD_GET_DRILL_TIME_6, [drill_time, hardness_multiplier, item_hardness, drill_multiplier], null)', drill_module_source)
        self.assertNotIn('var result = source_generated_class_runtime.call_java_method(SOURCE_DRILL_GENERATED_CLASS, "java_method_getDrillTime_6", [drill_time, hardness_multiplier, item_hardness, drill_multiplier], null)', drill_module_source)
