        bridge_source = bridge.read_text(encoding="utf-8") if bridge.exists() else ""
        port_source = port_game.read_text(encoding="utf-8")
        body = bridge_source.split("func source_building_dump_liquid_routing_gate_state(liquid: Variant, proximity_size: int, dump_cursor: int, output_dir: int, rotation_value: int, relative_to_by_index: Array, destination_present_by_index: Array, other_has_liquids_by_index: Array, can_dump_liquid_by_index: Array, other_liquids_present_by_index: Array) -> Dictionary:", 1)[1].split("\nfunc ", 1)[0]

        self.assertIn("static func default_callbacks_state(game: Object) -> Dictionary:", dump_module_source)
        self.assertIn('const SOURCE_BUILDING_LIQUID_INCREMENT_DUMP_CURSOR_METHOD_KEY := "increment_dump_cursor"', dump_module_source)
        self.assertIn('const SOURCE_BUILDING_LIQUID_INCREMENT_DUMP_CURSOR_METHOD_FALLBACK := "source_increment_dump_cursor"', dump_module_source)
        self.assertIn("static func runtime_method_names(game: Object) -> Dictionary:", dump_module_source)
        self.assertIn('game.has_method("_building_liquid_state_method_names")', dump_module_source)
        self.assertIn("static func runtime_method_name(method_names: Dictionary, key: String, fallback_name: String) -> String:", dump_module_source)
        self.assertIn("var method_names := runtime_method_names(game)", dump_module_source)
        self.assertIn("var increment_dump_cursor_method := runtime_method_name(method_names, SOURCE_BUILDING_LIQUID_INCREMENT_DUMP_CURSOR_METHOD_KEY, SOURCE_BUILDING_LIQUID_INCREMENT_DUMP_CURSOR_METHOD_FALLBACK)", dump_module_source)
        self.assertIn("SOURCE_BUILDING_LIQUID_INCREMENT_DUMP_CURSOR_METHOD_KEY: Callable(game, increment_dump_cursor_method)", dump_module_source)
        self.assertNotIn('"increment_dump_cursor": Callable(game, "source_increment_dump_cursor")', dump_module_source)
        self.assertIn("static func game_dump_liquid_routing_gate_state(game: Object, liquid: Variant, proximity_size: int, dump_cursor: int, output_dir: int, rotation_value: int, relative_to_by_index: Array, destination_present_by_index: Array, other_has_liquids_by_index: Array, can_dump_liquid_by_index: Array, other_liquids_present_by_index: Array) -> Dictionary:", dump_module_source)
        self.assertIn("default_callbacks_state(game).get(SOURCE_BUILDING_LIQUID_INCREMENT_DUMP_CURSOR_METHOD_KEY, Callable())", dump_module_source)
        self.assertIn("return source_building_liquid_dump_state.default_callbacks_state(game)", helper_source)
        self.assertIn("return source_building_liquid_state.game_dump_liquid_routing_gate_state(self, liquid, proximity_size, dump_cursor, output_dir, rotation_value, relative_to_by_index, destination_present_by_index, other_has_liquids_by_index, can_dump_liquid_by_index, other_liquids_present_by_index)", body)
        self.assertNotIn('source_building_liquid_state.default_callbacks_state(self).get("increment_dump_cursor", Callable())', body)
        self.assertNotIn('Callable(self, "source_increment_dump_cursor")', body)
        self.assertNotIn("func source_building_dump_liquid_routing_gate_state(", port_source)

