    def test_source_building_set_prop_generated_bridges_use_source_text_owner(self):
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingSetPropState.gd"
        source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingSetPropSourceTextState.gd"
        module_source = module.read_text(encoding="utf-8") if module.exists() else ""
        source_text_source = source_text.read_text(encoding="utf-8") if source_text.exists() else ""

        self.assertTrue(module.exists(), "SourceBuildingSetPropState.gd must own Building setProp generated bridge state")
        self.assertTrue(source_text.exists(), "SourceBuildingSetPropSourceTextState.gd must own Building setProp generated ids")
        self.assertIn('const source_building_source_text_state := preload("res://src/game/SourceBuildingSourceTextState.gd")', module_source)
        self.assertIn('const source_building_set_prop_source_text_state := preload("res://src/game/SourceBuildingSetPropSourceTextState.gd")', module_source)
        self.assertIn("const SOURCE_BUILDING_COMP_GENERATED_CLASS := source_building_source_text_state.SOURCE_BUILDING_COMP_GENERATED_CLASS", module_source)
        self.assertIn("static func _building_comp_call(generated_method: String, generated_args: Array) -> Variant:", module_source)
        self.assertIn("source_generated_class_runtime.call_java_method(SOURCE_BUILDING_COMP_GENERATED_CLASS, generated_method, generated_args, null)", module_source)
        self.assertNotIn('call_java_method("res://src/generated/classes/mindustry/entities/comp/BuildingComp.gd"', module_source)
        for method_value, (method_const, owner_const) in self._building_set_prop_generated_bridge_consts().items():
            generated_owner = "building_comp." + method_value
            self.assertIn(f'const {method_const} := "{method_value}"', source_text_source)
            self.assertIn(f'const {owner_const} := "{generated_owner}"', source_text_source)
            self.assertIn(f"const {method_const} := source_building_set_prop_source_text_state.{method_const}", module_source)
            self.assertIn(f"const {owner_const} := source_building_set_prop_source_text_state.{owner_const}", module_source)
            self.assertNotIn(f'_building_comp_call("{method_value}"', module_source)
            self.assertNotIn(f'"generated_owner": "{generated_owner}"', module_source)

