    def test_source_building_time_source_text_state_owns_generated_bridge_literals(self):
        owner = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingTimeSourceTextState.gd"
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingTimeState.gd"
        owner_source = owner.read_text(encoding="utf-8") if owner.exists() else ""
        helper_source = helper.read_text(encoding="utf-8") if helper.exists() else ""

        self.assertTrue(owner.exists(), "SourceBuildingTimeSourceTextState.gd must own Building time generated bridge source literals")
        self.assertIn("class_name SourceBuildingTimeSourceTextState", owner_source)
        self.assertIn('const source_building_time_source_text_state := preload("res://src/game/SourceBuildingTimeSourceTextState.gd")', helper_source)
        for generated_method, (method_const, owner_const) in self._building_time_generated_bridge_consts().items():
            generated_owner = "building_comp." + generated_method
            with self.subTest(generated_method=generated_method):
                self.assertIn(f'const {method_const} := "{generated_method}"', owner_source)
                self.assertIn(f'const {owner_const} := "{generated_owner}"', owner_source)
                self.assertIn(f"const {method_const} := source_building_time_source_text_state.{method_const}", helper_source)
                self.assertIn(f"const {owner_const} := source_building_time_source_text_state.{owner_const}", helper_source)
                self.assertNotIn(f'_building_comp_call("{generated_method}"', helper_source)
                self.assertNotIn(f'"generated_owner": "{generated_owner}"', helper_source)

