    def test_runtime_proofs_do_not_use_short_watchdog_timers(self):
        proof_root = ROOT / "godot-mindustry" / "tools" / "runtime_proofs"
        offenders = []

        for proof in sorted(proof_root.glob("*.gd")):
            proof_source = proof.read_text(encoding="utf-8")
            for timer in ("2.0", "6.0", "10.0"):
                needle = f"create_timer({timer})"
                if needle in proof_source:
                    offenders.append(f"{proof.name}:{needle}")

