    def test_port_game_delegates_building_interaction_source_state_to_module(self):
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingInteractionState.gd"
        bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingInteractionPortBridge.gd"
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"

        self.assertTrue(helper.exists(), "source_building_interaction_state.gd helper must own Building default callback source state block")
        self.assertTrue(bridge.exists(), "SourceBuildingInteractionPortBridge.gd must own compact building interaction compatibility wrappers")
        helper_source = helper.read_text(encoding="utf-8") if helper.exists() else ""
        bridge_source = bridge.read_text(encoding="utf-8") if bridge.exists() else ""
        port_source = port_game.read_text(encoding="utf-8")

        self.assertIn("class_name SourceBuildingInteractionState", helper_source)
        self.assertIn('const source_building_interaction_state := preload("res://src/game/SourceBuildingInteractionState.gd")', bridge_source)
        self.assertNotIn('const source_building_interaction_state := preload("res://src/game/SourceBuildingInteractionState.gd")', port_source)
        for method_name in (
            "is_commandable_state",
            "is_payload_state",
            "overwrote_state",
            "on_removed_state",
            "unit_on_state",
            "unit_on_any_state",
            "unit_removed_state",
            "puddle_on_state",
            "tapped_state",
        ):
            self.assertIn("static func " + method_name, helper_source)

        delegations = {
            "func source_building_is_commandable_state(block_commandable: bool) -> bool:": "\treturn source_building_interaction_state.is_commandable_state(block_commandable)",
            "func source_building_is_payload_state(tile_is_empty_tile: bool) -> bool:": "\treturn source_building_interaction_state.is_payload_state(tile_is_empty_tile)",
            "func source_building_overwrote_state(previous_state: Variant) -> Dictionary:": "\treturn source_building_interaction_state.overwrote_state(previous_state)",
            "func source_building_on_removed_state(current_state: Variant) -> Dictionary:": "\treturn source_building_interaction_state.on_removed_state(current_state)",
            "func source_building_unit_on_state(unit_state: Variant) -> Variant:": "\treturn source_building_interaction_state.unit_on_state(unit_state)",
            "func source_building_unit_on_any_state(unit_state: Variant) -> Variant:": "\treturn source_building_interaction_state.unit_on_any_state(unit_state)",
            "func source_building_unit_removed_state(unit_state: Variant) -> Variant:": "\treturn source_building_interaction_state.unit_removed_state(unit_state)",
            "func source_building_puddle_on_state(puddle_state: Variant) -> Dictionary:": "\treturn source_building_interaction_state.puddle_on_state(puddle_state)",
            "func source_building_tapped_state(current_state: Variant) -> Dictionary:": "\treturn source_building_interaction_state.tapped_state(current_state)",
        }
        for signature, delegation in delegations.items():
            self.assertNotIn(signature, port_source)
            method_body = self._method_body(bridge_source, signature)
            self.assertIn(delegation, method_body)

