        display_source = display_helper.read_text(encoding="utf-8") if display_helper.exists() else ""
        display_bridge_source = display_bridge.read_text(encoding="utf-8") if display_bridge.exists() else ""
        configure_source = configure_helper.read_text(encoding="utf-8") if configure_helper.exists() else ""
        configure_bridge_source = configure_bridge.read_text(encoding="utf-8") if configure_bridge.exists() else ""
        port_source = port_game.read_text(encoding="utf-8")

        self.assertIn("class_name SourceBuildingDisplayState", display_source)
        self.assertIn("class_name SourceBuildingConfigureState", configure_source)
        self.assertIn('extends "res://src/game/SourceBuildingItemPayloadPortBridge.gd"', (ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingCorePortBridge.gd").read_text(encoding="utf-8"))
        self.assertIn('extends "res://src/game/SourceBuildingCompStatePortBridge.gd"', (ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingItemPayloadPortBridge.gd").read_text(encoding="utf-8"))
        self.assertIn('extends "res://src/game/SourceConstructBuildPortBridge.gd"', display_bridge_source)
        self.assertIn("SourceBuildingDisplayPortBridge.gd", self._actual_port_game_port_bridge_chain())
        self.assertIn('const source_building_display_state := preload("res://src/game/SourceBuildingDisplayState.gd")', display_bridge_source)
        self.assertNotIn('const source_building_display_state := preload("res://src/game/SourceBuildingDisplayState.gd")', port_source)
        self.assertIn('const source_building_configure_state := preload("res://src/game/SourceBuildingConfigureState.gd")', configure_bridge_source)
        self.assertNotIn('const source_building_configure_state := preload("res://src/game/SourceBuildingConfigureState.gd")', port_source)
        for method_name in (
            "runtime_method_names",
            "runtime_method_name",
            "default_callbacks_state",
            "game_display_flow_rate_label",
            "fixed_one_decimal",
            "display_name_state",
            "display_icon_state",
            "flow_items_state",
            "display_consumption_state",
            "display_bars_state",
            "display_ui_gates_state",
            "display_flow_rate_label",
        ):
            self.assertIn("static func " + method_name, display_source)
        for method_name in (
            "configured_type_state",
            "configured_last_access_state",
            "configured_direct_handler_state",
            "configured_copy_config_state",
            "on_configure_build_tapped_state",
            "on_configure_tapped_state",
            "on_configure_closed_state",
            "configure_menu_visibility_state",
            "should_show_configure_state",
            "should_hide_configure_state",
        ):
            self.assertIn("static func " + method_name, configure_source)

        delegations = {
            "func source_building_display_name_state(localized_name: String, team_is_derelict: bool, team_is_player: bool, team_emoji: String, derelict_label: String) -> String:": "\treturn source_building_display_state.display_name_state(localized_name, team_is_derelict, team_is_player, team_emoji, derelict_label)",
            "func source_building_display_icon_state(block_ui_icon: Variant) -> Variant:": "\treturn source_building_display_state.display_icon_state(block_ui_icon)",
            "func source_building_flow_items_state(items_module: Variant) -> Variant:": "\treturn source_building_display_state.flow_items_state(items_module)",
            "func source_building_display_consumption_state(consumers: Array, self_state: Variant) -> Dictionary:": "\treturn source_building_display_state.display_consumption_state(consumers, self_state)",
            "func source_building_display_bars_state(bar_results: Array) -> Dictionary:": "\treturn source_building_display_state.display_bars_state(bar_results)",
            "func source_building_display_ui_gates_state(team_is_player: bool, block_category: String, block_display_flow: bool, net_active: bool, has_last_accessed: bool) -> Dictionary:": "\treturn source_building_display_state.display_ui_gates_state(team_is_player, block_category, block_display_flow, net_active, has_last_accessed)",
            "func source_building_display_flow_rate_label(flow_rate: float, per_second_label: String) -> String:": "\treturn source_building_display_state.game_display_flow_rate_label(self, flow_rate, per_second_label)",
        }
        for signature, delegation in delegations.items():
            self.assertNotIn(signature, port_source)
            method_body = self._method_body(display_bridge_source, signature)
            self.assertIn(delegation, method_body)

        configure_delegations = {
            "func source_building_configured_type_state(value_state: Dictionary) -> String:": "\treturn source_building_configure_state.configured_type_state(value_state)",
            "func source_building_configured_last_access_state(builder_state: Dictionary, current_last_accessed: String) -> Dictionary:": "\treturn source_building_configure_state.configured_last_access_state(builder_state, current_last_accessed)",
            "func source_building_configured_direct_handler_state(has_configuration: bool, configured_type: String, value_state: Variant) -> Dictionary:": "\treturn source_building_configure_state.configured_direct_handler_state(has_configuration, configured_type, value_state)",
            "func source_building_configured_copy_config_state(value_is_building: bool, copied_config: Variant, copied_config_is_building: bool) -> Dictionary:": "\treturn source_building_configure_state.configured_copy_config_state(value_is_building, copied_config, copied_config_is_building)",
            "func source_building_on_configure_build_tapped_state(clear_on_double_tap: bool, same_building: bool) -> Dictionary:": "\treturn source_building_configure_state.on_configure_build_tapped_state(clear_on_double_tap, same_building)",
            "func source_building_on_configure_tapped_state(x: float, y: float) -> Dictionary:": "\treturn source_building_configure_state.on_configure_tapped_state(x, y)",
            "func source_building_on_configure_closed_state() -> Dictionary:": "\treturn source_building_configure_state.on_configure_closed_state()",
            "func source_building_configure_menu_visibility_state(_player: Variant) -> Dictionary:": "\treturn source_building_configure_state.configure_menu_visibility_state(_player)",
            "func source_building_should_show_configure_state(_player: Variant) -> Dictionary:": "\treturn source_building_configure_state.should_show_configure_state(_player)",
            "func source_building_should_hide_configure_state(_player: Variant) -> Dictionary:": "\treturn source_building_configure_state.should_hide_configure_state(_player)",
        }
        for signature, delegation in configure_delegations.items():
            method_body = self._method_body(configure_bridge_source, signature)
            self.assertIn(delegation, method_body)

        for source_owner in (
            "port_game.source_building_display_consumption_state",
            "port_game.source_building_display_bars_state",
        ):
            expected_source_owner = "source_runtime_owner_registry.PORT_GAME_" + source_owner.removeprefix("port_game.").upper()
            self.assertIn('"source_owner": ' + expected_source_owner, display_source)

        callbacks_body = self._method_body(display_source, "static func default_callbacks_state(game: Object) -> Dictionary:")
        self.assertIn('if game.has_method("_building_display_method_names"):', display_source)
        self.assertIn("var method_names := runtime_method_names(game)", callbacks_body)
        self.assertNotIn('Callable(game, "source_', callbacks_body)
        self.assertIn('const SOURCE_BUILDING_DISPLAY_FIXED_ONE_DECIMAL_KEY := "fixed_one_decimal"', display_source)
        self.assertIn('const SOURCE_BUILDING_DISPLAY_FIXED_ONE_DECIMAL_FALLBACK := "source_arc_strings_fixed_one_decimal"', display_source)
        self.assertIn("SOURCE_BUILDING_DISPLAY_FIXED_ONE_DECIMAL_KEY: Callable(game, runtime_method_name(method_names, SOURCE_BUILDING_DISPLAY_FIXED_ONE_DECIMAL_KEY, SOURCE_BUILDING_DISPLAY_FIXED_ONE_DECIMAL_FALLBACK))", callbacks_body)

