    def test_port_game_delegates_building_display_generated_bridges_to_module(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingDisplayState.gd"
        port_source = port_game.read_text(encoding="utf-8")
        module_source = module.read_text(encoding="utf-8")

        cases = {
            "generated_building_comp_get_display_name_bridge_state(localized_name: String, team_is_derelict: bool, team_is_player: bool, team_emoji: String, derelict_label: String)": (
                "localized_name, team_is_derelict, team_is_player, team_emoji, derelict_label",
                "SOURCE_BUILDING_DISPLAY_NAME_JAVA_METHOD",
                "java_method_getDisplayName_157",
                "var canonical = display_name_state(localized_name, team_is_derelict, team_is_player, team_emoji, derelict_label)",
                "port_game.source_building_display_name_state",
                "SOURCE_BUILDING_DISPLAY_NAME_GENERATED_OWNER",
                "building_comp.java_method_getDisplayName_157",
            ),
            "generated_building_comp_flow_items_bridge_state(items_module: Variant)": (
                "items_module",
                "SOURCE_BUILDING_DISPLAY_FLOW_ITEMS_JAVA_METHOD",
                "java_method_flowItems_159",
                "var canonical = flow_items_state(items_module)",
                "port_game.source_building_flow_items_state",
                "SOURCE_BUILDING_DISPLAY_FLOW_ITEMS_GENERATED_OWNER",
                "building_comp.java_method_flowItems_159",
            ),
            "generated_building_comp_display_consumption_bridge_state(consumers: Array, self_state: Variant)": (
                "consumers, self_state",
                "SOURCE_BUILDING_DISPLAY_CONSUMPTION_JAVA_METHOD",
                "java_method_displayConsumption_161",
                "var canonical = display_consumption_state(consumers, self_state)",
                "port_game.source_building_display_consumption_state",
                "SOURCE_BUILDING_DISPLAY_CONSUMPTION_GENERATED_OWNER",
                "building_comp.java_method_displayConsumption_161",
            ),
            "generated_building_comp_display_bars_bridge_state(bar_results: Array)": (
                "bar_results",
                "SOURCE_BUILDING_DISPLAY_BARS_JAVA_METHOD",
                "java_method_displayBars_162",
                "var canonical = display_bars_state(bar_results)",
                "port_game.source_building_display_bars_state",
                "SOURCE_BUILDING_DISPLAY_BARS_GENERATED_OWNER",
                "building_comp.java_method_displayBars_162",
            ),
        }
        source_text_source = (ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingSourceTextState.gd").read_text(encoding="utf-8")
        for signature_tail, (args, generated_method_const, generated_method_literal, canonical_call, source_owner, generated_owner_const, generated_owner_literal) in cases.items():
            with self.subTest(signature=signature_tail):
                func_name = signature_tail.split("(", 1)[0]
                port_signature = f"func {signature_tail} -> Dictionary:"
                module_signature = f"static func {signature_tail} -> Dictionary:"
                port_body = self._method_body(port_source, port_signature)
                module_body = self._static_method_body(module_source, module_signature)
                self.assertIn(module_signature, module_source)
                self.assertIn(f"\treturn source_building_display_state.{func_name}({args})", port_body)
                self.assertNotIn("ResourceLoader.load(", port_body)
                self.assertNotIn("java_method_", port_body)
                self.assertIn('const source_building_source_text_state := preload("res://src/game/SourceBuildingSourceTextState.gd")', module_source)
                self.assertIn("const SOURCE_BUILDING_COMP_GENERATED_CLASS := source_building_source_text_state.SOURCE_BUILDING_COMP_GENERATED_CLASS", module_source)
                self.assertNotIn('const SOURCE_BUILDING_COMP_GENERATED_CLASS := "res://src/generated/classes/mindustry/entities/comp/BuildingComp.gd"', module_source)
                self.assertIn("static func _building_comp_call(generated_method: String, generated_args: Array) -> Variant:", module_source)
                self.assertIn("source_generated_class_runtime.call_java_method(SOURCE_BUILDING_COMP_GENERATED_CLASS, generated_method, generated_args, null)", module_source)
                self.assertNotIn('ResourceLoader.load("res://src/generated/classes/mindustry/entities/comp/BuildingComp.gd")', module_body)
                generated_call = f"var result = _building_comp_call({generated_method_const}, [{args}])"
                self.assertIn(generated_call, module_body)
                self.assertIn(f"const {generated_method_const} := source_building_source_text_state.{generated_method_const}", module_source)
                self.assertIn(f"const {generated_owner_const} := source_building_source_text_state.{generated_owner_const}", module_source)
                self.assertIn(f'const {generated_method_const} := "{generated_method_literal}"', source_text_source)
                self.assertIn(f'const {generated_owner_const} := "{generated_owner_literal}"', source_text_source)
                self.assertIn(canonical_call, module_body)
                expected_source_owner = "source_runtime_owner_registry.PORT_GAME_" + source_owner.removeprefix("port_game.").upper()
                self.assertIn(f'"source_owner": {expected_source_owner}', module_body)
                self.assertIn(f'"generated_owner": {generated_owner_const}', module_body)
                self.assertNotIn(f'_building_comp_call("{generated_method_literal}"', module_body)
                self.assertNotIn(f'"generated_owner": "{generated_owner_literal}"', module_body)

