    def test_source_building_efficiency_source_text_state_owns_efficiency_literals(self):
        owner = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingEfficiencySourceTextState.gd"
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingEfficiencyState.gd"
        owner_source = owner.read_text(encoding="utf-8") if owner.exists() else ""
        helper_source = helper.read_text(encoding="utf-8") if helper.exists() else ""

        self.assertTrue(owner.exists(), "SourceBuildingEfficiencySourceTextState.gd must own Building efficiency literals")
        self.assertIn("class_name SourceBuildingEfficiencySourceTextState", owner_source)
        self.assertIn('const source_building_efficiency_source_text_state := preload("res://src/game/SourceBuildingEfficiencySourceTextState.gd")', helper_source)
        for const_name, literal_value in {
            "SOURCE_BUILDING_UPDATE_EFFICIENCY_MULTIPLIER_COMMENT": "/** Called after efficiency is updated but before consumers are updated. Use to apply your own multiplier. */",
            "SOURCE_BUILDING_UPDATE_EFFICIENCY_MULTIPLIER_METHOD": "public void updateEfficiencyMultiplier(){",
            "SOURCE_BUILDING_UPDATE_EFFICIENCY_MULTIPLIER_SCALE": "float scale = efficiencyScale();",
            "SOURCE_BUILDING_UPDATE_EFFICIENCY_MULTIPLIER_EFFICIENCY": "efficiency *= scale;",
            "SOURCE_BUILDING_UPDATE_EFFICIENCY_MULTIPLIER_OPTIONAL": "optionalEfficiency *= scale;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_INITIAL_COMMENT": "//everything is valid when cheating",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_INITIAL_GUARD": "if(!block.hasConsumers || cheating()){",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_INITIAL_POTENTIAL": "potentialEfficiency = enabled && productionValid() ? 1f : 0f;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_INITIAL_EFFICIENCY": "efficiency = optionalEfficiency = shouldConsume() ? potentialEfficiency : 0f;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_INITIAL_POWER": "shouldConsumePower = true;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_INITIAL_MULTIPLIER": "updateEfficiencyMultiplier();",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_INITIAL_RETURN": "return;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_DISABLED_COMMENT": "//disabled -> nothing works",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_DISABLED_GUARD": "if(!enabled){",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_DISABLED_EFFICIENCIES": "potentialEfficiency = efficiency = optionalEfficiency = 0f;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_DISABLED_POWER": "shouldConsumePower = false;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_DISABLED_RETURN": "return;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_SETUP_UPDATE": "boolean update = shouldConsume() && productionValid();",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_SETUP_MIN": "float minEfficiency = 1f;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_SETUP_COMMENT": "//assume efficiency is 1 for the calculations below",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_SETUP_EFFICIENCIES": "efficiency = optionalEfficiency = 1f;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_SETUP_POWER": "shouldConsumePower = true;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_NON_OPTIONAL_COMMENT": "//first pass: get the minimum efficiency of any consumer",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_NON_OPTIONAL_LOOP": "for(var cons : block.nonOptionalConsumers){",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_NON_OPTIONAL_RESULT": "float result = cons.efficiency(self());",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_NON_OPTIONAL_POWER_GATE": "if(cons != block.consPower && result <= 0.0000001f){",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_NON_OPTIONAL_POWER_STATE": "shouldConsumePower = false;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_NON_OPTIONAL_MIN": "minEfficiency = Math.min(minEfficiency, result);",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_OPTIONAL_COMMENT": "//same for optionals",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_OPTIONAL_LOOP": "for(var cons : block.optionalConsumers){",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_OPTIONAL_MIN": "optionalEfficiency = Math.min(optionalEfficiency, cons.efficiency(self()));",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_EFFICIENCY_COMMENT": "//efficiency is now this minimum value",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_EFFICIENCY_ASSIGN": "efficiency = minEfficiency;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_EFFICIENCY_OPTIONAL_MIN": "optionalEfficiency = Math.min(optionalEfficiency, minEfficiency);",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_EFFICIENCY_POTENTIAL_ASSIGN": "potentialEfficiency = efficiency;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_EFFICIENCY_NO_UPDATE_ZERO": "efficiency = optionalEfficiency = 0f;",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_SECOND_MULTIPLIER": "updateEfficiencyMultiplier();",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_SECOND_COMMENT": "//second pass: update every consumer based on efficiency",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_SECOND_GUARD": "if(update && efficiency > 0){",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_SECOND_LOOP": "for(var cons : block.updateConsumers){",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_SECOND_UPDATE": "cons.update(self());",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_CALL_METHOD": "public void update(){",
            "SOURCE_BUILDING_UPDATE_CONSUMPTION_CALL": "updateConsumption();",
        }.items():
            self.assertIn(f'const {const_name} := "{literal_value}"', owner_source)
            self.assertIn(f"const {const_name} := source_building_efficiency_source_text_state.{const_name}", helper_source)
            self.assertNotIn(f'const {const_name} := "{literal_value}"', helper_source)

