        motion_source = motion.read_text(encoding="utf-8") if motion.exists() else ""
        registry_source = registry.read_text(encoding="utf-8") if registry.exists() else ""

        self.assertTrue(registry.exists(), "SourceUnitUpdateCallbackRegistry.gd must own unit-update callback key/fallback literals")
        self.assertIn("class_name SourceUnitUpdateCallbackRegistry", registry_source)
        self.assertIn('const source_geometry_callback_registry := preload("res://src/game/SourceGeometryCallbackRegistry.gd")', registry_source)
        self.assertIn('const source_math_callback_registry := preload("res://src/game/SourceMathCallbackRegistry.gd")', registry_source)
        self.assertIn('const source_unit_update_callback_registry := preload("res://src/game/SourceUnitUpdateCallbackRegistry.gd")', motion_source)
        self.assertNotIn('const source_unit_update_callback_registry := preload("res://src/game/SourceUnitUpdateCallbackRegistry.gd")', helper_source)
        expected_callbacks = {
            "SOURCE_UNIT_UPDATE_SIN_SCALED": ("sin_scaled", "source_arc_mathf_sin_scaled"),
            "SOURCE_UNIT_UPDATE_COS_SCALED": ("cos_scaled", "source_arc_mathf_cos_scaled"),
            "SOURCE_UNIT_UPDATE_VEC2_LIMIT": ("vec2_limit", "source_arc_vec2_limit"),
            "SOURCE_UNIT_UPDATE_VEC2_ANGLE": ("vec2_angle", "source_unit_vec2_angle"),
            "SOURCE_UNIT_UPDATE_ANGLES_MOVE_TOWARD": ("angles_move_toward", "source_arc_angles_move_toward"),
            "SOURCE_UNIT_UPDATE_ANGLES_ANGLE": ("angles_angle", "source_arc_angles_angle"),
        }
        for prefix, (key_value, fallback_value) in expected_callbacks.items():
            with self.subTest(prefix=prefix):
                geometry_names = {
                    "SOURCE_UNIT_UPDATE_ANGLES_MOVE_TOWARD": "MOVE_TOWARD_ANGLE",
                    "SOURCE_UNIT_UPDATE_ANGLES_ANGLE": "ANGLES_ANGLE",
                }
                math_names = {
                    "SOURCE_UNIT_UPDATE_VEC2_LIMIT": ("VEC2_LIMIT_KEY", "ARC_VEC2_LIMIT_FALLBACK"),
                }
                if prefix in geometry_names:
                    geometry_name = geometry_names[prefix]
                    self.assertIn(f"const {prefix}_KEY := source_geometry_callback_registry.{geometry_name}_KEY", registry_source)
                    self.assertIn(f"const {prefix}_FALLBACK := source_geometry_callback_registry.{geometry_name}_FALLBACK", registry_source)
                elif prefix in math_names:
                    key_name, fallback_name = math_names[prefix]
                    self.assertIn(f"const {prefix}_KEY := source_math_callback_registry.{key_name}", registry_source)
                    self.assertIn(f"const {prefix}_FALLBACK := source_math_callback_registry.{fallback_name}", registry_source)
                else:
                    self.assertIn(f'const {prefix}_KEY := "{key_value}"', registry_source)
                    self.assertIn(f'const {prefix}_FALLBACK := "{fallback_value}"', registry_source)
                self.assertIn(f"const {prefix}_KEY := source_unit_update_callback_registry.{prefix}_KEY", motion_source)
                self.assertIn(f"const {prefix}_FALLBACK := source_unit_update_callback_registry.{prefix}_FALLBACK", motion_source)
                self.assertNotIn(f'const {prefix}_KEY := "{key_value}"', motion_source)
                self.assertNotIn(f'const {prefix}_FALLBACK := "{fallback_value}"', motion_source)

