        self.assertIn('const source_unit_runtime_state := preload("res://src/game/SourceUnitRuntimeState.gd")', helper_source)
        for function_name in [
            "drowning_state",
            "type_hook_state",
            "heal_state",
            "heal_time_state",
            "captured_sector_death_state",
            "sound_loop_state",
            "unsupported_env_state",
            "abilities_loop_state",
            "ai_controller_server_gate_state",
            "invalid_controller_reset_state",
            "spawned_core_despawn_state",
        ]:
            with self.subTest(function=function_name):
                self.assertIn(f"static func {function_name}(", module_source)
        for alias in [
            "const SOURCE_UNIT_DROWN_HIT_SIZE_DIVISOR := source_unit_defaults.DROWN_HIT_SIZE_DIVISOR",
            "const SOURCE_UNIT_HEAL_TIME_DECAY_DIVISOR := source_unit_defaults.HEAL_TIME_DECAY_DIVISOR",
            "const SOURCE_UNIT_UPDATE_AI_CONTROLLER_CALL := source_unit_update_source_text_state.SOURCE_UNIT_UPDATE_AI_CONTROLLER_CALL",
            "const SOURCE_UNIT_HEAL_HEALTH_COMP_CLAMP := source_unit_update_source_text_state.SOURCE_UNIT_HEAL_HEALTH_COMP_CLAMP",
        ]:
            with self.subTest(alias=alias):
                self.assertIn(alias, module_source)
                self.assertNotIn(alias, helper_source)
        self.assertIsNone(
            re.search(r'^const SOURCE_UNIT_[A-Z0-9_]+ := "', module_source, re.MULTILINE),
            "SourceUnitRuntimeState.gd must re-export Unit Java source text from SourceUnitUpdateSourceTextState.gd instead of owning literal strings",
        )
        for delegate in [
            "return source_unit_runtime_state.drowning_state(floor_exists, floor_is_liquid, floor_drown_time, can_drown_value, current_drown_time, source_delta, hit_size, type_drown_time_multiplier, chance_delta_result, net_client)",
            "return source_unit_runtime_state.type_hook_state()",
            "return source_unit_runtime_state.heal_state(current_health, max_health, amount, current_was_healed)",
            "return source_unit_runtime_state.heal_time_state(was_healed_value, current_heal_time, source_delta)",
            "return source_unit_runtime_state.captured_sector_death_state(team_is_only_ai, state_is_campaign, sector_is_captured)",
            "return source_unit_runtime_state.sound_loop_state(headless_value, type_loop_sound, type_loop_sound_volume, type_move_sound, type_move_sound_volume, type_move_sound_pitch_min, type_move_sound_pitch_max, velocity_x, velocity_y, type_speed)",
            "return source_unit_runtime_state.unsupported_env_state(type_supports_env, dead_value)",
            "return source_unit_runtime_state.abilities_loop_state(ability_ids)",
            "return source_unit_runtime_state.ai_controller_server_gate_state(net_client_value, dead_value, should_update_controller_value, unit_id)",
            "return source_unit_runtime_state.invalid_controller_reset_state(controller_is_valid_value, unit_id)",
            "return source_unit_runtime_state.spawned_core_despawn_state(spawned_by_core_value, is_player_value, dead_value, unit_id)",
        ]:
            with self.subTest(delegate=delegate):
                self.assertIn(delegate, helper_source)
        for marker in [
            "var can_drown_on_floor := floor_exists and floor_is_liquid and floor_drown_time > 0.0 and can_drown_value",
            "var next_health := current_health + amount",
            "var velocity_len := sqrt(velocity_x * velocity_x + velocity_y * velocity_y)",
            "var guard := (not net_client_value) and (not dead_value) and should_update_controller_value",
        ]:
            with self.subTest(marker=marker):
                self.assertIn(marker, module_source)
                self.assertNotIn(marker, helper_source)

