        self.assertIn("if angle < 0.0:", math_state)
        self.assertIn("func source_arc_vec2_limit(vec: Vector2, limit: float) -> Vector2:", source)
        self.assertIn("return source_math_state.source_arc_vec2_limit(vec, limit)", source)
        self.assertNotIn("var limit2 := limit * limit", vec2_body)
        self.assertNotIn("return vec * sqrt(limit2 / len2)", vec2_body)
        self.assertIn("func source_unit_move_at_state(vel_x: float, vel_y: float, vector_x: float, vector_y: float, acceleration: float, source_delta: float) -> Dictionary:", source)
        self.assertIn("return source_unit_update_module.game_move_at_state(self, vel_x, vel_y, vector_x, vector_y, acceleration, source_delta)", source)
        self.assertIn("static func game_move_at_state(game: Object, vel_x: float, vel_y: float, vector_x: float, vector_y: float, acceleration: float, source_delta: float) -> Dictionary:", source)
        self.assertIn("return move_at_state(vel_x, vel_y, vector_x, vector_y, acceleration, source_delta, callbacks.get(SOURCE_UNIT_UPDATE_VEC2_LIMIT_KEY, Callable()))", source)
        self.assertIn("static func move_at_state(vel_x: float, vel_y: float, vector_x: float, vector_y: float, acceleration: float, source_delta: float, vec2_limit: Callable) -> Dictionary:", source)
        self.assertIn('const SOURCE_UNIT_MOVE_AT_METHOD := "public void moveAt(Vec2 vector, float acceleration){"', source)
        self.assertIn('const SOURCE_UNIT_MOVE_AT_TARGET_SET := "Vec2 t = tmp1.set(vector);"', source)
        self.assertIn('const SOURCE_UNIT_MOVE_AT_DELTA_LIMIT := "tmp2.set(t).sub(vel).limit(acceleration * vector.len() * Time.delta);"', source)
        self.assertIn('const SOURCE_UNIT_MOVE_AT_VEL_ADD := "vel.add(tmp2);"', source)
        self.assertIn("var vel := Vector2(vel_x, vel_y)", source)
        self.assertIn("var target := Vector2(vector_x, vector_y)", source)
        self.assertIn("var delta: Vector2 = vec2_limit.call(target - vel, acceleration * target.length() * source_delta)", source)
        self.assertIn("var next_vel := vel + delta", source)
        self.assertIn('"method": SOURCE_UNIT_MOVE_AT_METHOD', source)
        self.assertIn('"targetSet": SOURCE_UNIT_MOVE_AT_TARGET_SET', source)
        self.assertIn('"deltaLimit": SOURCE_UNIT_MOVE_AT_DELTA_LIMIT', source)
        self.assertIn('"velAdd": SOURCE_UNIT_MOVE_AT_VEL_ADD', source)

