        facade_source = facade.read_text(encoding="utf-8") if facade.exists() else ""
        consumer_sources = {
            "SourceUnitDestroyEffectsState.gd": effects_source,
            "SourceUnitDestroyState.gd": facade_source,
        }
        aliases = {
            "SourceUnitDestroyEffectsState.gd": (
                "SOURCE_UNIT_DESTROY_INITIAL_PAYLOAD_METHOD",
                "SOURCE_UNIT_DESTROY_EXPLOSION_DISPATCH_METHOD",
                "SOURCE_UNIT_DESTROY_VISUAL_EFFECTS_METHOD",
                "SOURCE_UNIT_DESTROY_SOUND_AND_EVENT_METHOD",
                "SOURCE_UNIT_DESTROY_SUICIDE_BOMB_TRIGGER_METHOD",
            ),
            "SourceUnitDestroyState.gd": (
                "SOURCE_UNIT_DESTROY_SHOOT_ON_DEATH_MOUNTS_METHOD",
                "SOURCE_UNIT_DESTROY_CRASH_LANDING_DAMAGE_METHOD",
                "SOURCE_UNIT_DESTROY_WRECK_DECAL_METHOD",
                "SOURCE_UNIT_DESTROY_ABILITY_DEATH_METHOD",
                "SOURCE_UNIT_DESTROY_TYPE_KILLED_REMOVE_METHOD",
            ),
        }

        self.assertTrue(owner.exists(), "SourceUnitDestroySourceTextState.gd must own shared Unit destroy source-text literals")
        self.assertIn("class_name SourceUnitDestroySourceTextState", owner_source)
        self.assertIn('const SOURCE_UNIT_DESTROY_METHOD := "public void destroy(){"', owner_source)
        for module_name, source in consumer_sources.items():
            with self.subTest(module=module_name):
                self.assertIn('const source_unit_destroy_source_text_state := preload("res://src/game/SourceUnitDestroySourceTextState.gd")', source)
                self.assertNotIn(':= "public void destroy(){"', source)
        for module_name, const_names in aliases.items():
            source = consumer_sources[module_name]
            for const_name in const_names:
                with self.subTest(module=module_name, const=const_name):
                    self.assertIn(f"const {const_name} := source_unit_destroy_source_text_state.SOURCE_UNIT_DESTROY_METHOD", source)

