        self.assertIn('"wasHealed": false', helper_source)
        self.assertIn('"resetHealTime": reset_heal_time', helper_source)
        self.assertIn('"decay": source_delta / SOURCE_UNIT_HEAL_TIME_DECAY_DIVISOR', helper_source)
        self.assertIn('"order": ["updateDrowning", "healTime gate", "healTime decay", "wasHealed reset"]', helper_source)

