        self.assertIn('"loop": SOURCE_UNIT_DESTROY_SHOOT_ON_DEATH_MOUNTS_LOOP', helper_source)
        self.assertIn('"guard": SOURCE_UNIT_DESTROY_SHOOT_ON_DEATH_MOUNTS_GUARD', helper_source)
        self.assertIn('"effectGuard": SOURCE_UNIT_DESTROY_SHOOT_ON_DEATH_MOUNTS_EFFECT_GUARD', helper_source)
        self.assertIn('"allowShootEffectsSource": SOURCE_UNIT_DESTROY_SHOOT_ON_DEATH_MOUNTS_ALLOW_EFFECTS', helper_source)
        self.assertIn('"effectCall": SOURCE_UNIT_DESTROY_SHOOT_ON_DEATH_MOUNTS_EFFECT_AT', helper_source)
        self.assertIn('"reload": SOURCE_UNIT_DESTROY_SHOOT_ON_DEATH_RELOAD_RESET', helper_source)
        self.assertNotIn('"reload": 0.0', mounts_wrapper)
        self.assertIn('"shoot": true', helper_source)
