        self.assertIn('"shootSource": SOURCE_UNIT_DESTROY_SHOOT_ON_DEATH_MOUNTS_SHOOT', helper_source)
        self.assertIn('"update": SOURCE_UNIT_DESTROY_SHOOT_ON_DEATH_MOUNTS_UPDATE', helper_source)
