    def test_bullet_heal_percent_uses_source_bullet_defaults_divisor_ssot(self):
        game = ROOT / "godot-mindustry" / "src" / "game"
        defaults_source = (game / "SourceBulletDefaults.gd").read_text(encoding="utf-8")
        hit_tile_source = (game / "SourceBulletTypeHitTileState.gd").read_text(encoding="utf-8")
        splash_source = (game / "SourceBulletTypeCreateSplashDamageState.gd").read_text(encoding="utf-8")
        runtime_source = (game / "SourceBulletRuntime.gd").read_text(encoding="utf-8")
        hit_tile_body = hit_tile_source.split("static func hit_tile_heal_state", 1)[1].split("static func ", 1)[0]
        splash_body = splash_source.split("static func heal_dispatch_state", 1)[1].split("static func ", 1)[0]
        runtime_hit_body = runtime_source.split("static func hit_tile_heal_state", 1)[1].split("static func ", 1)[0]
        runtime_splash_body = runtime_source.split("static func create_splash_damage_heal_dispatch_state", 1)[1].split("static func ", 1)[0]

        self.assertIn("const HEAL_PERCENT_DIVISOR := 100.0", defaults_source)
        for module_source in (hit_tile_source, splash_source, runtime_source):
            self.assertIn('const source_bullet_defaults := preload("res://src/game/SourceBulletDefaults.gd")', module_source)
        for body, raw_line in (
            (hit_tile_body, "var heal_applied_amount := heal_percent / 100.0 * build_max_health + heal_amount"),
            (splash_body, "var heal_applied_amount := heal_percent / 100.0 * other_max_health + heal_amount"),
        ):
            self.assertIn("source_bullet_defaults.HEAL_PERCENT_DIVISOR", body)
            self.assertNotIn(raw_line, body)
        self.assertIn("return source_bullet_type_hit_tile_state.hit_tile_heal_state", runtime_hit_body)
        self.assertIn("return source_bullet_type_create_splash_damage_state.heal_dispatch_state", runtime_splash_body)
        self.assertNotIn("heal_percent / 100.0", runtime_hit_body)
        self.assertNotIn("source_bullet_defaults.HEAL_PERCENT_DIVISOR", runtime_hit_body)
        self.assertNotIn("heal_percent / 100.0", runtime_splash_body)
        self.assertNotIn("source_bullet_defaults.HEAL_PERCENT_DIVISOR", runtime_splash_body)

