        self.assertIn('float(update_type_state.get("fragRandomSpread", source_math_defaults.FULL_CIRCLE_DEGREES))', frags_source)
        self.assertIn("const SOURCE_FULL_CIRCLE_DEGREES := source_math_defaults.FULL_CIRCLE_DEGREES", math_state_source)
        self.assertIn("tmp_v1_angle = source_math_state.source_angles_angle(0.0, 0.0, float(tmp_v1_x), float(tmp_v1_y))", units_source)
        self.assertIn("return abs(angle1 - angle2)", math_state_source)
        self.assertIn("return SOURCE_FULL_CIRCLE_DEGREES - abs(angle1 - angle2)", math_state_source)
        self.assertIn("angle_a = source_mod_float(angle_a, SOURCE_FULL_CIRCLE_DEGREES)", math_state_source)
        self.assertIn("angle_b = source_mod_float(angle_b, SOURCE_FULL_CIRCLE_DEGREES)", math_state_source)
        self.assertIn("var forward := angle_a - angle_b + SOURCE_FULL_CIRCLE_DEGREES if (angle_a - angle_b) < 0.0 else angle_a - angle_b", math_state_source)
        self.assertIn("var backward := angle_b - angle_a + SOURCE_FULL_CIRCLE_DEGREES if (angle_b - angle_a) < 0.0 else angle_b - angle_a", math_state_source)
        self.assertIn("angle = source_mod_float(angle, SOURCE_FULL_CIRCLE_DEGREES)", math_state_source)
        self.assertIn("to = source_mod_float(to, SOURCE_FULL_CIRCLE_DEGREES)", math_state_source)
        self.assertIn("angle -= speed", math_state_source)
        self.assertIn("angle += speed", math_state_source)
        self.assertIn("return angle", math_state_source)
        self.assertIn("angle += SOURCE_FULL_CIRCLE_DEGREES", self._static_method_body(math_state_source, "static func source_angles_angle(from_x: float, from_y: float, to_x: float, to_y: float) -> float:"))
        for raw_line in (
            "return 360.0 - abs(angle1 - angle2)",
            "angle_a = arc_mathf_mod_float(angle_a, 360.0)",
            "angle_b = arc_mathf_mod_float(angle_b, 360.0)",
            'float(update_type_state.get("fragRandomSpread", 360.0))',
            "tmp_v1_angle = float(tmp_v1_angle) + 360.0",
        ):
            self.assertNotIn(raw_line, runtime_source + "\n" + frags_source + "\n" + units_source + "\n" + math_state_source)

