    def test_port_game_exposes_source_weapon_shoot_default_pattern_dispatch_state(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        shoot_pattern_defaults = ROOT / "godot-mindustry" / "src" / "game" / "SourceShootPatternDefaults.gd"
        weapons_state = ROOT / "godot-mindustry" / "src" / "game" / "SourceWeaponsState.gd"
        shoot_pattern_state = ROOT / "godot-mindustry" / "src" / "game" / "SourceWeaponShootPatternState.gd"
        shoot_pattern_source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceShootPatternSourceTextState.gd"
        source = self._source_weapons_port_bridge_source()
        defaults_source = shoot_pattern_defaults.read_text(encoding="utf-8") if shoot_pattern_defaults.exists() else ""
        weapons_source = weapons_state.read_text(encoding="utf-8") if weapons_state.exists() else ""
        module_source = shoot_pattern_state.read_text(encoding="utf-8") if shoot_pattern_state.exists() else ""
        source_text_source = shoot_pattern_source_text.read_text(encoding="utf-8") if shoot_pattern_source_text.exists() else ""

        self.assertTrue(weapons_state.exists())
        self.assertTrue(shoot_pattern_state.exists())
        self.assertTrue(shoot_pattern_source_text.exists())
        self.assertIn("class_name SourceShootPatternDefaults", defaults_source)
        self.assertIn("const SHOTS_DEFAULT := 1", defaults_source)
        self.assertIn("const FIRST_SHOT_DELAY_DEFAULT := 0.0", defaults_source)
        self.assertIn("const SHOT_DELAY_DEFAULT := 0.0", defaults_source)
        self.assertIn('const source_shoot_pattern_defaults := preload("res://src/game/SourceShootPatternDefaults.gd")', module_source)
        self.assertIn('const source_shoot_pattern_source_text_state := preload("res://src/game/SourceShootPatternSourceTextState.gd")', module_source)
        self.assertIn("const SOURCE_SHOOT_PATTERN_SHOTS_DEFAULT := source_shoot_pattern_defaults.SHOTS_DEFAULT", module_source)
        self.assertIn("const SOURCE_SHOOT_PATTERN_FIRST_SHOT_DELAY_DEFAULT := source_shoot_pattern_defaults.FIRST_SHOT_DELAY_DEFAULT", module_source)
        self.assertIn("const SOURCE_SHOOT_PATTERN_SHOT_DELAY_DEFAULT := source_shoot_pattern_defaults.SHOT_DELAY_DEFAULT", module_source)
        self.assertIn("const SOURCE_SHOOT_PATTERN_SHOTS_DEFAULT := source_weapon_shoot_pattern_state.SOURCE_SHOOT_PATTERN_SHOTS_DEFAULT", weapons_source)
        self.assertIn("const SOURCE_SHOOT_PATTERN_FIRST_SHOT_DELAY_DEFAULT := source_weapon_shoot_pattern_state.SOURCE_SHOOT_PATTERN_FIRST_SHOT_DELAY_DEFAULT", weapons_source)
        self.assertIn("const SOURCE_SHOOT_PATTERN_SHOT_DELAY_DEFAULT := source_weapon_shoot_pattern_state.SOURCE_SHOOT_PATTERN_SHOT_DELAY_DEFAULT", weapons_source)
        for const_line in [
            'const SOURCE_SHOOT_PATTERN_DEFAULT_EVENTS_SHOTS_FIELD := "public int shots = 1;"',
            'const SOURCE_SHOOT_PATTERN_DEFAULT_EVENTS_FIRST_SHOT_DELAY_FIELD := "public float firstShotDelay = 0;"',
            'const SOURCE_SHOOT_PATTERN_DEFAULT_EVENTS_SHOT_DELAY_FIELD := "public float shotDelay = 0;"',
            'const SOURCE_SHOOT_PATTERN_DEFAULT_EVENTS_METHOD := "public void shoot(int totalShots, BulletHandler handler){"',
            'const SOURCE_SHOOT_PATTERN_DEFAULT_EVENTS_LOOP := "for(int i = 0; i < shots; i++){"',
            'const SOURCE_SHOOT_PATTERN_DEFAULT_EVENTS_HANDLER_CALL := "handler.shoot(0, 0, 0, firstShotDelay + shotDelay * i);"',
            'const SOURCE_SHOOT_PATTERN_DEFAULT_EVENTS_MOVER_NULL := "shoot(x, y, rotation, delay, null);"',
        ]:
            const_name = const_line.split(" := ", 1)[0].replace("const ", "")
            self.assertIn(const_line, source_text_source)
            self.assertIn(f"const {const_name} := source_shoot_pattern_source_text_state.{const_name}", module_source)
            self.assertNotIn(const_line, module_source)
            self.assertNotIn(const_line, source)
        self.assertIn("static func shoot_pattern_default_events(shoot_state: Dictionary) -> Array:", module_source)
        self.assertIn("static func shoot_default_pattern_dispatch_state(mount_state: Dictionary, shoot_state: Dictionary) -> Dictionary:", module_source)
        self.assertIn("var shots := int(shoot_state.get(\"shots\", SOURCE_SHOOT_PATTERN_SHOTS_DEFAULT))", module_source)
        self.assertIn("var first_shot_delay := float(shoot_state.get(\"firstShotDelay\", SOURCE_SHOOT_PATTERN_FIRST_SHOT_DELAY_DEFAULT))", module_source)
        self.assertIn("var shot_delay := float(shoot_state.get(\"shotDelay\", SOURCE_SHOOT_PATTERN_SHOT_DELAY_DEFAULT))", module_source)
        self.assertNotIn("shots\", 1)", module_source)
        self.assertNotIn("firstShotDelay\", 0.0", module_source)
        self.assertNotIn("shotDelay\", 0.0", module_source)
        self.assertIn("for i in shots:", module_source)
        self.assertIn('"xOffset": 0.0', module_source)
        self.assertIn('"yOffset": 0.0', module_source)
        self.assertIn('"angleOffset": 0.0', module_source)
        self.assertIn('"delay": first_shot_delay + shot_delay * float(i)', module_source)
        self.assertIn("func source_weapon_shoot_default_pattern_dispatch_state(mount_state: Dictionary, shoot_state: Dictionary) -> Dictionary:", source)
