    def test_source_weapons_callbacks_are_owned_by_callback_registry(self):
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceWeaponsState.gd"
        registry = ROOT / "godot-mindustry" / "src" / "game" / "SourceWeaponsCallbackRegistry.gd"
        helper_source = helper.read_text(encoding="utf-8") if helper.exists() else ""
        registry_source = registry.read_text(encoding="utf-8") if registry.exists() else ""

        self.assertTrue(registry.exists(), "SourceWeaponsCallbackRegistry.gd must own weapons callback key/fallback literals")
        self.assertIn("class_name SourceWeaponsCallbackRegistry", registry_source)
        self.assertIn('const source_geometry_callback_registry := preload("res://src/game/SourceGeometryCallbackRegistry.gd")', registry_source)
        self.assertIn('const source_math_callback_registry := preload("res://src/game/SourceMathCallbackRegistry.gd")', registry_source)
        self.assertIn('const source_weapons_callback_registry := preload("res://src/game/SourceWeaponsCallbackRegistry.gd")', helper_source)
        expected_callbacks = {
            "SOURCE_WEAPONS_APPROACH_DELTA": ("approach_delta", "source_mathf_approach_delta"),
            "SOURCE_WEAPONS_LERP_DELTA": ("lerp_delta", "source_mathf_lerp_delta"),
            "SOURCE_WEAPONS_TRNS_VEC": ("trns_vec", "source_arc_angles_trns_vec"),
            "SOURCE_WEAPONS_ANGLES_ANGLE": ("angles_angle", "source_arc_angles_angle"),
            "SOURCE_WEAPONS_MOVE_TOWARD_ANGLE": ("move_toward_angle", "source_arc_angles_move_toward"),
            "SOURCE_WEAPONS_ANGLE_DIST": ("angle_dist", "source_arc_angles_angle_dist"),
            "SOURCE_WEAPONS_MATHF_DST": ("mathf_dst", "source_mathf_dst"),
            "SOURCE_WEAPONS_STATUS_APPLY_RESULT": ("status_apply_result", "source_status_apply_result"),
            "SOURCE_WEAPONS_BULLET_ORIGIN_STATE": ("bullet_origin_state", "source_weapon_update_bullet_origin_state"),
        }
        for prefix, (key_value, fallback_value) in expected_callbacks.items():
            with self.subTest(prefix=prefix):
                geometry_names = {
                    "SOURCE_WEAPONS_TRNS_VEC": "TRNS_VEC",
                    "SOURCE_WEAPONS_ANGLES_ANGLE": "ANGLES_ANGLE",
                    "SOURCE_WEAPONS_MOVE_TOWARD_ANGLE": "MOVE_TOWARD_ANGLE",
                    "SOURCE_WEAPONS_ANGLE_DIST": "ANGLE_DIST",
                }
                math_names = {
                    "SOURCE_WEAPONS_APPROACH_DELTA": ("APPROACH_DELTA_KEY", "MATHF_APPROACH_DELTA_FALLBACK"),
                    "SOURCE_WEAPONS_LERP_DELTA": ("LERP_DELTA_KEY", "MATHF_LERP_DELTA_FALLBACK"),
                    "SOURCE_WEAPONS_MATHF_DST": ("MATHF_DST_KEY", "MATHF_DST_FALLBACK"),
                }
                if prefix in geometry_names:
                    geometry_name = geometry_names[prefix]
                    self.assertIn(f"const {prefix}_KEY := source_geometry_callback_registry.{geometry_name}_KEY", registry_source)
                    self.assertIn(f"const {prefix}_FALLBACK := source_geometry_callback_registry.{geometry_name}_FALLBACK", registry_source)
                elif prefix in math_names:
                    key_name, fallback_name = math_names[prefix]
                    self.assertIn(f"const {prefix}_KEY := source_math_callback_registry.{key_name}", registry_source)
                    self.assertIn(f"const {prefix}_FALLBACK := source_math_callback_registry.{fallback_name}", registry_source)
                else:
                    self.assertIn(f'const {prefix}_KEY := "{key_value}"', registry_source)
                    self.assertIn(f'const {prefix}_FALLBACK := "{fallback_value}"', registry_source)
                self.assertIn(f"const {prefix}_KEY := source_weapons_callback_registry.{prefix}_KEY", helper_source)
                self.assertIn(f"const {prefix}_FALLBACK := source_weapons_callback_registry.{prefix}_FALLBACK", helper_source)
                self.assertNotIn(f'const {prefix}_KEY := "{key_value}"', helper_source)
                self.assertNotIn(f'const {prefix}_FALLBACK := "{fallback_value}"', helper_source)

