    def test_source_ssot_catalog_runtime_hq_state_exposes_policy_self_check(self):
        catalog = ROOT / "godot-mindustry" / "src" / "generated" / "SourceSsotCatalog.gd"
        catalog_source = catalog.read_text(encoding="utf-8")
        manifest = json.loads((ROOT / "godot-mindustry" / "src" / "generated" / "source_ssot_modules.json").read_text(encoding="utf-8"))
        canonical_aliases = manifest.get("policy", {}).get("canonicalAliases", {})

        self.assertIn('var errors: Array = []', catalog_source)
        self.assertIn('"valid": errors.is_empty()', catalog_source)
        self.assertIn('"errors": errors.duplicate()', catalog_source)
        self.assertIn('"canonical_key_count": headquarters.size()', catalog_source)
        self.assertIn('"headquarter_count": seen_headquarters.size()', catalog_source)
        self.assertIn('"canonical_feature_count": features.size()', catalog_source)
        self.assertIn('"alias_count": alias_registry.size()', catalog_source)
        self.assertIn('var module_registry: Dictionary = {}', catalog_source)
        self.assertIn('module_registry[managed_module_name] = {', catalog_source)
        self.assertIn('"module_registry_count": module_registry.size()', catalog_source)
        self.assertIn('"module_registry": module_registry', catalog_source)
        self.assertIn('"duplicate_headquarters": duplicate_headquarters.duplicate(true)', catalog_source)
        self.assertIn('"duplicate_features": duplicate_features.duplicate(true)', catalog_source)
        self.assertIn('"duplicate_aliases": duplicate_aliases.duplicate(true)', catalog_source)
        self.assertIn('var aliases_for_key: Array = _canonical_policy_aliases(managed_key, feature_entry, alias_registry, policy)', catalog_source)
        self.assertIn('var canonical_headquarters := _canonical_headquarters_policy(headquarters, policy)', catalog_source)
        self.assertIn('"one_headquarter_per_ssot": seen_headquarters.size() == headquarters.size() and errors.is_empty()', catalog_source)
        self.assertIn('"managed_ssot_count": registry.size()', catalog_source)
        self.assertIn('static func _canonical_headquarter_lookup_candidates(alias_name: String) -> Array:', catalog_source)
        self.assertIn('"canonical_aliases": _canonical_policy_aliases(canonical_key, feature_entry, alias_registry, policy)', catalog_source)
        self.assertIn('static func _canonical_policy_aliases(canonical_key: String, feature_entry: Dictionary, alias_registry: Dictionary, policy: Dictionary) -> Array:', catalog_source)
        self.assertIn("registry", canonical_aliases)
        self.assertIn("source symbols", canonical_aliases["registry"])
        self.assertIn("source.symbol.registry", canonical_aliases["registry"])
        self.assertIn("content_registry.blocks", canonical_aliases)
        self.assertIn("block content registry", canonical_aliases["content_registry.blocks"])
