        self.assertIn("func source_unit_update_drowning_state(floor_exists: bool, floor_is_liquid: bool, floor_drown_time: float, can_drown_value: bool, current_drown_time: float, source_delta: float, hit_size: float, type_drown_time_multiplier: float, chance_delta_result: bool, net_client: bool) -> Dictionary:", source)
        self.assertIn("return source_unit_update_module.drowning_state(floor_exists, floor_is_liquid, floor_drown_time, can_drown_value, current_drown_time, source_delta, hit_size, type_drown_time_multiplier, chance_delta_result, net_client)", source)
        self.assertIn("static func drowning_state(floor_exists: bool, floor_is_liquid: bool, floor_drown_time: float, can_drown_value: bool, current_drown_time: float, source_delta: float, hit_size: float, type_drown_time_multiplier: float, chance_delta_result: bool, net_client: bool) -> Dictionary:", helper_source)
        self.assertIn("const DROWN_HIT_SIZE_DIVISOR := 8.0", unit_source)
        self.assertIn("const DROWN_UPDATE_EFFECT_CHANCE := 0.05", unit_source)
        self.assertIn("const DROWN_KILL_THRESHOLD := 0.999", unit_source)
        self.assertIn("const DROWN_DRY_DECAY_DIVISOR := 50.0", unit_source)
        self.assertIn("const SOURCE_UNIT_DROWN_HIT_SIZE_DIVISOR := source_unit_defaults.DROWN_HIT_SIZE_DIVISOR", helper_source)
        self.assertIn("const SOURCE_UNIT_DROWN_UPDATE_EFFECT_CHANCE := source_unit_defaults.DROWN_UPDATE_EFFECT_CHANCE", helper_source)
        self.assertIn("const SOURCE_UNIT_DROWN_KILL_THRESHOLD := source_unit_defaults.DROWN_KILL_THRESHOLD", helper_source)
        self.assertIn("const SOURCE_UNIT_DROWN_DRY_DECAY_DIVISOR := source_unit_defaults.DROWN_DRY_DECAY_DIVISOR", helper_source)
        self.assertIn("var can_drown_on_floor := floor_exists and floor_is_liquid and floor_drown_time > 0.0 and can_drown_value", helper_source)
        self.assertIn("var drown_time_before_clamp := current_drown_time", helper_source)
        self.assertIn("var drown_increment := 0.0", helper_source)
        self.assertIn("drown_increment = source_delta / (hit_size / SOURCE_UNIT_DROWN_HIT_SIZE_DIVISOR * type_drown_time_multiplier * floor_drown_time)", helper_source)
        self.assertIn("drown_time_before_clamp += drown_increment", helper_source)
        self.assertIn("effect_call = {", helper_source)
        self.assertIn('"call": "floor.drownUpdateEffect.at(x, y, hitSize, floor.mapColor)"', helper_source)
        self.assertIn('"chanceValue": SOURCE_UNIT_DROWN_UPDATE_EFFECT_CHANCE', helper_source)
        self.assertIn("kill_unit = drown_time_before_clamp >= SOURCE_UNIT_DROWN_KILL_THRESHOLD and not net_client", helper_source)
        self.assertIn('"event": "Events.fire(new UnitDrownEvent(self()))"', helper_source)
        self.assertIn("drown_time_before_clamp -= source_delta / SOURCE_UNIT_DROWN_DRY_DECAY_DIVISOR", helper_source)
        self.assertIn("var clamped_drown_time: float = clampf(drown_time_before_clamp, 0.0, 1.0)", helper_source)

