        self.assertNotIn("const SOURCE_TILESIZE := 8.0", port_source)
        self.assertNotIn("const SOURCE_UNIT_WARP_DST := 8.0", port_source)
        self.assertNotIn("const SOURCE_FINAL_WORLD_BOUNDS := 250.0", port_source)
        self.assertIn("func source_unit_update_bounds_state(type_bounded: bool, world_unit_height: float, world_unit_width: float, rules_limit_map_area: bool, team_is_ai: bool, rules_limit_x: int, rules_limit_y: int, rules_limit_width: int, rules_limit_height: int, current_x: float, current_y: float, elevation_value: float, net_client: bool, is_local: bool, source_delta: float) -> Dictionary:", source)
        self.assertIn("return source_unit_update_module.bounds_state(type_bounded, world_unit_height, world_unit_width, rules_limit_map_area, team_is_ai, rules_limit_x, rules_limit_y, rules_limit_width, rules_limit_height, current_x, current_y, elevation_value, net_client, is_local, source_delta)", source)
        self.assertIn("static func bounds_state(type_bounded: bool, world_unit_height: float, world_unit_width: float, rules_limit_map_area: bool, team_is_ai: bool, rules_limit_x: int, rules_limit_y: int, rules_limit_width: int, rules_limit_height: int, current_x: float, current_y: float, elevation_value: float, net_client: bool, is_local: bool, source_delta: float) -> Dictionary:", helper_source)
        self.assertIn("if not type_bounded:", helper_source)
        self.assertIn("var use_limited_area := rules_limit_map_area and not team_is_ai", helper_source)
        self.assertIn("bot = float(rules_limit_y) * source_world_defaults.TILESIZE", helper_source)
        self.assertIn("left = float(rules_limit_x) * source_world_defaults.TILESIZE", helper_source)
        self.assertIn("top = float(rules_limit_height) * source_world_defaults.TILESIZE + bot", helper_source)
        self.assertIn("right = float(rules_limit_width) * source_world_defaults.TILESIZE + left", helper_source)
        self.assertIn("if (not net_client) or is_local:", helper_source)
        self.assertIn("dx += (-(next_x - left) / SOURCE_UNIT_WARP_DST)", helper_source)
        self.assertIn("dy += (-(next_y - bot) / SOURCE_UNIT_WARP_DST)", helper_source)
        self.assertIn("dx -= (next_x - (right - source_world_defaults.TILESIZE)) / SOURCE_UNIT_WARP_DST", helper_source)
        self.assertIn("dy -= (next_y - (top - source_world_defaults.TILESIZE)) / SOURCE_UNIT_WARP_DST", helper_source)
        self.assertIn("vel_add_net = {\"x\": dx * source_delta, \"y\": dy * source_delta}", helper_source)
        self.assertIn("var margin := source_world_defaults.TILESIZE * 1.0", helper_source)
        self.assertIn("next_x = clampf(next_x, left - margin, right - source_world_defaults.TILESIZE + margin)", helper_source)
        self.assertIn("next_y = clampf(next_y, bot - margin, top - source_world_defaults.TILESIZE + margin)", helper_source)
        self.assertIn("if grounded:", helper_source)
        self.assertIn("next_x = clampf(next_x, left, right - source_world_defaults.TILESIZE)", helper_source)
        self.assertIn("next_y = clampf(next_y, bot, top - source_world_defaults.TILESIZE)", helper_source)
        self.assertIn("var kill_unit := next_x < -SOURCE_FINAL_WORLD_BOUNDS + left or next_y < -SOURCE_FINAL_WORLD_BOUNDS + bot or next_x >= right + SOURCE_FINAL_WORLD_BOUNDS or next_y >= top + SOURCE_FINAL_WORLD_BOUNDS", helper_source)

