        self.assertIn("input_runtime.set_virtual_input_axes(touch_x, touch_y, roblox_x, roblox_y)", source)
        self.assertIn("set_touch_move_axis(Vector2(touch_x, touch_y))", runtime_source)
        self.assertIn("set_roblox_move_axis(Vector2(roblox_x, roblox_y))", runtime_source)
        self.assertIn("func set_touch_move_axis(axis: Vector2) -> void:", source)
        self.assertIn("func set_roblox_move_axis(axis: Vector2) -> void:", source)
        self.assertIn("touch_move_axis = source_input_defaults.normalize_virtual_axis(axis)", runtime_source)
        self.assertIn("roblox_move_axis = source_input_defaults.normalize_virtual_axis(axis)", runtime_source)
