        self.assertIn("game.call(\"set_touch_move_axis\", source_input_defaults.touch_axis_from_drag(event.relative))", input_event_source)
        self.assertIn("elif event is InputEventScreenTouch and not event.pressed:", input_event_source)
        self.assertIn("game.call(\"set_touch_move_axis\", Vector2.ZERO)", input_event_source)
