    def test_port_game_routes_power_generator_through_port_bridge(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourcePowerGeneratorPortBridge.gd"
        power_bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingPowerPortBridge.gd"

        self.assertTrue(bridge.exists(), "Power generator compatibility wrappers must live in SourcePowerGeneratorPortBridge.gd")
        self.assertTrue(power_bridge.exists(), "SourceBuildingPowerPortBridge.gd must own the building power wrappers")
        port_source = port_game.read_text(encoding="utf-8")
        bridge_source = bridge.read_text(encoding="utf-8")
        power_bridge_source = power_bridge.read_text(encoding="utf-8")
        chain_source = self._port_game_port_bridge_chain_source()
        actual_chain = self._actual_port_game_port_bridge_chain()

        self.assertIn('extends "res://src/game/SourcePortGameFacadePortBridge.gd"', port_source)
        self.assertIn('extends "res://src/game/SourceInputViewportPortBridge.gd"', chain_source)
        self.assertIn('extends "res://src/game/SourcePowerNodePortBridge.gd"', chain_source)
        self.assertIn(
            'extends "res://src/game/SourcePowerGeneratorPortBridge.gd"',
            (ROOT / "godot-mindustry" / "src" / "game" / "SourcePowerNodePortBridge.gd").read_text(encoding="utf-8"),
        )
        self.assertIn("SourcePowerGeneratorPortBridge.gd", actual_chain)
        self.assertIn('const source_power_generator_state := preload("res://src/game/SourcePowerGeneratorState.gd")', chain_source)
        self.assertIn('extends "res://src/game/SourceBuildingPowerPortBridge.gd"', bridge_source)
        self.assertIn('extends "res://src/game/SourceBuildingSetPropPortBridge.gd"', power_bridge_source)
        self.assertIn('extends "res://src/game/SourceBuildingCorePortBridge.gd"', (ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildingSetPropPortBridge.gd").read_text(encoding="utf-8"))
        self.assertIn('const source_building_power_state := preload("res://src/game/SourceBuildingPowerState.gd")', power_bridge_source)
        self.assertIn('const source_power_generator_state := preload("res://src/game/SourcePowerGeneratorState.gd")', bridge_source)
        self.assertIn('const source_building_power_state := preload("res://src/game/SourceBuildingPowerState.gd")', chain_source)
        self.assertNotIn('const source_power_generator_state := preload("res://src/game/SourcePowerGeneratorState.gd")', port_source)
        self.assertNotIn("class_name SourcePowerGeneratorPortBridge", bridge_source)

