        self.assertIn("source_drill_production_runtime_state_script.SOURCE_DRILL_PRODUCTION_ITEM_PROGRESS_KEY", self._port_game_drill_runtime_source())
        self.assertIn('"production_item_progress": source_drill_production_runtime_state_script.SOURCE_DRILL_PRODUCTION_ITEM_PROGRESS_KEY', self._port_game_drill_runtime_source())
