    def test_port_game_uses_source_conveyor_speed_for_item_motion(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourcePlayableWorldRuntimePortBridge.gd"
        metadata_helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockMetadataState.gd"
        factory_defaults = ROOT / "godot-mindustry" / "src" / "game" / "SourceFactoryDefaults.gd"
        conveyor_runtime = ROOT / "godot-mindustry" / "src" / "game" / "SourceConveyorRuntimeState.gd"
        conveyor_source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceConveyorSourceTextState.gd"
        factory_runtime = ROOT / "godot-mindustry" / "src" / "game" / "SourceFactoryRuntimeState.gd"
        factory_simulation_runtime = ROOT / "godot-mindustry" / "src" / "game" / "SourceFactorySimulationRuntimeState.gd"
        source = port_game.read_text(encoding="utf-8") + "\n" + self._port_game_port_bridge_chain_source()
        helper_source = metadata_helper.read_text(encoding="utf-8")
        factory_source = factory_defaults.read_text(encoding="utf-8") if factory_defaults.exists() else ""
        conveyor_source = conveyor_runtime.read_text(encoding="utf-8") if conveyor_runtime.exists() else ""
        conveyor_source_text_source = conveyor_source_text.read_text(encoding="utf-8") if conveyor_source_text.exists() else ""
        factory_runtime_source = factory_runtime.read_text(encoding="utf-8") if factory_runtime.exists() else ""
        factory_simulation_source = factory_simulation_runtime.read_text(encoding="utf-8") if factory_simulation_runtime.exists() else ""
        initial_build_source = (ROOT / "godot-mindustry" / "src" / "game" / "SourceWorldInitialBuildRuntimeState.gd").read_text(encoding="utf-8")

        self.assertIn("const CONVEYOR_TILE_SPEED_SCALE := 55.0", factory_source)
        self.assertTrue(conveyor_runtime.exists())
        self.assertIn("class_name SourceConveyorRuntimeState", conveyor_source)
        self.assertIn('const source_block_metadata_state := preload("res://src/game/SourceBlockMetadataState.gd")', conveyor_source)
        self.assertIn('const source_factory_defaults := preload("res://src/game/SourceFactoryDefaults.gd")', conveyor_source)
        self.assertIn('const source_conveyor_source_text_state := preload("res://src/game/SourceConveyorSourceTextState.gd")', conveyor_source)
        self.assertIn('const source_texture_runtime_state := preload("res://src/game/SourceTextureRuntimeState.gd")', conveyor_source)
        self.assertIn('const SOURCE_CONVEYOR_WORLD_SPEED_SOURCE := "core/src/mindustry/world/blocks/distribution/Conveyor.java"', conveyor_source_text_source)
        self.assertIn("const SOURCE_CONVEYOR_WORLD_SPEED_SOURCE := source_conveyor_source_text_state.SOURCE_CONVEYOR_WORLD_SPEED_SOURCE", conveyor_source)
        self.assertIn("const SOURCE_CONVEYOR_TILE_SPEED_SCALE := source_factory_defaults.CONVEYOR_TILE_SPEED_SCALE", conveyor_source)
        self.assertNotIn("const SOURCE_CONVEYOR_TILE_SPEED_SCALE := source_factory_defaults.CONVEYOR_TILE_SPEED_SCALE", source)
        self.assertIn("var transport_progress := 0.0", source)
        self.assertIn("var conveyor_world_speed := 0.0", source)
        self.assertIn("var conveyor_path_progress_rate := 0.0", source)
        self.assertIn('game.set(PROP_CONVEYOR_WORLD_SPEED, float(game.call(METHOD_SOURCE_CONVEYOR_WORLD_SPEED, source_playable_scenario_defaults.BLOCK_CONVEYOR)))', initial_build_source)
        self.assertIn('game.set(PROP_CONVEYOR_PATH_PROGRESS_RATE, float(game.call(METHOD_SOURCE_CONVEYOR_PATH_PROGRESS_RATE, source_playable_scenario_defaults.BLOCK_CONVEYOR)))', initial_build_source)
        self.assertIn('source_factory_simulation_runtime_state_script.SOURCE_FACTORY_SIMULATION_CONVEYOR_PROGRESS_DELTA_FOR_CELL_KEY: Callable(game, conveyor_progress_delta_method)', factory_runtime_source)
