    def test_source_conveyor_runtime_state_source_text_is_owned_by_source_text_state(self):
        runtime = ROOT / "godot-mindustry" / "src" / "game" / "SourceConveyorRuntimeState.gd"
        source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceConveyorSourceTextState.gd"
        runtime_source = runtime.read_text(encoding="utf-8") if runtime.exists() else ""
        source_text_source = source_text.read_text(encoding="utf-8") if source_text.exists() else ""
        constants = {
            "SOURCE_CONVEYOR_WORLD_SPEED_SOURCE": "core/src/mindustry/world/blocks/distribution/Conveyor.java",
            "SOURCE_CONVEYOR_WORLD_SPEED_SPEED_FIELD": "public float speed = 0f;",
            "SOURCE_CONVEYOR_WORLD_SPEED_UNIT_WORLD_SPEED": "float mspeed = speed * tilesize * 55f;",
            "SOURCE_CONVEYOR_WORLD_SPEED_UNIT_IMPULSE": "unit.impulse((tx * mspeed + centerx) * delta(), (ty * mspeed + centery) * delta());",
            "SOURCE_CONVEYOR_WORLD_SPEED_TILESIZE_COMMENT": "/** size of tiles in units */",
            "SOURCE_CONVEYOR_WORLD_SPEED_KEY": "speed",
            "SOURCE_CONVEYOR_PATH_PROGRESS_RATE_SPEED_FIELD": "public float speed = 0f;",
            "SOURCE_CONVEYOR_PATH_PROGRESS_RATE_UNIT_WORLD_SPEED": "float mspeed = speed * tilesize * 55f;",
            "SOURCE_CONVEYOR_PATH_PROGRESS_RATE_ITEM_POSITIONS": "public float[] xs = new float[capacity], ys = new float[capacity];",
            "SOURCE_CONVEYOR_PATH_PROGRESS_RATE_MOVED": "float moved = speed * edelta();",
            "SOURCE_CONVEYOR_PATH_PROGRESS_RATE_YS_ADD": "ys[i] += maxmove;",
            "SOURCE_CONVEYOR_PATH_PROGRESS_RATE_PASS_THRESHOLD": "if(ys[i] >= 1f && pass(ids[i])){",
            "SOURCE_CONVEYOR_PATH_PROGRESS_DELTA_SPEED_FIELD": "public float speed = 0f;",
            "SOURCE_CONVEYOR_PATH_PROGRESS_DELTA_MOVED": "float moved = speed * edelta();",
            "SOURCE_CONVEYOR_PATH_PROGRESS_DELTA_MAXMOVE": "float maxmove = Mathf.clamp(nextpos - ys[i], 0, moved);",
            "SOURCE_CONVEYOR_PATH_PROGRESS_DELTA_YS_ADD": "ys[i] += maxmove;",
            "SOURCE_CONVEYOR_PATH_PROGRESS_DELTA_EDELTA_METHOD": "public float edelta(){",
            "SOURCE_CONVEYOR_PATH_PROGRESS_DELTA_EDELTA_RETURN": "return efficiency * delta();",
            "SOURCE_CONVEYOR_PATH_PROGRESS_DELTA_FOR_CELL_TILE_FIELD": "transient Tile tile;",
            "SOURCE_CONVEYOR_PATH_PROGRESS_DELTA_FOR_CELL_BLOCK_FIELD": "transient Block block;",
            "SOURCE_CONVEYOR_PATH_PROGRESS_DELTA_FOR_CELL_TILE_X": "return tile.x;",
            "SOURCE_CONVEYOR_PATH_PROGRESS_DELTA_FOR_CELL_TILE_Y": "return tile.y;",
            "SOURCE_CONVEYOR_PATH_PROGRESS_DELTA_FOR_CELL_TIME_SCALE_FIELD": "private transient float timeScale = 1f, timeScaleDuration;",
            "SOURCE_CONVEYOR_PATH_PROGRESS_DELTA_FOR_CELL_TIME_SCALE_METHOD": "public float timeScale(){",
            "SOURCE_CONVEYOR_PATH_PROGRESS_DELTA_FOR_CELL_TIME_SCALE_RETURN": "return timeScale;",
            "SOURCE_CONVEYOR_EDELTA_PROVIDER_KEY": "edelta_provider",
            "SOURCE_CONVEYOR_EDELTA_PROVIDER_FALLBACK": "source_building_edelta",
        }

        self.assertTrue(source_text.exists(), "SourceConveyorSourceTextState.gd must own conveyor runtime literals")
        self.assertIn("class_name SourceConveyorSourceTextState", source_text_source)
        world_source_text = (ROOT / "godot-mindustry" / "src" / "game" / "SourceWorldSourceTextState.gd").read_text(encoding="utf-8")
        self.assertIn('const SOURCE_TILESIZE_FIELD := "public static final int tilesize = 8;"', world_source_text)
        self.assertIn('const source_world_source_text_state := preload("res://src/game/SourceWorldSourceTextState.gd")', source_text_source)
        self.assertIn('const SOURCE_CONVEYOR_WORLD_SPEED_TILESIZE_FIELD := source_world_source_text_state.SOURCE_TILESIZE_FIELD', source_text_source)
        self.assertIn('const SOURCE_CONVEYOR_WORLD_SPEED_TILESIZE_FIELD := source_conveyor_source_text_state.SOURCE_CONVEYOR_WORLD_SPEED_TILESIZE_FIELD', runtime_source)
        self.assertIn('const source_conveyor_source_text_state := preload("res://src/game/SourceConveyorSourceTextState.gd")', runtime_source)
        for const_name, literal_value in constants.items():
            self.assertIn(f'const {const_name} := "{literal_value}"', source_text_source, f"{const_name} must be owned by SourceConveyorSourceTextState")
            self.assertIn(f"const {const_name} := source_conveyor_source_text_state.{const_name}", runtime_source, f"{const_name} must alias SourceConveyorSourceTextState")
            self.assertNotIn(f'const {const_name} := "{literal_value}"', runtime_source, f"{const_name} must not duplicate its literal in SourceConveyorRuntimeState")

