    def test_source_block_remaining_generated_bridges_use_block_source_text_state(self):
        cases = {
            "SourceBlockCheckContentArrayCapacityState.gd": "var result = _block_call(SOURCE_BLOCK_CHECK_CONTENT_ARRAY_CAPACITY_JAVA_METHOD_CHECK_CONTENT_ARRAY_CAPACITY_125, [item_filter, liquid_filter, items, liquids])",
            "SourceBlockInitBufferedPowerState.gd": "var result = _block_call(SOURCE_BLOCK_INIT_BUFFERED_POWER_JAVA_METHOD_INIT_123, [outputs_power, has_cons_power, cons_power_buffered_before], {SOURCE_BLOCK_INIT_BUFFERED_POWER_BRIDGE_MODE_KEY: SOURCE_BLOCK_INIT_BUFFERED_POWER_BUFFERED_POWER_MODE})",
            "SourceBlockInitBuildingDefaultState.gd": "var result = _block_call(SOURCE_BLOCK_INIT_BUILDING_DEFAULT_JAVA_METHOD_INIT_BUILDING_117, [build_type_before])",
            "SourceBlockInitItemLiquidFiltersState.gd": "var result = _block_call(SOURCE_BLOCK_INIT_ITEM_LIQUID_FILTERS_JAVA_METHOD_INIT_123, [content_items_size, content_liquids_size], {SOURCE_BLOCK_INIT_ITEM_LIQUID_FILTERS_BRIDGE_MODE_KEY: SOURCE_BLOCK_INIT_ITEM_LIQUID_FILTERS_ITEM_LIQUID_FILTERS_MODE})",
            "SourceBlockInitLogicConfigurableState.gd": "var result = _block_call(SOURCE_BLOCK_INIT_LOGIC_CONFIGURABLE_JAVA_METHOD_INIT_123, [logic_configurable_before, config_key_assignable_to_unlockable_content], {SOURCE_BLOCK_INIT_LOGIC_CONFIGURABLE_BRIDGE_MODE_KEY: SOURCE_BLOCK_INIT_LOGIC_CONFIGURABLE_LOGIC_CONFIGURABLE_MODE})",
            "SourceBlockInitSandboxVisibilityState.gd": "var result = _block_call(SOURCE_BLOCK_INIT_SANDBOX_VISIBILITY_JAVA_METHOD_INIT_123, [build_visibility, hide_details_before], {SOURCE_BLOCK_INIT_SANDBOX_VISIBILITY_BRIDGE_MODE_KEY: SOURCE_BLOCK_INIT_SANDBOX_VISIBILITY_SANDBOX_VISIBILITY_MODE})",
            "SourceBlockInitSetBarsCallState.gd": "var result = _block_call(SOURCE_BLOCK_INIT_SET_BARS_CALL_JAVA_METHOD_INIT_123, [], {SOURCE_BLOCK_INIT_SET_BARS_CALL_BRIDGE_MODE_KEY: SOURCE_BLOCK_INIT_SET_BARS_CALL_SET_BARS_CALL_MODE})",
            "SourceBlockInitStatsCategoriesState.gd": "var result = _block_call(SOURCE_BLOCK_INIT_STATS_CATEGORIES_JAVA_METHOD_INIT_123, [stats_use_categories_before], {SOURCE_BLOCK_INIT_STATS_CATEGORIES_BRIDGE_MODE_KEY: SOURCE_BLOCK_INIT_STATS_CATEGORIES_STATS_CATEGORIES_MODE})",
            "SourceBlockQueryState.gd": "var result = _block_call(SOURCE_BLOCK_QUERY_OUTPUTS_ITEMS_JAVA_METHOD_OUTPUTS_ITEMS_17, [has_items])",
        }

        for filename, helper_call in cases.items():
            with self.subTest(module=filename):
                module = ROOT / "godot-mindustry" / "src" / "game" / filename
                module_source = module.read_text(encoding="utf-8")
                self.assertIn('const source_block_source_text_state := preload("res://src/game/SourceBlockSourceTextState.gd")', module_source)
                self.assertIn("const SOURCE_BLOCK_GENERATED_CLASS := source_block_source_text_state.SOURCE_BLOCK_GENERATED_CLASS", module_source)
                self.assertIn("static func _block_call(generated_method: String, generated_args: Array, metadata: Variant = null) -> Variant:", module_source)
                self.assertIn("source_generated_class_runtime.call_java_method(SOURCE_BLOCK_GENERATED_CLASS, generated_method, generated_args, null)", module_source)
                self.assertIn(helper_call, module_source)
                self.assertNotIn('call_java_method("res://src/generated/classes/mindustry/world/Block.gd"', module_source)

