    def test_source_sync_source_text_state_owns_generated_bridge_literals(self):
        source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceSyncSourceTextState.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceSyncState.gd"
        source_text_source = source_text.read_text(encoding="utf-8") if source_text.exists() else ""
        module_source = module.read_text(encoding="utf-8") if module.exists() else ""

        self.assertTrue(source_text.exists(), "SourceSyncSourceTextState.gd must own SyncComp generated bridge source literals")
        self.assertIn("class_name SourceSyncSourceTextState", source_text_source)
        self.assertIn('const source_sync_source_text_state := preload("res://src/game/SourceSyncSourceTextState.gd")', module_source)

        for const_name, literal_value in {
            "SOURCE_SYNC_EMPTY_BODY_KEY": "empty_body",
            "SOURCE_SYNC_NO_OP_KEY": "no_op",
            "SOURCE_SYNC_CALL_KEY": "call",
            "SOURCE_SYNC_METHOD_KEY": "method",
            "SOURCE_SYNC_SOURCE_OWNER_KEY": "source_owner",
            "SOURCE_SYNC_PLAYER_KEY": "player",
            "SOURCE_SYNC_RETURN_EXPR_KEY": "return_expr",
            "SOURCE_SYNC_IS_SYNC_HIDDEN_KEY": "is_sync_hidden",
            "SOURCE_SYNC_CONDITION_KEY": "condition",
            "SOURCE_SYNC_INTERPOLATE_CALL_KEY": "interpolate_call",
            "SOURCE_SYNC_NET_CLIENT_KEY": "net_client",
            "SOURCE_SYNC_IS_LOCAL_KEY": "is_local",
            "SOURCE_SYNC_IS_REMOTE_KEY": "is_remote",
            "SOURCE_SYNC_INTERPOLATE_CALLED_KEY": "interpolate_called",
            "SOURCE_SYNC_INTERPOLATE_KEY": "interpolate",
            "SOURCE_SYNC_ADD_REMOVED_ENTITY_CALL_KEY": "add_removed_entity_call",
            "SOURCE_SYNC_ID_CALL_KEY": "id_call",
            "SOURCE_SYNC_ENTITY_ID_KEY": "entity_id",
            "SOURCE_SYNC_RESULT_KEY": "result",
            "SOURCE_SYNC_CANONICAL_KEY": "canonical",
            "SOURCE_SYNC_GENERATED_OWNER_KEY": "generated_owner",
            "SOURCE_SYNC_MATCHES_KEY": "matches",
        }.items():
            with self.subTest(key=const_name):
                self.assertIn(f'const {const_name} := "{literal_value}"', source_text_source)
                self.assertIn(f"const {const_name} := source_sync_source_text_state.{const_name}", module_source)

        for generated_method, (method_const, owner_const) in self._sync_generated_bridge_consts().items():
            generated_owner = "sync_comp." + generated_method
            with self.subTest(generated_method=generated_method):
                self.assertIn(f'const {method_const} := "{generated_method}"', source_text_source)
                self.assertIn(f'const {owner_const} := "{generated_owner}"', source_text_source)
                self.assertIn(f"const {method_const} := source_sync_source_text_state.{method_const}", module_source)
                self.assertIn(f"const {owner_const} := source_sync_source_text_state.{owner_const}", module_source)
                self.assertNotIn(f'_sync_comp_call("{generated_method}"', module_source)
                self.assertNotIn(f'"generated_owner": "{generated_owner}"', module_source)

