    def test_source_builder_runtime_state_source_text_owns_literals(self):
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuilderRuntimeState.gd"
        source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuilderRuntimeSourceTextState.gd"
        module_source = module.read_text(encoding="utf-8")
        source_text_source = source_text.read_text(encoding="utf-8") if source_text.exists() else ""

        self.assertTrue(source_text.exists(), "SourceBuilderRuntimeSourceTextState.gd must own BuilderComp runtime source literals")
        self.assertIn("class_name SourceBuilderRuntimeSourceTextState", source_text_source)
        self.assertIn('const source_builder_runtime_source_text_state := preload("res://src/game/SourceBuilderRuntimeSourceTextState.gd")', module_source)
        for const_name, literal_value in {
            "SOURCE_BUILDER_RUNTIME_SOURCE": "core/src/mindustry/entities/comp/BuilderComp.java",
            "SOURCE_BUILDER_CAN_BUILD_METHOD": "public boolean canBuild(){",
            "SOURCE_BUILDER_CAN_BUILD_RETURN_EXPR": "return type.buildSpeed > 0 && buildSpeedMultiplier > 0;",
            "SOURCE_BUILDER_UPDATE_METHOD": "public void update(){",
            "SOURCE_BUILDER_UPDATE_BUILD_LOGIC_CALL_EXPR": "updateBuildLogic();",
            "SOURCE_BUILDER_AFTER_READ_METHOD": "public void afterRead(){",
            "SOURCE_BUILDER_AFTER_READ_COMMENT": "//why would this happen?",
            "SOURCE_BUILDER_AFTER_READ_GUARD_EXPR": "if(plans == null){",
            "SOURCE_BUILDER_AFTER_READ_QUEUE_CONSTRUCTOR": "new Queue<>(1)",
            "SOURCE_BUILDER_IS_BUILDING_METHOD": "boolean isBuilding(){",
            "SOURCE_BUILDER_IS_BUILDING_RETURN_EXPR": "return plans.size != 0;",
            "SOURCE_BUILDER_CLEAR_BUILDING_METHOD": "void clearBuilding(){",
            "SOURCE_BUILDER_CLEAR_BUILDING_PLANS_CLEAR_CALL_EXPR": "plans.clear();",
            "SOURCE_BUILDER_ADD_BUILD_TAIL_METHOD": "void addBuild(BuildPlan place){",
            "SOURCE_BUILDER_ADD_BUILD_TAIL_CALL_EXPR": "addBuild(place, true);",
            "SOURCE_BUILDER_SHOULD_SKIP_METHOD": "boolean shouldSkip(BuildPlan plan, @Nullable Building core){",
            "SOURCE_BUILDER_SHOULD_SKIP_GUARD_EXPR": "if(state.rules.infiniteResources || team.rules().infiniteResources || plan.breaking || core == null || plan.isRotation(team) || plan.isDerelictRepair()) return false;",
            "SOURCE_BUILDER_SHOULD_SKIP_RETURN_EXPR": "return (plan.stuck && !core.items.has(plan.block.requirements)) || (Structs.contains(plan.block.requirements, i -> !core.items.has(i.item, Math.min(i.amount, 15)) && Mathf.round(i.amount * state.rules.buildCostMultiplier) > 0));",
            "SOURCE_BUILDER_REMOVE_BUILD_METHOD": "void removeBuild(int x, int y, boolean breaking){",
            "SOURCE_BUILDER_REMOVE_BUILD_INDEX_EXPR": "int idx = plans.indexOf(req -> req.breaking == breaking && req.x == x && req.y == y);",
            "SOURCE_BUILDER_REMOVE_BUILD_GUARD_EXPR": "if(idx != -1){",
            "SOURCE_BUILDER_REMOVE_BUILD_REMOVE_INDEX_EXPR": "plans.removeIndex(idx);",
            "SOURCE_BUILDER_ADD_BUILD_METHOD": "void addBuild(BuildPlan place, boolean tail){",
            "SOURCE_BUILDER_ADD_BUILD_WORLD_TILE_CALL_EXPR": "world.tile(place.x, place.y);",
            "SOURCE_BUILDER_ADD_BUILD_ADD_LAST_EXPR": "plans.addLast(place);",
            "SOURCE_BUILDER_ADD_BUILD_ADD_FIRST_EXPR": "plans.addFirst(place);",
            "SOURCE_BUILDER_BUILD_PLAN_METHOD": "BuildPlan buildPlan(){",
            "SOURCE_BUILDER_BUILD_PLAN_RETURN_EXPR": "return plans.size == 0 ? null : plans.first();",
            "SOURCE_BUILDER_ACTIVELY_BUILDING_METHOD": "boolean activelyBuilding(){",
            "SOURCE_BUILDER_ACTIVELY_BUILDING_RANGE_EXPR": "state.rules.infiniteResources ? Float.MAX_VALUE : type.buildRange",
            "SOURCE_BUILDER_BUILD_STEP_METHOD": "void updateBuildLogic(){",
            "SOURCE_BUILDER_BUILD_STEP_SPEED_FORMULA_EXPR": "1f / entity.buildCost * type.buildSpeed * buildSpeedMultiplier * state.rules.buildSpeed(team)",
            "SOURCE_BUILDER_BUILD_STEP_CONSTRUCT_CALL_EXPR": "entity.construct(self(), core, bs, current.config);",
            "SOURCE_BUILDER_BUILD_STEP_DECONSTRUCT_CALL_EXPR": "entity.deconstruct(self(), core, bs);",
        }.items():
            literal_token = literal_value.replace("\\", "\\\\").replace('"', '\\"')
            self.assertIn(f'const {const_name} := "{literal_token}"', source_text_source)
            self.assertIn(f"const {const_name} := source_builder_runtime_source_text_state.{const_name}", module_source)
            self.assertNotIn(f'const {const_name} := "{literal_token}"', module_source)

