    def test_source_turret_source_text_state_owns_turret_init_generated_classes(self):
        owner = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretSourceTextState.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretInitState.gd"
        owner_source = owner.read_text(encoding="utf-8") if owner.exists() else ""
        module_source = module.read_text(encoding="utf-8")

        self.assertTrue(owner.exists(), "SourceTurretSourceTextState.gd must own turret generated class paths")
        self.assertIn('const SOURCE_TURRET_GENERATED_CLASS := "res://src/generated/classes/mindustry/world/blocks/defense/turrets/Turret.gd"', owner_source)
        self.assertIn('const SOURCE_BASE_TURRET_GENERATED_CLASS := "res://src/generated/classes/mindustry/world/blocks/defense/turrets/BaseTurret.gd"', owner_source)
        self.assertIn('const SOURCE_TURRET_SHOOT_Y_INIT_DEFAULT := "if(shootY == Float.NEGATIVE_INFINITY) shootY = size * tilesize / 2f;"', owner_source)
        for const_name, literal_value in {
            "SOURCE_TURRET_INIT_JAVA_METHOD": "java_method_init_3",
            "SOURCE_TURRET_INIT_GENERATED_OWNER": "turret.java_method_init_3",
            "SOURCE_BASE_TURRET_INIT_JAVA_METHOD": "java_method_init_0",
            "SOURCE_BASE_TURRET_INIT_GENERATED_OWNER": "base_turret.java_method_init_0",
            "SOURCE_BASE_TURRET_REINITIALIZE_CONSUMERS_JAVA_METHOD": "java_method_reinitializeConsumers_1",
            "SOURCE_BASE_TURRET_REINITIALIZE_CONSUMERS_GENERATED_OWNER": "base_turret.java_method_reinitializeConsumers_1",
            "SOURCE_BASE_TURRET_CHECK_INIT_COOLANT_JAVA_METHOD": "java_method_checkInitCoolant_2",
            "SOURCE_BASE_TURRET_CHECK_INIT_COOLANT_GENERATED_OWNER": "base_turret.java_method_checkInitCoolant_2",
        }.items():
            self.assertIn(f'const {const_name} := "{literal_value}"', owner_source)
            self.assertIn(f"const {const_name} := source_turret_source_text_state.{const_name}", module_source)
        self.assertIn('const source_turret_source_text_state := preload("res://src/game/SourceTurretSourceTextState.gd")', module_source)
        self.assertIn("const SOURCE_TURRET_GENERATED_CLASS := source_turret_source_text_state.SOURCE_TURRET_GENERATED_CLASS", module_source)
        self.assertIn("const SOURCE_BASE_TURRET_GENERATED_CLASS := source_turret_source_text_state.SOURCE_BASE_TURRET_GENERATED_CLASS", module_source)
        self.assertIn("const SOURCE_TURRET_SHOOT_Y_INIT_DEFAULT := source_turret_source_text_state.SOURCE_TURRET_SHOOT_Y_INIT_DEFAULT", module_source)
        self.assertIn('"shoot_y_guard_expr": SOURCE_TURRET_SHOOT_Y_INIT_DEFAULT', module_source)
        self.assertNotIn('"shoot_y_guard_expr": "if(shootY == Float.NEGATIVE_INFINITY) shootY = size * tilesize / 2f;"', module_source)
        self.assertIn("static func _turret_init_call(generated_method: String, generated_args: Array) -> Variant:", module_source)
        self.assertIn("static func _base_turret_call(generated_method: String, generated_args: Array) -> Variant:", module_source)
        self.assertIn("source_generated_class_runtime.call_java_method(SOURCE_TURRET_GENERATED_CLASS, generated_method, generated_args, null)", module_source)
        self.assertIn("source_generated_class_runtime.call_java_method(SOURCE_BASE_TURRET_GENERATED_CLASS, generated_method, generated_args, null)", module_source)
        self.assertIn("var result = _turret_init_call(SOURCE_TURRET_INIT_JAVA_METHOD, [shoot_y, shoot_y_is_negative_infinity, size, source_tilesize, elevation, recoil_time, reload, cooldown_time, new_target_interval, target_interval, target_ground, disable_overlap_check, range_value, tracking_range])", module_source)
        self.assertIn("var result = _base_turret_call(SOURCE_BASE_TURRET_INIT_JAVA_METHOD, [coolant_present, found_consume_coolant, disable_overlap_check, place_overlap_range, range_value, place_overlap_margin, source_tilesize, fog_radius_multiplier, fog_radius])", module_source)
        self.assertIn('"generated_owner": SOURCE_TURRET_INIT_GENERATED_OWNER', module_source)
        self.assertIn('"generated_owner": SOURCE_BASE_TURRET_INIT_GENERATED_OWNER', module_source)
        self.assertIn('"generated_owner": SOURCE_BASE_TURRET_REINITIALIZE_CONSUMERS_GENERATED_OWNER', module_source)
        self.assertIn('"generated_owner": SOURCE_BASE_TURRET_CHECK_INIT_COOLANT_GENERATED_OWNER', module_source)
        self.assertNotIn('var result = _turret_init_call("java_method_init_3"', module_source)
        self.assertNotIn('var result = _base_turret_call("java_method_init_0"', module_source)
        self.assertNotIn('"generated_owner": "turret.java_method_init_3"', module_source)
        self.assertNotIn('"generated_owner": "base_turret.java_method_init_0"', module_source)
        self.assertNotIn('"generated_owner": "base_turret.java_method_reinitializeConsumers_1"', module_source)
        self.assertNotIn('"generated_owner": "base_turret.java_method_checkInitCoolant_2"', module_source)
        self.assertNotIn('call_java_method("res://src/generated/classes/mindustry/world/blocks/defense/turrets/Turret.gd"', module_source)
        self.assertNotIn('call_java_method("res://src/generated/classes/mindustry/world/blocks/defense/turrets/BaseTurret.gd"', module_source)

    def test_port_game_exposes_source_base_turret_init_state(self):
        source = self._port_game_turret_init_source()

        self.assertIn("func source_base_turret_init_state(coolant_present: bool, found_consume_coolant: bool, disable_overlap_check: bool, place_overlap_range: float, range_value: float, place_overlap_margin: float, source_tilesize: float, fog_radius_multiplier: float, fog_radius: int) -> Dictionary:", source)
        self.assertIn('"source_owner": source_runtime_owner_registry.PORT_GAME_SOURCE_BASE_TURRET_INIT_STATE', source)
        self.assertIn('"method": "public void init(){"', source)
        self.assertIn('"coolant_null_guard_expr": "if(coolant == null){"', source)
        self.assertIn('"find_consumer_expr": "coolant = findConsumer(c -> c instanceof ConsumeCoolant);"', source)
        self.assertIn('"check_init_coolant_expr": "checkInitCoolant();"', source)
        self.assertIn('"overlap_guard_expr": "if(!disableOverlapCheck){"', source)
        self.assertIn('"place_overlap_range_expr": "placeOverlapRange = Math.max(placeOverlapRange, range + placeOverlapMargin);"', source)
        self.assertIn('"fog_radius_expr": "fogRadius = Math.max(Mathf.round(range / tilesize * fogRadiusMultiplier), fogRadius);"', source)
