        generated_source = generated.read_text(encoding="utf-8")
        self._assert_runtime_bridge_moved_to_module(
            source,
            module_source,
            "func generated_base_turret_init_bridge_state(coolant_present: bool, found_consume_coolant: bool, disable_overlap_check: bool, place_overlap_range: float, range_value: float, place_overlap_margin: float, source_tilesize: float, fog_radius_multiplier: float, fog_radius: int) -> Dictionary:",
            "static func generated_base_turret_init_bridge_state(coolant_present: bool, found_consume_coolant: bool, disable_overlap_check: bool, place_overlap_range: float, range_value: float, place_overlap_margin: float, source_tilesize: float, fog_radius_multiplier: float, fog_radius: int) -> Dictionary:",
            "return source_turret_init_state_script.generated_base_turret_init_bridge_state(coolant_present, found_consume_coolant, disable_overlap_check, place_overlap_range, range_value, place_overlap_margin, source_tilesize, fog_radius_multiplier, fog_radius)",
            "res://src/generated/classes/mindustry/world/blocks/defense/turrets/BaseTurret.gd",
            "java_method_init_0",
            "coolant_present, found_consume_coolant, disable_overlap_check, place_overlap_range, range_value, place_overlap_margin, source_tilesize, fog_radius_multiplier, fog_radius",
            "var canonical = base_turret_init_state(coolant_present, found_consume_coolant, disable_overlap_check, place_overlap_range, range_value, place_overlap_margin, source_tilesize, fog_radius_multiplier, fog_radius)",
            "port_game.source_base_turret_init_state",
            "base_turret.java_method_init_0",
        )
        self._assert_generated_bridge_uses_runtime(
            module_source,
            self._method_body(module_source, "static func generated_base_turret_init_bridge_state(coolant_present: bool, found_consume_coolant: bool, disable_overlap_check: bool, place_overlap_range: float, range_value: float, place_overlap_margin: float, source_tilesize: float, fog_radius_multiplier: float, fog_radius: int) -> Dictionary:"),
            "res://src/generated/classes/mindustry/world/blocks/defense/turrets/BaseTurret.gd",
            "java_method_init_0",
            "coolant_present, found_consume_coolant, disable_overlap_check, place_overlap_range, range_value, place_overlap_margin, source_tilesize, fog_radius_multiplier, fog_radius",
        )
        self.assertIn("var canonical = base_turret_init_state(coolant_present, found_consume_coolant, disable_overlap_check, place_overlap_range, range_value, place_overlap_margin, source_tilesize, fog_radius_multiplier, fog_radius)", module_source)
        self.assertIn('"source_owner": source_runtime_owner_registry.PORT_GAME_SOURCE_BASE_TURRET_INIT_STATE', module_source)
        self.assertIn('"generated_owner": SOURCE_BASE_TURRET_INIT_GENERATED_OWNER', module_source)
        self.assertIn('"matches": result.get("coolant_present_after", null) == canonical.get("coolant_present_after", null) and result.get("place_overlap_range_after", null) == canonical.get("place_overlap_range_after", null) and result.get("fog_radius_after", null) == canonical.get("fog_radius_after", null)', module_source)
        self.assertIn('const source_time_defaults := preload("res://src/game/SourceTimeDefaults.gd")', generated_source)
        self.assertIn("const SOURCE_TILESIZE := source_world_defaults.TILESIZE", generated_source)
        self.assertIn('const source_turret_defaults := preload("res://src/game/SourceTurretDefaults.gd")', generated_source)
        self.assertIn("const SOURCE_TURRET_RANGE_DEFAULT := source_turret_defaults.RANGE_DEFAULT", generated_source)
        self.assertIn("const SOURCE_TURRET_PLACE_OVERLAP_MARGIN_DEFAULT := source_turret_defaults.PLACE_OVERLAP_MARGIN_DEFAULT", generated_source)
        self.assertIn("const SOURCE_TURRET_FOG_RADIUS_MULTIPLIER_DEFAULT := source_turret_defaults.FOG_RADIUS_MULTIPLIER_DEFAULT", generated_source)
        self.assertIn("const SOURCE_TURRET_DISABLE_OVERLAP_CHECK_DEFAULT := source_turret_defaults.DISABLE_OVERLAP_CHECK_DEFAULT", generated_source)
        self.assertIn("var disable_overlap_check: bool = bool(_args[2] if _args.size() > 2 else SOURCE_TURRET_DISABLE_OVERLAP_CHECK_DEFAULT)", generated_source)
        self.assertNotIn("var disable_overlap_check: bool = bool(_args[2] if _args.size() > 2 else false)", generated_source)
        self.assertIn("var range_value: float = float(_args[4] if _args.size() > 4 else SOURCE_TURRET_RANGE_DEFAULT)", generated_source)
        self.assertNotIn("var range_value: float = float(_args[4] if _args.size() > 4 else 80.0)", generated_source)
        self.assertIn("var place_overlap_margin: float = float(_args[5] if _args.size() > 5 else SOURCE_TURRET_PLACE_OVERLAP_MARGIN_DEFAULT)", generated_source)
        self.assertNotIn("var place_overlap_margin: float = float(_args[5] if _args.size() > 5 else 56.0)", generated_source)
        self.assertIn("var fog_radius_multiplier: float = float(_args[7] if _args.size() > 7 else SOURCE_TURRET_FOG_RADIUS_MULTIPLIER_DEFAULT)", generated_source)
        self.assertNotIn("var fog_radius_multiplier: float = float(_args[7] if _args.size() > 7 else 1.0)", generated_source)
        self.assertIn("var source_tilesize: float = float(_args[6] if _args.size() > 6 else SOURCE_TILESIZE)", generated_source)
        self.assertNotIn("var source_tilesize: float = float(_args[6] if _args.size() > 6 else 8.0)", generated_source)

