    def test_port_game_routes_base_turret_draw_through_port_bridge(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourceBaseTurretDrawPortBridge.gd"
        item_turret_bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourceItemTurretBuildPortBridge.gd"
        port_source = port_game.read_text(encoding="utf-8")
        bridge_source = bridge.read_text(encoding="utf-8") if bridge.exists() else ""
        item_turret_source = item_turret_bridge.read_text(encoding="utf-8") if item_turret_bridge.exists() else ""

        self.assertTrue(bridge.exists(), "SourceBaseTurretDrawPortBridge.gd must own BaseTurret draw-place PortGame compatibility wrappers")
        self.assertIn("SourceBaseTurretDrawPortBridge.gd", self._actual_port_game_port_bridge_chain())
        self.assertIn('extends "res://src/game/SourceBaseTurretDrawPortBridge.gd"', item_turret_source)
        self.assertIn('extends "res://src/game/SourceComponentPortBridge.gd"', bridge_source)
        self.assertNotIn("class_name SourceBaseTurretDrawPortBridge", bridge_source)
        self.assertIn('const source_base_turret_draw_state := preload("res://src/game/SourceBaseTurretDrawState.gd")', bridge_source)
        self.assertNotIn('const source_base_turret_draw_state := preload("res://src/game/SourceBaseTurretDrawState.gd")', port_source)

        expected_delegates = {
            "func source_base_turret_draw_place_state(tile_x: int, tile_y: int, rotation_value: int, valid: bool, source_tilesize: float, block_offset: float, range_value: float, fog_radius_multiplier: float, rules_fog: bool) -> Dictionary:": "return source_base_turret_draw_state.draw_place_state(tile_x, tile_y, rotation_value, valid, source_tilesize, block_offset, range_value, fog_radius_multiplier, rules_fog)",
            "func generated_base_turret_draw_place_bridge_state(tile_x: int, tile_y: int, rotation_value: int, valid: bool, source_tilesize: float, block_offset: float, range_value: float, fog_radius_multiplier: float, rules_fog: bool) -> Dictionary:": "return source_base_turret_draw_state.generated_base_turret_draw_place_bridge_state(tile_x, tile_y, rotation_value, valid, source_tilesize, block_offset, range_value, fog_radius_multiplier, rules_fog)",
            "func generated_base_turret_draw_place_source_tilesize_default_bridge_state(tile_x: int, tile_y: int, rotation_value: int, valid: bool) -> Dictionary:": "return source_base_turret_draw_state.generated_base_turret_draw_place_source_tilesize_default_bridge_state(tile_x, tile_y, rotation_value, valid)",
        }
        for signature, delegate in expected_delegates.items():
            with self.subTest(signature=signature):
                self.assertNotIn(signature, port_source)
                method_body = self._method_body(bridge_source, signature)
                self.assertIn(delegate, method_body)

