    def test_source_tractor_beam_callback_literals_have_single_registry_owner(self):
        registry = ROOT / "godot-mindustry" / "src" / "game" / "SourceTractorBeamCallbackRegistry.gd"
        module_names = [
            "SourceTractorBeamTurretBuildUpdateTileActiveStrengthState.gd",
            "SourceTractorBeamTurretBuildUpdateTileInactiveStrengthState.gd",
            "SourceTractorBeamTurretBuildUpdateTileAngleToTargetState.gd",
            "SourceTractorBeamTurretBuildUpdateTileRotationMoveState.gd",
            "SourceTractorBeamTurretBuildUpdateTileShootWhenPossibleGuardState.gd",
        ]
        registry_source = registry.read_text(encoding="utf-8")
        direct_callbacks = {
            "SOURCE_TRACTOR_BEAM_STRENGTH_LERP_DELTA_KEY": "lerp_delta",
            "SOURCE_TRACTOR_BEAM_STRENGTH_LERP_DELTA_FALLBACK": "source_mathf_lerp_delta",
            "SOURCE_TRACTOR_BEAM_ANGLE_TO_TARGET_KEY": "angle_to_target",
            "SOURCE_TRACTOR_BEAM_ANGLE_TO_TARGET_FALLBACK": "source_angle_to_target",
        }
        geometry_callbacks = {
            "SOURCE_TRACTOR_BEAM_ROTATION_MOVE_TOWARD_ANGLE_KEY": "move_toward_angle",
            "SOURCE_TRACTOR_BEAM_ROTATION_MOVE_TOWARD_ANGLE_FALLBACK": "source_arc_angles_move_toward",
            "SOURCE_TRACTOR_BEAM_SHOOT_GUARD_ANGLE_DIST_KEY": "angle_dist",
            "SOURCE_TRACTOR_BEAM_SHOOT_GUARD_ANGLE_DIST_FALLBACK": "source_angles_angle_dist",
        }

        self.assertIn("class_name SourceTractorBeamCallbackRegistry", registry_source)
        self.assertIn('const source_geometry_callback_registry := preload("res://src/game/SourceGeometryCallbackRegistry.gd")', registry_source)
        self.assertIn('const source_math_callback_registry := preload("res://src/game/SourceMathCallbackRegistry.gd")', registry_source)
        for const_name, literal in direct_callbacks.items():
            with self.subTest(callback=const_name):
                if const_name == "SOURCE_TRACTOR_BEAM_STRENGTH_LERP_DELTA_KEY":
                    self.assertIn(f"const {const_name} := source_math_callback_registry.LERP_DELTA_KEY", registry_source)
                elif const_name == "SOURCE_TRACTOR_BEAM_STRENGTH_LERP_DELTA_FALLBACK":
                    self.assertIn(f"const {const_name} := source_math_callback_registry.MATHF_LERP_DELTA_FALLBACK", registry_source)
                else:
                    self.assertIn(f'const {const_name} := "{literal}"', registry_source)
        for const_name, literal in geometry_callbacks.items():
            with self.subTest(callback=const_name):
                geometry_name = "MOVE_TOWARD_ANGLE" if "ROTATION_MOVE" in const_name else "ANGLE_DIST"
                suffix = "KEY" if const_name.endswith("_KEY") else "FALLBACK"
                self.assertIn(f"const {const_name} := source_geometry_callback_registry.{geometry_name}_{suffix}", registry_source)
        for module_name in module_names:
            module_source = (ROOT / "godot-mindustry" / "src" / "game" / module_name).read_text(encoding="utf-8")
            with self.subTest(module=module_name):
                self.assertIn('const source_tractor_beam_callback_registry := preload("res://src/game/SourceTractorBeamCallbackRegistry.gd")', module_source)
                for const_name, literal in {**direct_callbacks, **geometry_callbacks}.items():
                    if const_name in module_source:
                        self.assertNotIn(f'const {const_name} := "{literal}"', module_source)
                        self.assertIn(f"const {const_name} := source_tractor_beam_callback_registry.{const_name}", module_source)

