    def test_source_turret_source_text_state_owns_placement_expressions(self):
        source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretSourceTextState.gd"
        placement_state = ROOT / "godot-mindustry" / "src" / "game" / "SourceTurretPlacementState.gd"
        source_text_source = source_text.read_text(encoding="utf-8")
        placement_source = placement_state.read_text(encoding="utf-8")

        constants = {
            "SOURCE_TURRET_OVERRIDE_EXPR": "@Override",
            "SOURCE_TURRET_DRAW_PLACE_METHOD": "public void drawPlace(int x, int y, int rotation, boolean valid){",
            "SOURCE_TURRET_DRAW_PLACE_JAVA_METHOD": "java_method_drawPlace_9",
            "SOURCE_TURRET_DRAW_PLACE_GENERATED_OWNER": "turret.java_method_drawPlace_9",
            "SOURCE_TURRET_DRAW_PLACE_SUPER_EXPR": "super.drawPlace(x, y, rotation, valid);",
            "SOURCE_TURRET_DRAW_PLACE_MIN_RANGE_GATE": "if(drawMinRange){",
            "SOURCE_TURRET_DRAW_PLACE_DASH_CIRCLE_EXPR": "Drawf.dashCircle(x * tilesize + offset, y * tilesize + offset, minRange, Pal.placing);",
            "SOURCE_TURRET_ROTATED_OUTPUT_METHOD": "public boolean rotatedOutput(int x, int y){",
            "SOURCE_TURRET_ROTATED_OUTPUT_JAVA_METHOD": "java_method_rotatedOutput_10",
            "SOURCE_TURRET_ROTATED_OUTPUT_GENERATED_OWNER": "turret.java_method_rotatedOutput_10",
            "SOURCE_TURRET_ROTATED_OUTPUT_RETURN_EXPR": "return false;",
            "SOURCE_TURRET_PLACE_ENDED_METHOD": "public void placeEnded(Tile tile, @Nullable Unit builder, int rotation, @Nullable Object config){",
            "SOURCE_TURRET_PLACE_ENDED_JAVA_METHOD": "java_method_placeEnded_11",
            "SOURCE_TURRET_PLACE_ENDED_GENERATED_OWNER": "turret.java_method_placeEnded_11",
            "SOURCE_TURRET_PLACE_ENDED_SUPER_EXPR": "super.placeEnded(tile, builder, rotation, config);",
            "SOURCE_TURRET_PLACE_ENDED_GATE_EXPR": "if(rotate && tile.build instanceof TurretBuild turret){",
            "SOURCE_TURRET_PLACE_ENDED_ROTATION_ASSIGN_EXPR": "turret.rotation = tile.build.rotdeg();",
        }
        for const_name, value in constants.items():
            self.assertIn(f'const {const_name} := "{value}"', source_text_source)
            self.assertIn(f"const {const_name} := source_turret_source_text_state.{const_name}", placement_source)
        for raw in constants.values():
            self.assertNotIn(f'": "{raw}"', placement_source)

