        self.assertNotIn('"dispatch_expr": "limitRange(shootType, margin);"', range_source)
        self.assertNotIn('"dispatch_expr": "limitRange(9f);"', range_source)
        self.assertNotIn('"loop_expr": "for(var entry : ammoTypes.entries()){"', range_source)
        self.assertNotIn('"dispatch_expr": "limitRange(entry.value, margin);"', range_source)

