    def test_port_game_generated_block_query_bridges_are_owned_by_module(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockQueryState.gd"
        source = self._port_game_block_query_source()
        module_source = module.read_text(encoding="utf-8")

        self.assertTrue(module.exists(), "source_block_query_state.gd must own Block query bridge state")
        self.assertIn('const source_block_query_state := preload("res://src/game/SourceBlockQueryState.gd")', source)

        cases = [
            (
                "func generated_block_outputs_items_bridge_state(has_items: bool) -> Dictionary:",
                "func generated_block_outputs_items_bridge_state(has_items: bool) -> Dictionary:",
                "return source_block_query_state.generated_block_outputs_items_bridge_state(has_items)",
                'var script = ResourceLoader.load("res://src/generated/classes/mindustry/world/Block.gd")',
                "var result = instance.java_method_outputsItems_17([has_items])",
                "var canonical = outputs_items_state(has_items)",
                "source_runtime_owner_registry.PORT_GAME_SOURCE_BLOCK_OUTPUTS_ITEMS_STATE",
                "block.java_method_outputsItems_17",
                "var matches: bool = source_generated_class_runtime.generated_state_matches_canonical_subset(result, canonical)",
            ),
        ]

        for port_signature, module_signature, facade_call, script_load, generated_call, canonical_call, source_owner, generated_owner, matches_expr in cases:
            with self.subTest(signature=port_signature):
                bridge_body = self._method_body(source, port_signature)
                module_body = self._static_method_body(module_source, module_signature)
                generated_method = generated_call.split("instance.", 1)[1].split("(", 1)[0]
                generated_args = generated_call.split("(", 1)[1].rsplit(")", 1)[0]
                self.assertIn(module_signature, module_source)
                self.assertIn(facade_call, bridge_body)
                self.assertNotIn(script_load, bridge_body)
                self.assertNotIn("source_generated_class_runtime.call_java_method", bridge_body)
                self.assertIn('const source_generated_class_runtime := preload("res://src/game/SourceGeneratedClassRuntime.gd")', module_source)
                self.assertIn(
                    "var result = _block_call(SOURCE_BLOCK_QUERY_OUTPUTS_ITEMS_JAVA_METHOD_OUTPUTS_ITEMS_17, [has_items])",
                    module_body,
                )
                self.assertIn('const source_block_source_text_state := preload("res://src/game/SourceBlockSourceTextState.gd")', module_source)
                self.assertIn("const SOURCE_BLOCK_GENERATED_CLASS := source_block_source_text_state.SOURCE_BLOCK_GENERATED_CLASS", module_source)
                self.assertIn(canonical_call, module_body)
                if source_owner.startswith("source_runtime_owner_registry."):
                    self.assertIn(f'"source_owner": {source_owner}', module_body)
                else:
                    self.assertIn(f'"source_owner": "{source_owner}"', module_body)
                self.assertIn('"generated_owner": SOURCE_BLOCK_QUERY_OUTPUTS_ITEMS_GENERATED_OWNER', module_body)
                self.assertNotIn('var result = _block_call("java_method_outputsItems_17", [has_items])', module_body)
                self.assertNotIn('"generated_owner": "block.java_method_outputsItems_17"', module_body)
                self.assertIn(matches_expr, module_body)
                self.assertNotIn("ResourceLoader.load(", module_body)
                self.assertNotIn("script.new()", module_body)

