    def test_runtime_proofs_use_ssot_accessor_headquarter(self):
        proof_dir = ROOT / "godot-mindustry" / "tools" / "runtime_proofs"
        proof_sources = []
        for proof_path in sorted(proof_dir.glob("*.gd")):
            if proof_path.name == "RuntimeProofState.gd":
                continue
            proof_sources.append((proof_path.name, proof_path.read_text(encoding="utf-8")))

        direct_catalog_proofs = [
            proof_name
            for proof_name, proof_source in proof_sources
            if 'preload("res://src/generated/SourceSsotCatalog.gd")' in proof_source
        ]

        self.assertFalse(
            direct_catalog_proofs,
            "runtime proofs must use SourceSsotAccessorRuntimeState instead of preloading SourceSsotCatalog directly: %s" % ", ".join(direct_catalog_proofs),
        )

