        self.assertTrue(module.exists(), "source_block_consume_state.gd must own Block consume source state")
        module_source = module.read_text(encoding="utf-8")
        self.assertIn('const source_block_consume_state := preload("res://src/game/SourceBlockConsumeState.gd")', source)

        delegations = {
            "func source_block_consume_liquid_state(liquid: Variant, amount: float) -> Dictionary:": "\treturn source_block_consume_state.consume_liquid_state(liquid, amount)",
            "func source_block_consume_liquids_state(stacks: Variant) -> Dictionary:": "\treturn source_block_consume_state.consume_liquids_state(stacks)",
            "func source_block_consume_power_state(power_per_tick: float) -> Dictionary:": "\treturn source_block_consume_state.consume_power_state(power_per_tick)",
            "func source_block_consume_power_cond_state(usage: float, cons: Variant) -> Dictionary:": "\treturn source_block_consume_state.consume_power_cond_state(usage, cons)",
            "func source_block_consume_power_dynamic_state(usage: Variant) -> Dictionary:": "\treturn source_block_consume_state.consume_power_dynamic_state(usage)",
            "func source_block_consume_power_dynamic_displayed_state(displayed: float, usage: Variant) -> Dictionary:": "\treturn source_block_consume_state.consume_power_dynamic_displayed_state(displayed, usage)",
            "func source_block_consume_power_buffered_state(power_capacity: float) -> Dictionary:": "\treturn source_block_consume_state.consume_power_buffered_state(power_capacity)",
            "func source_block_consume_item_single_state(item: Variant) -> Dictionary:": "\treturn source_block_consume_state.consume_item_single_state(item)",
            "func source_block_consume_item_amount_state(item: Variant, amount: int) -> Dictionary:": "\treturn source_block_consume_state.consume_item_amount_state(item, amount)",
            "func source_block_consume_items_varargs_state(items: Array) -> Dictionary:": "\treturn source_block_consume_state.consume_items_varargs_state(items)",
            "func source_block_consume_coolant_single_state(amount: float) -> Dictionary:": "\treturn source_block_consume_state.consume_coolant_single_state(amount)",
            "func source_block_consume_coolant_filtered_state(amount: float, allow_liquid: bool, allow_gas: bool) -> Dictionary:": "\treturn source_block_consume_state.consume_coolant_filtered_state(amount, allow_liquid, allow_gas)",
            "func source_block_consume_generic_state(consume: Variant, consume_is_power: bool, consume_builder_before: Array, consume_builder_without_power: Array, cons_power_before: Variant) -> Dictionary:": "\treturn source_block_consume_state.consume_generic_state(consume, consume_is_power, consume_builder_before, consume_builder_without_power, cons_power_before)",
        }
        for signature, delegation in delegations.items():
            method_body = self._method_body(source, signature)
            self.assertIn(delegation, method_body)
            self.assertNotIn('"source": "core/src/mindustry/world/Block.java"', method_body)

