            self.assertNotIn('call_java_method("res://src/generated/classes/mindustry/world/Block.gd"', module_source)
            self.assertIn(canonical_call, module_body)
            self.assertIn(f'SOURCE_BLOCK_CONSUME_GENERATED_OWNER_KEY: {generated_owner_const}', module_body)
            self.assertIn(f"const {generated_method_const} := source_block_consume_source_text_state.{generated_method_const}", module_source)
            self.assertIn(f"const {generated_owner_const} := source_block_consume_source_text_state.{generated_owner_const}", module_source)
            self.assertIn(f'const {generated_method_const} := "{generated_method_literal}"', source_text_source)
            self.assertIn(f'const {generated_owner_const} := "{generated_owner_literal}"', source_text_source)
            self.assertNotIn(f'_block_call("{generated_method_literal}"', module_source)
            self.assertNotIn(f'SOURCE_BLOCK_CONSUME_GENERATED_OWNER_KEY: "{generated_owner_literal}"', module_source)
            self.assertNotIn("ResourceLoader.load(", module_body)
            self.assertNotIn("script.new()", module_body)

