    def test_port_game_delegates_block_requirements_source_state_to_module(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockRequirementsPortBridge.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockRequirementsState.gd"
        source = port_game.read_text(encoding="utf-8")
        bridge_source = bridge.read_text(encoding="utf-8") if bridge.exists() else ""

        self.assertTrue(module.exists(), "source_block_requirements_state.gd must own Block setupRequirements/requirements source state")
        module_source = module.read_text(encoding="utf-8")
        self.assertIn('const source_block_requirements_state := preload("res://src/game/SourceBlockRequirementsState.gd")', bridge_source)
        self.assertNotIn('const source_block_requirements_state := preload("res://src/game/SourceBlockRequirementsState.gd")', source)
        self.assertIn('const source_block_source_text_state := preload("res://src/game/SourceBlockSourceTextState.gd")', module_source)
        self.assertIn("const SOURCE_BLOCK_GENERATED_CLASS := source_block_source_text_state.SOURCE_BLOCK_GENERATED_CLASS", module_source)
        self.assertIn("static func _block_call(generated_method: String, generated_args: Array, metadata: Variant = null) -> Variant:", module_source)
        self.assertIn("source_generated_class_runtime.call_java_method(SOURCE_BLOCK_GENERATED_CLASS, generated_method, generated_args, null, metadata)", module_source)
        self.assertNotIn('call_java_method("res://src/generated/classes/mindustry/world/Block.gd"', module_source)

        delegations = {
            "func source_block_setup_requirements_simple_state(cat: Variant, stacks: Variant) -> Dictionary:": "\treturn source_block_requirements_state.setup_requirements_simple_state(cat, stacks)",
            "func source_block_setup_requirements_visible_state(cat: Variant, build_visibility: Variant, stacks: Variant) -> Dictionary:": "\treturn source_block_requirements_state.setup_requirements_visible_state(cat, build_visibility, stacks)",
            "func source_block_requirements_unlocked_state(cat: Variant, stacks: Variant, unlocked: bool) -> Dictionary:": "\treturn source_block_requirements_state.requirements_unlocked_state(cat, stacks, unlocked)",
            "func source_block_requirements_simple_state(cat: Variant, stacks: Variant) -> Dictionary:": "\treturn source_block_requirements_state.requirements_simple_state(cat, stacks)",
            "func source_block_requirements_visible_state(cat: Variant, build_visibility: Variant, stacks: Variant) -> Dictionary:": "\treturn source_block_requirements_state.requirements_visible_state(cat, build_visibility, stacks)",
        }
        for signature, delegation in delegations.items():
            method_body = self._method_body(bridge_source, signature)
            self.assertIn(delegation, method_body)
            self.assertNotIn('"source": "core/src/mindustry/world/Block.java"', method_body)

        for method_name in (
            "setup_requirements_simple_state",
            "setup_requirements_visible_state",
            "requirements_unlocked_state",
            "requirements_simple_state",
            "requirements_visible_state",
        ):
            self.assertIn("static func " + method_name, module_source)

        for source_owner in (
            "source_runtime_owner_registry.PORT_GAME_SOURCE_BLOCK_SETUP_REQUIREMENTS_SIMPLE_STATE",
            "source_runtime_owner_registry.PORT_GAME_SOURCE_BLOCK_SETUP_REQUIREMENTS_VISIBLE_STATE",
            "source_runtime_owner_registry.PORT_GAME_SOURCE_BLOCK_REQUIREMENTS_UNLOCKED_STATE",
            "source_runtime_owner_registry.PORT_GAME_SOURCE_BLOCK_REQUIREMENTS_SIMPLE_STATE",
            "source_runtime_owner_registry.PORT_GAME_SOURCE_BLOCK_REQUIREMENTS_VISIBLE_STATE",
        ):
            self.assertIn('"source_owner": ' + source_owner, module_source)

    def test_port_game_delegates_block_requirements_generated_bridge_state_to_module(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockRequirementsState.gd"
        source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockRequirementsSourceTextState.gd"
        port_source = port_game.read_text(encoding="utf-8")
        module_source = module.read_text(encoding="utf-8")
        source_text_source = source_text.read_text(encoding="utf-8")

        bridges = {
            "generated_block_setup_requirements_simple_bridge_state(cat: Variant, stacks: Variant)": ("cat, stacks", "SOURCE_BLOCK_REQUIREMENTS_SETUP_SIMPLE_JAVA_METHOD", "[cat, stacks]", "var canonical = setup_requirements_simple_state(cat, stacks)", "SOURCE_BLOCK_REQUIREMENTS_SETUP_SIMPLE_GENERATED_OWNER", "java_method_setupRequirements_112", "block.java_method_setupRequirements_112"),
            "generated_block_setup_requirements_visible_bridge_state(cat: Variant, build_visibility: Variant, stacks: Variant)": ("cat, build_visibility, stacks", "SOURCE_BLOCK_REQUIREMENTS_SETUP_VISIBLE_JAVA_METHOD", "[cat, build_visibility, stacks]", "var canonical = setup_requirements_visible_state(cat, build_visibility, stacks)", "SOURCE_BLOCK_REQUIREMENTS_SETUP_VISIBLE_GENERATED_OWNER", "java_method_setupRequirements_113", "block.java_method_setupRequirements_113"),
            "generated_block_requirements_unlocked_bridge_state(cat: Variant, stacks: Variant, unlocked: bool)": ("cat, stacks, unlocked", "SOURCE_BLOCK_REQUIREMENTS_REQUIREMENTS_UNLOCKED_JAVA_METHOD", "[cat, stacks, unlocked]", "var canonical = requirements_unlocked_state(cat, stacks, unlocked)", "SOURCE_BLOCK_REQUIREMENTS_REQUIREMENTS_UNLOCKED_GENERATED_OWNER", "java_method_requirements_114", "block.java_method_requirements_114"),
            "generated_block_requirements_simple_bridge_state(cat: Variant, stacks: Variant)": ("cat, stacks", "SOURCE_BLOCK_REQUIREMENTS_REQUIREMENTS_SIMPLE_JAVA_METHOD", "[cat, stacks]", "var canonical = requirements_simple_state(cat, stacks)", "SOURCE_BLOCK_REQUIREMENTS_REQUIREMENTS_SIMPLE_GENERATED_OWNER", "java_method_requirements_115", "block.java_method_requirements_115"),
            "generated_block_requirements_visible_bridge_state(cat: Variant, build_visibility: Variant, stacks: Variant)": ("cat, build_visibility, stacks", "SOURCE_BLOCK_REQUIREMENTS_REQUIREMENTS_VISIBLE_JAVA_METHOD", "[cat, build_visibility, stacks]", "var canonical = requirements_visible_state(cat, build_visibility, stacks)", "SOURCE_BLOCK_REQUIREMENTS_REQUIREMENTS_VISIBLE_GENERATED_OWNER", "java_method_requirements_116", "block.java_method_requirements_116"),
        }
        for signature_tail, (args, generated_method_const, generated_args, canonical_call, generated_owner_const, generated_method_literal, generated_owner_literal) in bridges.items():
            func_name = signature_tail.split("(", 1)[0]
            port_signature = f"func {signature_tail} -> Dictionary:"
            module_signature = f"static func {signature_tail} -> Dictionary:"
            port_body = self._method_body(port_source, port_signature)
            module_body = self._static_method_body(module_source, module_signature)
            self.assertIn(module_signature, module_source)
            self.assertIn(f"\treturn source_block_requirements_state.{func_name}({args})", port_body)
            self.assertNotIn("ResourceLoader.load(", port_body)
            self.assertNotIn("java_method_", port_body)
            self.assertIn('const source_generated_class_runtime := preload("res://src/game/SourceGeneratedClassRuntime.gd")', module_source)
            self.assertIn(f"const {generated_method_const} := source_block_requirements_source_text_state.{generated_method_const}", module_source)
            self.assertIn(f"const {generated_owner_const} := source_block_requirements_source_text_state.{generated_owner_const}", module_source)
            self.assertIn(f'const {generated_method_const} := "{generated_method_literal}"', source_text_source)
            self.assertIn(f'const {generated_owner_const} := "{generated_owner_literal}"', source_text_source)
            self.assertIn(f"var result = _block_call({generated_method_const}, {generated_args})", module_body)
            self.assertIn(canonical_call, module_body)
            self.assertIn(f'"generated_owner": {generated_owner_const}', module_body)
            self.assertNotIn(f'_block_call("{generated_method_literal}"', module_body)
            self.assertNotIn(f'"generated_owner": "{generated_owner_literal}"', module_body)
            self.assertIn("var matches: bool = source_generated_class_runtime.generated_state_matches_canonical_subset(result, canonical)", module_body)
            self.assertNotIn('static func generated_state_matches_generated_subset(result: Variant, canonical: Variant) -> bool:', module_source)
            self.assertNotIn("ResourceLoader.load(", module_body)
            self.assertNotIn("script.new()", module_body)

