    def test_port_game_delegates_block_research_requirements_source_state_to_module(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockResearchRequirementsPortBridge.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockResearchRequirementsState.gd"
        source = port_game.read_text(encoding="utf-8")
        bridge_source = bridge.read_text(encoding="utf-8") if bridge.exists() else ""

        self.assertTrue(module.exists(), "source_block_research_requirements_state.gd must own Block researchRequirements source state")
        module_source = module.read_text(encoding="utf-8")
        self.assertIn('const source_block_research_requirements_state := preload("res://src/game/SourceBlockResearchRequirementsState.gd")', bridge_source)
        self.assertNotIn('const source_block_research_requirements_state := preload("res://src/game/SourceBlockResearchRequirementsState.gd")', source)

        delegations = {
            "func source_block_research_requirements_research_cost_state(research_cost: Variant) -> Dictionary:": "\treturn source_block_research_requirements_state.research_cost_state(research_cost)",
            "func source_block_research_requirements_empty_state(research_cost: Variant, research_cost_multiplier: float) -> Dictionary:": "\treturn source_block_research_requirements_state.empty_state(research_cost, research_cost_multiplier)",
            "func source_block_research_requirements_loop_shape_state(research_cost: Variant, research_cost_multiplier: float, requirements: Array) -> Dictionary:": "\treturn source_block_research_requirements_state.loop_shape_state(research_cost, research_cost_multiplier, requirements)",
            "func source_block_research_requirements_quantity_formula_state(research_cost: Variant, research_cost_multiplier: float, requirements: Array, research_cost_multipliers: Dictionary) -> Dictionary:": "\treturn source_block_research_requirements_state.quantity_formula_state(research_cost, research_cost_multiplier, requirements, research_cost_multipliers)",
            "func source_block_research_requirements_round_amount_state(research_cost: Variant, research_cost_multiplier: float, requirements: Array, research_cost_multipliers: Dictionary) -> Dictionary:": "\treturn source_block_research_requirements_state.round_amount_state(research_cost, research_cost_multiplier, requirements, research_cost_multipliers)",
            "func source_block_research_requirements_output_fill_state(research_cost: Variant, research_cost_multiplier: float, requirements: Array, research_cost_multipliers: Dictionary) -> Dictionary:": "\treturn source_block_research_requirements_state.output_fill_state(research_cost, research_cost_multiplier, requirements, research_cost_multipliers)",
        }
        for signature, delegation in delegations.items():
            method_body = self._method_body(bridge_source, signature)
            self.assertIn(delegation, method_body)
            self.assertNotIn('"source": "core/src/mindustry/world/Block.java"', method_body)

        for method_name in (
            "research_cost_state",
            "empty_state",
            "loop_shape_state",
            "quantity_formula_state",
            "round_amount_state",
            "output_fill_state",
        ):
            self.assertIn("static func " + method_name, module_source)

        for source_owner in (
            "PORT_GAME_SOURCE_BLOCK_RESEARCH_REQUIREMENTS_RESEARCH_COST_STATE",
            "PORT_GAME_SOURCE_BLOCK_RESEARCH_REQUIREMENTS_EMPTY_STATE",
            "PORT_GAME_SOURCE_BLOCK_RESEARCH_REQUIREMENTS_LOOP_SHAPE_STATE",
            "PORT_GAME_SOURCE_BLOCK_RESEARCH_REQUIREMENTS_QUANTITY_FORMULA_STATE",
            "PORT_GAME_SOURCE_BLOCK_RESEARCH_REQUIREMENTS_ROUND_AMOUNT_STATE",
            "PORT_GAME_SOURCE_BLOCK_RESEARCH_REQUIREMENTS_OUTPUT_FILL_STATE",
        ):
            self.assertIn('"source_owner": source_runtime_owner_registry.' + source_owner, module_source)

    def test_port_game_delegates_block_research_requirements_generated_bridge_state_to_module(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockResearchRequirementsState.gd"
        port_source = port_game.read_text(encoding="utf-8")
        module_source = module.read_text(encoding="utf-8")

        bridges = {
            "generated_block_research_requirements_research_cost_bridge_state(research_cost: Variant)": ("research_cost", 'var result = source_generated_class_runtime.call_java_method(SOURCE_BLOCK_GENERATED_CLASS, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_JAVA_METHOD_RESEARCH_REQUIREMENTS_118, [research_cost], null)', "var canonical = research_cost_state(research_cost)"),
            "generated_block_research_requirements_empty_bridge_state(research_cost: Variant, research_cost_multiplier: float)": ("research_cost, research_cost_multiplier", 'var result = source_generated_class_runtime.call_java_method(SOURCE_BLOCK_GENERATED_CLASS, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_JAVA_METHOD_RESEARCH_REQUIREMENTS_118, [research_cost, research_cost_multiplier], null)', "var canonical = empty_state(research_cost, research_cost_multiplier)"),
            "generated_block_research_requirements_loop_shape_bridge_state(research_cost: Variant, research_cost_multiplier: float, requirements: Array)": ("research_cost, research_cost_multiplier, requirements", 'var result = source_generated_class_runtime.call_java_method(SOURCE_BLOCK_GENERATED_CLASS, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_JAVA_METHOD_RESEARCH_REQUIREMENTS_118, [research_cost, research_cost_multiplier, requirements], null)', "var canonical = loop_shape_state(research_cost, research_cost_multiplier, requirements)"),
            "generated_block_research_requirements_quantity_formula_bridge_state(research_cost: Variant, research_cost_multiplier: float, requirements: Array, research_cost_multipliers: Dictionary)": ("research_cost, research_cost_multiplier, requirements, research_cost_multipliers", 'var result = source_generated_class_runtime.call_java_method(SOURCE_BLOCK_GENERATED_CLASS, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_JAVA_METHOD_RESEARCH_REQUIREMENTS_118, [research_cost, research_cost_multiplier, requirements, research_cost_multipliers], null)', "var canonical = quantity_formula_state(research_cost, research_cost_multiplier, requirements, research_cost_multipliers)"),
            "generated_block_research_requirements_round_amount_bridge_state(research_cost: Variant, research_cost_multiplier: float, requirements: Array, research_cost_multipliers: Dictionary)": ("research_cost, research_cost_multiplier, requirements, research_cost_multipliers", 'var result = source_generated_class_runtime.call_java_method(SOURCE_BLOCK_GENERATED_CLASS, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_JAVA_METHOD_RESEARCH_REQUIREMENTS_118, [research_cost, research_cost_multiplier, requirements, research_cost_multipliers, true], null)', "var canonical = round_amount_state(research_cost, research_cost_multiplier, requirements, research_cost_multipliers)"),
            "generated_block_research_requirements_output_fill_bridge_state(research_cost: Variant, research_cost_multiplier: float, requirements: Array, research_cost_multipliers: Dictionary)": ("research_cost, research_cost_multiplier, requirements, research_cost_multipliers", 'var result = source_generated_class_runtime.call_java_method(SOURCE_BLOCK_GENERATED_CLASS, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_JAVA_METHOD_RESEARCH_REQUIREMENTS_118, [research_cost, research_cost_multiplier, requirements, research_cost_multipliers, true, true], null)', "var canonical = output_fill_state(research_cost, research_cost_multiplier, requirements, research_cost_multipliers)"),
        }
        self.assertIn('const source_generated_class_runtime := preload("res://src/game/SourceGeneratedClassRuntime.gd")', module_source)
        for signature_tail, (args, generated_call, canonical_call) in bridges.items():
            func_name = signature_tail.split("(", 1)[0]
            port_signature = f"func {signature_tail} -> Dictionary:"
            module_signature = f"static func {signature_tail} -> Dictionary:"
            port_body = self._method_body(port_source, port_signature)
            module_body = self._static_method_body(module_source, module_signature)
            self.assertIn(module_signature, module_source)
            self.assertIn(f"\treturn source_block_research_requirements_state.{func_name}({args})", port_body)
            self.assertNotIn("ResourceLoader.load(", port_body)
            self.assertNotIn("java_method_", port_body)
            self.assertIn(generated_call, module_body)
            self.assertIn(canonical_call, module_body)
            self.assertIn("var matches: bool = source_generated_class_runtime.generated_state_matches_canonical_subset(result, canonical)", module_body)
            self.assertIn('"generated_owner": SOURCE_BLOCK_RESEARCH_REQUIREMENTS_GENERATED_OWNER', module_body)

