    def test_port_game_delegates_block_init_clip_source_state_to_module(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockInitClipState.gd"
        source = port_game.read_text(encoding="utf-8") + "\n" + self._port_game_port_bridge_chain_source()

        self.assertTrue(module.exists(), "source_block_init_clip_state.gd must own Block init clip source state")
        module_source = module.read_text(encoding="utf-8")
        self.assertIn('const source_block_init_clip_state := preload("res://src/game/SourceBlockInitClipState.gd")', source)

        delegations = {
            "func source_block_init_clip_size_state(clip_size_before: float, size_value: int, source_tilesize: float) -> Dictionary:": "\treturn source_block_init_clip_state.clip_size_state(clip_size_before, size_value, source_tilesize)",
            "func source_block_init_light_clip_size_state(light_clip_size_before: float, clip_size: float) -> Dictionary:": "\treturn source_block_init_clip_state.light_clip_size_state(light_clip_size_before, clip_size)",
            "func source_block_init_liquid_light_state(has_liquids: bool, draw_liquid_light: bool, emit_light_before: bool, light_clip_size_before: float, size_value: int) -> Dictionary:": "\treturn source_block_init_clip_state.liquid_light_state(has_liquids, draw_liquid_light, emit_light_before, light_clip_size_before, size_value)",
            "func source_block_init_liquid_capacity_default_state(liquid_capacity_before: float) -> Dictionary:": "\treturn source_block_init_clip_state.liquid_capacity_default_state(liquid_capacity_before)",
            "func source_block_init_emit_light_radius_state(emit_light: bool, light_clip_size_before: float, light_radius: float) -> Dictionary:": "\treturn source_block_init_clip_state.emit_light_radius_state(emit_light, light_clip_size_before, light_radius)",
        }
        for signature, delegation in delegations.items():
            method_body = self._method_body(source, signature)
            self.assertIn(delegation, method_body)
            self.assertNotIn('"source": "core/src/mindustry/world/Block.java"', method_body)

        for method_name in (
            "clip_size_state",
            "light_clip_size_state",
            "liquid_light_state",
            "liquid_capacity_default_state",
            "emit_light_radius_state",
        ):
            self.assertIn("static func " + method_name, module_source)

        for source_owner in (
            "source_runtime_owner_registry.PORT_GAME_SOURCE_BLOCK_INIT_CLIP_SIZE_STATE",
            "source_runtime_owner_registry.PORT_GAME_SOURCE_BLOCK_INIT_LIGHT_CLIP_SIZE_STATE",
            "source_runtime_owner_registry.PORT_GAME_SOURCE_BLOCK_INIT_LIQUID_LIGHT_STATE",
            "source_runtime_owner_registry.PORT_GAME_SOURCE_BLOCK_INIT_LIQUID_CAPACITY_DEFAULT_STATE",
            "source_runtime_owner_registry.PORT_GAME_SOURCE_BLOCK_INIT_EMIT_LIGHT_RADIUS_STATE",
        ):
            self.assertIn('SOURCE_BLOCK_INIT_CLIP_SOURCE_OWNER_KEY: ' + source_owner, module_source)

