            self.assertIn('const source_generated_class_runtime := preload("res://src/game/SourceGeneratedClassRuntime.gd")', module_source)
            self.assertIn("var matches: bool = source_generated_class_runtime.generated_state_matches_canonical_subset(result, canonical)", module_body)
