    def test_port_game_delegates_block_load_generated_bridge_state_to_module(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockLoadState.gd"
        port_source = port_game.read_text(encoding="utf-8") + "\n" + self._port_game_port_bridge_chain_source()
        module_source = module.read_text(encoding="utf-8")

        bridges = {
            "generated_block_load_base_regions_bridge_state(name_value: String)": ("name_value", 'var result = _block_call(SOURCE_BLOCK_LOAD_JAVA_METHOD_LOAD_126, [name_value])', "var canonical = base_regions_state(name_value)", "SOURCE_BLOCK_LOAD_GENERATED_OWNER"),
            "generated_block_load_team_regions_bridge_state(name_value: String, team_region_found: bool, team_region: Variant, teams: Array)": ("name_value, team_region_found, team_region, teams", 'var result = _block_call(SOURCE_BLOCK_LOAD_JAVA_METHOD_LOAD_126, [name_value, team_region_found, team_region, teams], {SOURCE_BLOCK_LOAD_BRIDGE_MODE_KEY: SOURCE_BLOCK_LOAD_TEAM_REGIONS_MODE})', "var canonical = team_regions_state(name_value, team_region_found, team_region, teams)", "SOURCE_BLOCK_LOAD_GENERATED_OWNER"),
            "generated_block_load_variant_regions_bridge_state(name_value: String, variants: int)": ("name_value, variants", 'var result = _block_call(SOURCE_BLOCK_LOAD_JAVA_METHOD_LOAD_126, [name_value, variants], {SOURCE_BLOCK_LOAD_BRIDGE_MODE_KEY: SOURCE_BLOCK_LOAD_VARIANT_REGIONS_MODE})', "var canonical = variant_regions_state(name_value, variants)", "SOURCE_BLOCK_LOAD_GENERATED_OWNER"),
            "generated_block_load_variant_shadow_regions_bridge_state(name_value: String, variants: int, custom_shadow: bool)": ("name_value, variants, custom_shadow", 'var result = _block_call(SOURCE_BLOCK_LOAD_JAVA_METHOD_LOAD_126, [name_value, variants, custom_shadow], {SOURCE_BLOCK_LOAD_BRIDGE_MODE_KEY: SOURCE_BLOCK_LOAD_VARIANT_SHADOW_REGIONS_MODE})', "var canonical = variant_shadow_regions_state(name_value, variants, custom_shadow)", "SOURCE_BLOCK_LOAD_GENERATED_OWNER"),
        }
        self.assertIn('const source_block_source_text_state := preload("res://src/game/SourceBlockSourceTextState.gd")', module_source)
        self.assertIn("const SOURCE_BLOCK_GENERATED_CLASS := source_block_source_text_state.SOURCE_BLOCK_GENERATED_CLASS", module_source)
        self.assertIn("static func _block_call(generated_method: String, generated_args: Array, metadata: Variant = null) -> Variant:", module_source)
        self.assertIn("if metadata == null:", module_source)
        self.assertIn("source_generated_class_runtime.call_java_method(SOURCE_BLOCK_GENERATED_CLASS, generated_method, generated_args, null)", module_source)
        self.assertNotIn('call_java_method("res://src/generated/classes/mindustry/world/Block.gd"', module_source)
        for signature_tail, (args, generated_call, canonical_call, generated_owner) in bridges.items():
            func_name = signature_tail.split("(", 1)[0]
            port_signature = f"func {signature_tail} -> Dictionary:"
            module_signature = f"static func {signature_tail} -> Dictionary:"
            port_body = self._method_body(port_source, port_signature)
            self.assertIn(module_signature, module_source)
            module_body = self._static_method_body(module_source, module_signature)
            self.assertIn(f"\treturn source_block_load_state.{func_name}({args})", port_body)
            self.assertNotIn("ResourceLoader.load(", port_body)
            self.assertNotIn("java_method_", port_body)
            self.assertNotIn('ResourceLoader.load("res://src/generated/classes/mindustry/world/Block.gd")', module_source)
            self.assertNotIn("script.new()", module_source)
            self.assertIn(generated_call, module_body)
            self.assertIn(canonical_call, module_body)
            self.assertIn(f'SOURCE_BLOCK_LOAD_GENERATED_OWNER_KEY: {generated_owner}', module_body)
            self.assertIn('const source_generated_class_runtime := preload("res://src/game/SourceGeneratedClassRuntime.gd")', module_source)
            self.assertIn("var matches: bool = source_generated_class_runtime.generated_state_matches_canonical_subset(result, canonical)", module_body)
            self.assertNotIn("static func generated_state_matches_generated_subset(result: Variant, canonical: Variant) -> bool:", module_source)
            self.assertNotIn('"matches": result == canonical', module_body)
            self.assertNotIn('"generated_owner": "block.java_method_load_126"', module_body)

