    def test_port_game_exposes_source_block_flip_rotation_state(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockPlanState.gd"
        placement = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockPlanPlacementState.gd"
        source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockPlanSourceTextState.gd"
        registry = ROOT / "godot-mindustry" / "src" / "game" / "SourceRuntimeOwnerRegistry.gd"
        source = port_game.read_text(encoding="utf-8") + "\n" + self._port_game_port_bridge_chain_source()
        module_source = module.read_text(encoding="utf-8")
        placement_source = placement.read_text(encoding="utf-8")
        source_text_source = source_text.read_text(encoding="utf-8")
        registry_source = self._runtime_owner_registry_canonical_source()

        self.assertIn("func source_block_flip_rotation_state(rotation_before: int, x_value: bool, invert_flip: bool, rotate_value: bool, lock_rotation: bool) -> Dictionary:", source)
        method_body = self._method_body(source, "func source_block_flip_rotation_state(rotation_before: int, x_value: bool, invert_flip: bool, rotate_value: bool, lock_rotation: bool) -> Dictionary:")
        self.assertIn("return source_block_plan_state.game_flip_rotation_state(self, rotation_before, x_value, invert_flip, rotate_value, lock_rotation)", method_body)
        self.assertNotIn('Callable(self, "source_arc_mathf_mod_float")', method_body)
        self.assertNotIn('Callable(self, "source_block_plan_rotation_state")', method_body)
        self.assertIn("static func default_callbacks_state(game: Object) -> Dictionary:", placement_source)
        callbacks_body = self._method_body(placement_source, "static func default_callbacks_state(game: Object) -> Dictionary:")
        self.assertIn("static func runtime_method_names(game: Object) -> Dictionary:", placement_source)
        self.assertIn('if game.has_method("_block_plan_method_names"):', placement_source)
        self.assertIn("static func runtime_method_name(method_names: Dictionary, key: String, fallback_name: String) -> String:", placement_source)
        self.assertIn("var method_names := runtime_method_names(game)", callbacks_body)
        self.assertNotIn('Callable(game, "source_', callbacks_body)
        for prefix, key, method_name in [
            ("SOURCE_BLOCK_PLAN_MOD_FLOAT", "mod_float", "source_arc_mathf_mod_float"),
            ("SOURCE_BLOCK_PLAN_ROTATION", "plan_rotation", "source_block_plan_rotation_state"),
        ]:
            with self.subTest(key=key):
                self.assertIn(f"const {prefix}_KEY := source_block_plan_source_text_state.{prefix}_KEY", placement_source)
                self.assertIn(f"const {prefix}_FALLBACK := source_block_plan_source_text_state.{prefix}_FALLBACK", placement_source)
                self.assertIn(f'const {prefix}_KEY := "{key}"', source_text_source)
                self.assertIn(f'const {prefix}_FALLBACK := "{method_name}"', source_text_source)
                self.assertIn(f"{prefix}_KEY: Callable(game, runtime_method_name(method_names, {prefix}_KEY, {prefix}_FALLBACK))", callbacks_body)
        self.assertIn("static func game_flip_rotation_state(game: Object, rotation_before: int, x_value: bool, invert_flip: bool, rotate_value: bool, lock_rotation: bool) -> Dictionary:", placement_source)
        self.assertIn("var callbacks := default_callbacks_state(game)", placement_source)
        self.assertIn("callbacks.get(SOURCE_BLOCK_PLAN_MOD_FLOAT_KEY, Callable())", placement_source)
        self.assertIn("callbacks.get(SOURCE_BLOCK_PLAN_ROTATION_KEY, Callable())", placement_source)
        self.assertIn("static func flip_rotation_state(rotation_before: int, x_value: bool, invert_flip: bool, rotate_value: bool, lock_rotation: bool, mod_fn: Callable, plan_rotation_fn: Callable) -> Dictionary:", placement_source)
        self.assertIn("var rotation_even: bool = rotation_before % 2 == 0", placement_source)
        self.assertIn("var flip_guard: bool = (x_value == rotation_even) != invert_flip", placement_source)
        self.assertIn("var mod_value: int = int(mod_fn.call(float(rotation_before + 2), 4.0))", placement_source)
        self.assertIn("var rotation_plan_state: Dictionary = plan_rotation_fn.call(rotate_value, lock_rotation, mod_value)", placement_source)
        self.assertIn("var rotation_after: int = int(rotation_plan_state[\"plan_rotation\"]) if flip_guard else rotation_before", placement_source)
        self.assertIn('const PORT_GAME_SOURCE_BLOCK_FLIP_ROTATION_STATE := "port_game.source_block_flip_rotation_state"', registry_source)
        self.assertIn('SOURCE_BLOCK_PLAN_SOURCE_OWNER_KEY: source_runtime_owner_registry.PORT_GAME_SOURCE_BLOCK_FLIP_ROTATION_STATE', placement_source)
        self.assertIn('const SOURCE_BLOCK_PLAN_FLIP_ROTATION_METHOD := source_block_plan_source_text_state.SOURCE_BLOCK_PLAN_FLIP_ROTATION_METHOD', placement_source)
        self.assertIn('const SOURCE_BLOCK_PLAN_FLIP_ROTATION_GUARD_EXPR := source_block_plan_source_text_state.SOURCE_BLOCK_PLAN_FLIP_ROTATION_GUARD_EXPR', placement_source)
        self.assertIn('const SOURCE_BLOCK_PLAN_FLIP_ROTATION_ASSIGNMENT_EXPR := source_block_plan_source_text_state.SOURCE_BLOCK_PLAN_FLIP_ROTATION_ASSIGNMENT_EXPR', placement_source)
        self.assertIn('const SOURCE_BLOCK_PLAN_FLIP_ROTATION_METHOD := "public void flipRotation(BuildPlan req, boolean x){"', source_text_source)
        self.assertIn('const SOURCE_BLOCK_PLAN_FLIP_ROTATION_GUARD_EXPR := "if((x == (req.rotation % 2 == 0)) != invertFlip){"', source_text_source)
        self.assertIn('const SOURCE_BLOCK_PLAN_FLIP_ROTATION_ASSIGNMENT_EXPR := "req.rotation = planRotation(Mathf.mod(req.rotation + 2, 4));"', source_text_source)
        self.assertIn('SOURCE_BLOCK_PLAN_ROTATION_AFTER_KEY: rotation_after', placement_source)

