    def test_source_payload_source_text_state_owns_build_payload_generated_class(self):
        owner = ROOT / "godot-mindustry" / "src" / "game" / "SourcePayloadSourceTextState.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildPayloadState.gd"
        owner_source = owner.read_text(encoding="utf-8") if owner.exists() else ""
        module_source = module.read_text(encoding="utf-8")

        self.assertTrue(owner.exists(), "SourcePayloadSourceTextState.gd must own payload generated class paths")
        self.assertIn("class_name SourcePayloadSourceTextState", owner_source)
        self.assertIn('const SOURCE_BUILD_PAYLOAD_SOURCE := "core/src/mindustry/world/blocks/payloads/BuildPayload.java"', owner_source)
        self.assertIn('const SOURCE_BUILD_PAYLOAD_GENERATED_CLASS := "res://src/generated/classes/mindustry/world/blocks/payloads/BuildPayload.gd"', owner_source)
        self.assertIn('const source_payload_source_text_state := preload("res://src/game/SourcePayloadSourceTextState.gd")', module_source)
        self.assertIn("const SOURCE_BUILD_PAYLOAD_SOURCE := source_payload_source_text_state.SOURCE_BUILD_PAYLOAD_SOURCE", module_source)
        self.assertIn("const BUILD_PAYLOAD_GENERATED_CLASS := source_payload_source_text_state.SOURCE_BUILD_PAYLOAD_GENERATED_CLASS", module_source)
        self.assertIn("static func _build_payload_call(generated_method: String, generated_args: Array) -> Variant:", module_source)
        self.assertIn("source_generated_class_runtime.call_java_method(BUILD_PAYLOAD_GENERATED_CLASS, generated_method, generated_args, null)", module_source)
        self.assertNotIn('call_java_method("res://src/generated/classes/mindustry/world/blocks/payloads/BuildPayload.gd"', module_source)

    def test_port_game_delegates_build_payload_basic_generated_bridge_state_to_module(self):
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildPayloadState.gd"
        port_source = self._port_game_build_payload_source()
        module_source = module.read_text(encoding="utf-8")

        bridges = {
            "generated_build_payload_block_bridge_state(build_block: Variant)": ("build_block", "var result = _build_payload_call(SOURCE_BUILD_PAYLOAD_BLOCK_JAVA_METHOD, [build_block])", "var canonical = block_state(build_block)", "SOURCE_BUILD_PAYLOAD_BLOCK_GENERATED_OWNER"),
            "generated_build_payload_constructor_block_team_bridge_state(block: Variant, team: Variant)": ("block, team", "var result = _build_payload_call(SOURCE_BUILD_PAYLOAD_CONSTRUCTOR_BLOCK_TEAM_JAVA_METHOD, [block, team])", "var canonical = constructor_block_team_state(block, team)", "SOURCE_BUILD_PAYLOAD_CONSTRUCTOR_BLOCK_TEAM_GENERATED_OWNER"),
            "generated_build_payload_constructor_build_bridge_state(build: Variant)": ("build", "var result = _build_payload_call(SOURCE_BUILD_PAYLOAD_CONSTRUCTOR_BUILD_JAVA_METHOD, [build])", "var canonical = constructor_build_state(build)", "SOURCE_BUILD_PAYLOAD_CONSTRUCTOR_BUILD_GENERATED_OWNER"),
        }
        for signature_tail, (args, generated_call, canonical_call, generated_owner) in bridges.items():
            func_name = signature_tail.split("(", 1)[0]
            port_signature = f"func {signature_tail} -> Dictionary:"
            module_signature = f"static func {signature_tail} -> Dictionary:"
            port_body = self._method_body(port_source, port_signature)
            self.assertIn(module_signature, module_source)
            module_body = self._static_method_body(module_source, module_signature)
            self.assertIn(f"\treturn source_build_payload_state.{func_name}({args})", port_body)
            self.assertNotIn("source_generated_class_runtime.call_java_method", port_body)
            self.assertNotIn("ResourceLoader.load(", port_body)
            self.assertNotIn("java_method_", port_body)
            self.assertIn('const source_generated_class_runtime := preload("res://src/game/SourceGeneratedClassRuntime.gd")', module_source)
            self.assertIn("const BUILD_PAYLOAD_GENERATED_CLASS := source_payload_source_text_state.SOURCE_BUILD_PAYLOAD_GENERATED_CLASS", module_source)
            self.assertIn(generated_call, module_body)
            self.assertNotIn("ResourceLoader.load(", module_body)
            self.assertNotIn("script.new()", module_body)
            self.assertIn(canonical_call, module_body)
            self.assertIn(f'"generated_owner": {generated_owner}', module_body)
            self.assertIn("var matches: bool = source_generated_class_runtime.generated_state_matches_canonical_subset(result, canonical)", module_body)
            self.assertNotIn('"matches": result == canonical', module_body)

    def test_build_payload_module_proof_scene_exists(self):
        proof_script = ROOT / "godot-mindustry" / "tools" / "runtime_proofs" / "BuildPayloadModuleProof.gd"
        proof_scene = ROOT / "godot-mindustry" / "tools" / "runtime_proofs" / "BuildPayloadModuleProof.tscn"

        self.assertTrue(proof_script.exists(), "BuildPayload module runtime proof script must exist")
        self.assertTrue(proof_scene.exists(), "BuildPayload module runtime proof scene must exist")
        scene_source = proof_scene.read_text(encoding="utf-8")
        proof_source = proof_script.read_text(encoding="utf-8")
        self.assertIn('path="res://tools/runtime_proofs/BuildPayloadModuleProof.gd"', scene_source)
        self.assertIn("BUILD_PAYLOAD_MODULE_PROOF", proof_source)
        self.assertIn("SourceBuildPayloadDrawState", proof_source)
        self.assertIn('"content_bridge_matches"', proof_source)
        self.assertIn('"draw_bridge_matches"', proof_source)
        self.assertIn('"icon_bridge_matches"', proof_source)
        self.assertIn("source_ssot_accessor_runtime_state.canonical_headquarter_registry_state()", proof_source)
        self.assertIn('"one_headquarter_per_ssot"', proof_source)
        self._assert_runtime_proof_uses_canonical_finalizer(proof_source, "BuildPayloadModuleProof")

