    def test_port_game_delegates_build_payload_draw_source_state_to_module(self):
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBuildPayloadDrawState.gd"
        source = self._port_game_build_payload_draw_source()

        self.assertTrue(module.exists(), "source_build_payload_draw_state_script.gd must own BuildPayload visual source state")
        module_source = module.read_text(encoding="utf-8")
        self.assertIn('const source_build_payload_draw_state_script := preload("res://src/game/SourceBuildPayloadDrawState.gd")', source)

        delegations = {
            "func source_build_payload_draw_shadow_state(build_x: float, build_y: float, build_block_size: float, source_tilesize: float, alpha: float) -> Dictionary:": "\treturn source_build_payload_draw_state_script.draw_shadow_state(build_x, build_y, build_block_size, source_tilesize, alpha)",
            "func source_build_payload_draw_state(prev_z: float, layer_flying_unit_low: float, transform_z: float) -> Dictionary:": "\treturn source_build_payload_draw_state_script.draw_state(prev_z, layer_flying_unit_low, transform_z)",
            "func source_build_payload_icon_state(full_icon: Variant) -> Dictionary:": "\treturn source_build_payload_draw_state_script.icon_state(full_icon)",
        }
        for signature, delegation in delegations.items():
            method_body = self._method_body(source, signature)
            self.assertIn(delegation, method_body)
            self.assertNotIn('"source": "core/src/mindustry/world/blocks/payloads/BuildPayload.java"', method_body)

        for method_name in (
            "draw_shadow_state",
            "draw_state",
            "icon_state",
        ):
            self.assertIn("static func " + method_name, module_source)

        for source_owner in (
            "source_runtime_owner_registry.PORT_GAME_SOURCE_BUILD_PAYLOAD_DRAW_SHADOW_STATE",
            "source_runtime_owner_registry.PORT_GAME_SOURCE_BUILD_PAYLOAD_DRAW_STATE",
            "source_runtime_owner_registry.PORT_GAME_SOURCE_BUILD_PAYLOAD_ICON_STATE",
        ):
            self.assertIn('"source_owner": ' + source_owner, module_source)

