        self.assertIn('const SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR := "@Override"', source_text_source)
        for expected in (
            'const SOURCE_UNIT_PAYLOAD_SOURCE := "core/src/mindustry/world/blocks/payloads/UnitPayload.java"',
            'const SOURCE_UNIT_PAYLOAD_CLASS_EXPR := "public class UnitPayload implements Payload{"',
            'const SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR := "public Unit unit;"',
        ):
            self.assertIn(expected, source_text_source)
            self.assertNotIn(expected, basic_source)
        for expected in (
            "const SOURCE_UNIT_PAYLOAD_SOURCE := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_SOURCE",
            "const SOURCE_UNIT_PAYLOAD_CLASS_EXPR := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_CLASS_EXPR",
            "const SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR",
        ):
            self.assertIn(expected, basic_source)
        self.assertIn('const SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR', basic_source)
        self.assertNotIn('const SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR := "@Override"', basic_source)

        for expected in (
            'const source_unit_payload_basic_state := preload("res://src/game/SourceUnitPayloadBasicState.gd")',
            'const source_runtime_owner_registry := preload("res://src/game/SourceRuntimeOwnerRegistry.gd")',
            'const source_payload_source_text_state := preload("res://src/game/SourcePayloadSourceTextState.gd")',
            'const SOURCE_UNIT_PAYLOAD_CONTENT_EQUALS_METHOD := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_CONTENT_EQUALS_METHOD',
            'const SOURCE_UNIT_PAYLOAD_CONTENT_EQUALS_RETURN_EXPR := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_CONTENT_EQUALS_RETURN_EXPR',
            'const SOURCE_UNIT_PAYLOAD_UPDATE_METHOD := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_UPDATE_METHOD',
            'const SOURCE_UNIT_PAYLOAD_UPDATE_PAYLOAD_EXPR := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_UPDATE_PAYLOAD_EXPR',
            'const SOURCE_UNIT_PAYLOAD_CONTENT_METHOD := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_CONTENT_METHOD',
            'const SOURCE_UNIT_PAYLOAD_CONTENT_RETURN_EXPR := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_CONTENT_RETURN_EXPR',
        ):
            self.assertIn(expected, module_source)

        body_expectations = {
            "content_equals_state": (
                '"source_owner": source_runtime_owner_registry.PORT_GAME_SOURCE_UNIT_PAYLOAD_CONTENT_EQUALS_STATE',
                '"source": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_SOURCE',
                '"class_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_CLASS_EXPR',
                '"field_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR',
                '"override_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR',
                '"method": SOURCE_UNIT_PAYLOAD_CONTENT_EQUALS_METHOD',
                '"return_expr": SOURCE_UNIT_PAYLOAD_CONTENT_EQUALS_RETURN_EXPR',
            ),
            "update_state": (
                '"source_owner": source_runtime_owner_registry.PORT_GAME_SOURCE_UNIT_PAYLOAD_UPDATE_STATE',
                '"source": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_SOURCE',
                '"class_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_CLASS_EXPR',
                '"field_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR',
                '"override_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR',
                '"method": SOURCE_UNIT_PAYLOAD_UPDATE_METHOD',
                '"update_payload_expr": SOURCE_UNIT_PAYLOAD_UPDATE_PAYLOAD_EXPR',
            ),
            "content_state": (
                '"source_owner": source_runtime_owner_registry.PORT_GAME_SOURCE_UNIT_PAYLOAD_CONTENT_STATE',
                '"source": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_SOURCE',
                '"class_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_CLASS_EXPR',
                '"field_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR',
                '"override_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR',
                '"method": SOURCE_UNIT_PAYLOAD_CONTENT_METHOD',
                '"return_expr": SOURCE_UNIT_PAYLOAD_CONTENT_RETURN_EXPR',
            ),
        }
        duplicate_literals = (
            '"source_owner": "port_game.source_unit_payload_content_equals_state"',
            '"source_owner": "port_game.source_unit_payload_update_state"',
            '"source_owner": "port_game.source_unit_payload_content_state"',
            '"source": "core/src/mindustry/world/blocks/payloads/UnitPayload.java"',
            '"class_expr": "public class UnitPayload implements Payload{"',
            '"field_expr": "public Unit unit;"',
            '"override_expr": "@Override"',
            '"method": "public boolean contentEquals(Payload other){"',
            '"return_expr": "return other instanceof UnitPayload up && up.unit.type == unit.type;"',
            '"method": "public void update(@Nullable Unit unitHolder, @Nullable Building buildingHolder){"',
            '"update_payload_expr": "unit.type.updatePayload(unit, unitHolder, buildingHolder);"',
            '"method": "public UnlockableContent content(){"',
            '"return_expr": "return unit.type;"',
        )
        for method_name, expected_lines in body_expectations.items():
            method_body = module_source.split("static func " + method_name, 1)[1].split("\nstatic func ", 1)[0]
            for expected in expected_lines:
                self.assertIn(expected, method_body)
            for duplicate_literal in duplicate_literals:
                self.assertNotIn(duplicate_literal, method_body)

