    def test_unit_payload_requirements_uses_canonical_module_constants_without_duplicate_literals(self):
        basic = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitPayloadBasicState.gd"
        source_text = ROOT / "godot-mindustry" / "src" / "game" / "SourcePayloadSourceTextState.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitPayloadRequirementsState.gd"
        basic_source = basic.read_text(encoding="utf-8")
        source_text_source = source_text.read_text(encoding="utf-8")
        module_source = module.read_text(encoding="utf-8")

        for expected in (
            'const SOURCE_UNIT_PAYLOAD_SOURCE := "core/src/mindustry/world/blocks/payloads/UnitPayload.java"',
            'const SOURCE_UNIT_PAYLOAD_CLASS_EXPR := "public class UnitPayload implements Payload{"',
            'const SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR := "public Unit unit;"',
        ):
            self.assertIn(expected, source_text_source)
            self.assertNotIn(expected, basic_source)

        for expected in (
            "const SOURCE_UNIT_PAYLOAD_SOURCE := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_SOURCE",
            "const SOURCE_UNIT_PAYLOAD_CLASS_EXPR := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_CLASS_EXPR",
            "const SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR",
            'const SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR',
        ):
            self.assertIn(expected, basic_source)

        for expected in (
            'const source_unit_payload_basic_state := preload("res://src/game/SourceUnitPayloadBasicState.gd")',
            'const source_payload_source_text_state := preload("res://src/game/SourcePayloadSourceTextState.gd")',
            'const SOURCE_UNIT_PAYLOAD_GENERATED_CLASS := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_GENERATED_CLASS',
            'const SOURCE_UNIT_PAYLOAD_REQUIREMENTS_METHOD := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_REQUIREMENTS_METHOD',
            'const SOURCE_UNIT_PAYLOAD_REQUIREMENTS_RETURN_EXPR := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_REQUIREMENTS_RETURN_EXPR',
            'const SOURCE_UNIT_PAYLOAD_REQUIREMENTS_CALL_EXPR := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_REQUIREMENTS_CALL_EXPR',
            'const SOURCE_UNIT_PAYLOAD_BUILD_TIME_METHOD := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_BUILD_TIME_METHOD',
            'const SOURCE_UNIT_PAYLOAD_BUILD_TIME_RETURN_EXPR := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_BUILD_TIME_RETURN_EXPR',
            'const SOURCE_UNIT_PAYLOAD_BUILD_TIME_CALL_EXPR := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_BUILD_TIME_CALL_EXPR',
            'const SOURCE_UNIT_PAYLOAD_REQUIREMENTS_JAVA_METHOD := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_REQUIREMENTS_JAVA_METHOD',
            'const SOURCE_UNIT_PAYLOAD_REQUIREMENTS_GENERATED_OWNER := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_REQUIREMENTS_GENERATED_OWNER',
            'const SOURCE_UNIT_PAYLOAD_BUILD_TIME_JAVA_METHOD := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_BUILD_TIME_JAVA_METHOD',
            'const SOURCE_UNIT_PAYLOAD_BUILD_TIME_GENERATED_OWNER := source_payload_source_text_state.SOURCE_UNIT_PAYLOAD_BUILD_TIME_GENERATED_OWNER',
        ):
            self.assertIn(expected, module_source)
        self.assertIn("static func _unit_payload_call(generated_method: String, generated_args: Array) -> Variant:", module_source)
        self.assertIn("source_generated_class_runtime.call_java_method(SOURCE_UNIT_PAYLOAD_GENERATED_CLASS, generated_method, generated_args, null)", module_source)
        self.assertIn('var result = _unit_payload_call(SOURCE_UNIT_PAYLOAD_REQUIREMENTS_JAVA_METHOD, [unit_type, total_requirements])', module_source)
        self.assertIn('var result = _unit_payload_call(SOURCE_UNIT_PAYLOAD_BUILD_TIME_JAVA_METHOD, [unit_type, build_time])', module_source)
        self.assertNotIn('call_java_method("res://src/generated/classes/mindustry/world/blocks/payloads/UnitPayload.gd"', module_source)

        body_expectations = {
            "requirements_state": (
                '"source": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_SOURCE',
                '"class_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_CLASS_EXPR',
                '"field_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR',
                '"override_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR',
                '"method": SOURCE_UNIT_PAYLOAD_REQUIREMENTS_METHOD',
                '"return_expr": SOURCE_UNIT_PAYLOAD_REQUIREMENTS_RETURN_EXPR',
                '{"call": SOURCE_UNIT_PAYLOAD_REQUIREMENTS_CALL_EXPR',
            ),
            "build_time_state": (
                '"source": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_SOURCE',
                '"class_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_CLASS_EXPR',
                '"field_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR',
                '"override_expr": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR',
                '"method": SOURCE_UNIT_PAYLOAD_BUILD_TIME_METHOD',
                '"return_expr": SOURCE_UNIT_PAYLOAD_BUILD_TIME_RETURN_EXPR',
                '{"call": SOURCE_UNIT_PAYLOAD_BUILD_TIME_CALL_EXPR',
            ),
        }
        duplicate_literals = (
            '"source": "core/src/mindustry/world/blocks/payloads/UnitPayload.java"',
            '"class_expr": "public class UnitPayload implements Payload{"',
            '"field_expr": "public Unit unit;"',
            '"override_expr": "@Override"',
            '"method": "public ItemStack[] requirements(){"',
            '"return_expr": "return unit.type.getTotalRequirements();"',
            '{"call": "unit.type.getTotalRequirements();"',
            '"method": "public float buildTime(){"',
            '"return_expr": "return unit.type.getBuildTime();"',
            '{"call": "unit.type.getBuildTime();"',
        )
        for method_name, expected_lines in body_expectations.items():
            method_body = module_source.split("static func " + method_name, 1)[1].split("\nstatic func ", 1)[0]
            for expected in expected_lines:
                self.assertIn(expected, method_body)
            for duplicate_literal in duplicate_literals:
                self.assertNotIn(duplicate_literal, method_body)

