    def test_port_game_exposes_source_unit_payload_dump_solidity_guard_state(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitPayloadDumpState.gd"
        guard_helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitPayloadDumpGuardState.gd"
        solidity_helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitPayloadDumpSolidityGuardState.gd"
        world_defaults = ROOT / "godot-mindustry" / "src" / "game" / "SourceWorldDefaults.gd"
        source = self._port_game_unit_payload_dump_source()
        port_source = port_game.read_text(encoding="utf-8") + "\n" + self._port_game_port_bridge_chain_source()
        helper_source = helper.read_text(encoding="utf-8")
        guard_source = guard_helper.read_text(encoding="utf-8") if guard_helper.exists() else ""
        solidity_source = solidity_helper.read_text(encoding="utf-8") if solidity_helper.exists() else ""
        world_source = world_defaults.read_text(encoding="utf-8")

        self.assertIn("func source_unit_payload_dump_solidity_guard_state(unit_type_null: bool, units_can_create: bool, solid_present: bool, unit_rotation: float, unit_x: float, unit_y: float, solid_solid: bool) -> Dictionary:", source)
        self.assertIn("return source_unit_payload_dump_state.solidity_guard_state(unit_type_null, units_can_create, solid_present, unit_rotation, unit_x, unit_y, solid_solid)", source)
        self.assertIn("const UNIT_PAYLOAD_DUMP_SOLID_LOOKAHEAD := 1.0", world_source)
        self.assertIn("const SOURCE_UNIT_PAYLOAD_DUMP_SOLID_LOOKAHEAD := source_unit_payload_dump_solidity_guard_state.SOURCE_UNIT_PAYLOAD_DUMP_SOLID_LOOKAHEAD", guard_source)
        self.assertIn("const SOURCE_UNIT_PAYLOAD_DUMP_SOLID_LOOKAHEAD := source_world_defaults.UNIT_PAYLOAD_DUMP_SOLID_LOOKAHEAD", solidity_source)
        self.assertIn("const SOURCE_UNIT_PAYLOAD_DUMP_SOLID_LOOKAHEAD := source_unit_payload_dump_guard_state.SOURCE_UNIT_PAYLOAD_DUMP_SOLID_LOOKAHEAD", helper_source)
        self.assertNotIn("const SOURCE_TILESIZE := source_world_defaults.TILESIZE", helper_source)
        self.assertNotIn("const SOURCE_UNIT_PAYLOAD_DUMP_SOLID_LOOKAHEAD := source_world_defaults.UNIT_PAYLOAD_DUMP_SOLID_LOOKAHEAD", port_source)
        self.assertIn("static func solidity_guard_state(unit_type_null: bool, units_can_create: bool, solid_present: bool, unit_rotation: float, unit_x: float, unit_y: float, solid_solid: bool) -> Dictionary:", helper_source)
        self.assertIn("return source_unit_payload_dump_solidity_guard_state.solidity_guard_state(unit_type_null, units_can_create, solid_present, unit_rotation, unit_x, unit_y, solid_solid)", guard_source)
        self.assertIn('"source_owner": source_runtime_owner_registry.PORT_GAME_SOURCE_UNIT_PAYLOAD_DUMP_SOLIDITY_GUARD_STATE', solidity_source)
        self.assertIn('"source": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_SOURCE', solidity_source)
        self.assertIn('"arc_vec2_source": SOURCE_UNIT_PAYLOAD_DUMP_ARC_VEC2_SOURCE', solidity_source)
        self.assertIn('"world_source": SOURCE_UNIT_PAYLOAD_DUMP_WORLD_SOURCE', solidity_source)
        self.assertIn('"vars_source": SOURCE_UNIT_PAYLOAD_DUMP_VARS_SOURCE', solidity_source)
        self.assertIn('"solidity_comment_expr": SOURCE_UNIT_PAYLOAD_DUMP_SOLIDITY_COMMENT_EXPR', solidity_source)
        self.assertIn('"solid_assign_expr": SOURCE_UNIT_PAYLOAD_DUMP_SOLID_ASSIGN_EXPR', solidity_source)
        self.assertIn('"solid_guard_expr": SOURCE_UNIT_PAYLOAD_DUMP_SOLID_GUARD_EXPR', solidity_source)
        self.assertIn('"trns_expr": SOURCE_UNIT_PAYLOAD_DUMP_TRNS_EXPR', solidity_source)
        self.assertIn('"vec2_trns_amount_expr": SOURCE_UNIT_PAYLOAD_DUMP_VEC2_TRNS_AMOUNT_EXPR', solidity_source)
        self.assertIn('"vec2_trns_amount_return_expr": SOURCE_UNIT_PAYLOAD_DUMP_VEC2_TRNS_AMOUNT_RETURN_EXPR', solidity_source)
        self.assertIn('"tile_assign_expr": SOURCE_UNIT_PAYLOAD_DUMP_TILE_ASSIGN_EXPR', solidity_source)
        self.assertIn('"world_to_tile_method": SOURCE_UNIT_PAYLOAD_DUMP_WORLD_TO_TILE_METHOD', solidity_source)
        self.assertIn('"world_to_tile_return": SOURCE_UNIT_PAYLOAD_DUMP_WORLD_TO_TILE_RETURN', solidity_source)
        self.assertIn('"vars_tilesize_field": SOURCE_UNIT_PAYLOAD_DUMP_VARS_TILESIZE_FIELD', solidity_source)
        self.assertIn('"solid_solid_guard_expr": SOURCE_UNIT_PAYLOAD_DUMP_SOLID_SOLID_GUARD_EXPR', solidity_source)
        self.assertIn("var solid_lookahead: float = SOURCE_UNIT_PAYLOAD_DUMP_SOLID_LOOKAHEAD", solidity_source)
        self.assertIn("var trns_vec: Dictionary = trns_vec_state(unit_rotation, solid_lookahead, 0.0) if solid_present_guard else {\"x\": 0.0, \"y\": 0.0}", solidity_source)
        self.assertIn("var tx: int = int(round((unit_x + float(trns_vec.get(\"x\", 0.0))) / source_world_defaults.TILESIZE)) if solid_present_guard else 0", solidity_source)
        self.assertIn("var ty: int = int(round((unit_y + float(trns_vec.get(\"y\", 0.0))) / source_world_defaults.TILESIZE)) if solid_present_guard else 0", solidity_source)
        self.assertIn("var solid_guard: bool = solid_solid_evaluated and solid_solid", solidity_source)
        self.assertIn('"solid_call": solid_call', solidity_source)
        self.assertIn('"deferred_remaining_dump": deferred_remaining_dump', solidity_source)

    def test_port_game_exposes_generated_unit_payload_dump_solidity_guard_bridge_state(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitPayloadDumpState.gd"
        generated_bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitPayloadDumpGeneratedBridgeState.gd"
        source = self._port_game_unit_payload_dump_source()
        port_source = port_game.read_text(encoding="utf-8") + "\n" + self._port_game_port_bridge_chain_source()
        helper_source = helper.read_text(encoding="utf-8")
        helper_body = self._static_method_body(helper_source, "static func generated_solidity_guard_bridge_state(unit_type_null: bool, units_can_create: bool, solid_present: bool, unit_rotation: float, unit_x: float, unit_y: float, solid_solid: bool) -> Dictionary:")
        generated_bridge_source = generated_bridge.read_text(encoding="utf-8") if generated_bridge.exists() else ""
        generated_bridge_body = self._static_method_body(generated_bridge_source, "static func generated_solidity_guard_bridge_state(unit_type_null: bool, units_can_create: bool, solid_present: bool, unit_rotation: float, unit_x: float, unit_y: float, solid_solid: bool, canonical_solidity_guard: Callable) -> Dictionary:")
        generated_payload = ROOT / "godot-mindustry" / "src" / "generated" / "classes" / "mindustry" / "world" / "blocks" / "payloads" / "UnitPayload.gd"
        generated_source = generated_payload.read_text(encoding="utf-8")

        self.assertIn('const source_unit_payload_dump_state := preload("res://src/game/SourceUnitPayloadDumpState.gd")', generated_source)
        self.assertIn('const source_world_defaults := preload("res://src/game/SourceWorldDefaults.gd")', generated_source)
        self.assertIn("const SOURCE_TILESIZE := source_world_defaults.TILESIZE", generated_source)
        self.assertIn("const SOURCE_UNIT_PAYLOAD_DUMP_SOLID_LOOKAHEAD := source_unit_payload_dump_state.SOURCE_UNIT_PAYLOAD_DUMP_SOLID_LOOKAHEAD", generated_source)
        self.assertIn("var source_tilesize: float = SOURCE_TILESIZE", generated_source)
        self.assertIn("var solid_lookahead: float = SOURCE_UNIT_PAYLOAD_DUMP_SOLID_LOOKAHEAD", generated_source)
