    def test_port_game_exposes_generated_unit_payload_dump_spawn_side_effects_bridge_state(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitPayloadDumpState.gd"
        generated_bridge = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitPayloadDumpGeneratedBridgeState.gd"
        generated_payload = ROOT / "godot-mindustry" / "src" / "generated" / "classes" / "mindustry" / "world" / "blocks" / "payloads" / "UnitPayload.gd"
        source = self._port_game_unit_payload_dump_source()
        port_source = port_game.read_text(encoding="utf-8") + "\n" + self._port_game_port_bridge_chain_source()
        helper_source = helper.read_text(encoding="utf-8")
        helper_body = self._static_method_body(helper_source, "static func generated_spawn_side_effects_bridge_state(unit_type_null: bool, units_can_create: bool, solid_present: bool, unit_rotation: float, unit_x: float, unit_y: float, solid_solid: bool, unit_type_flying: bool, unit_physic_size: float, units_count: int, net_client: bool, range_x: float, range_y: float, unit_id: Variant) -> Dictionary:")
        generated_bridge_source = generated_bridge.read_text(encoding="utf-8") if generated_bridge.exists() else ""
        generated_bridge_body = self._static_method_body(generated_bridge_source, "static func generated_spawn_side_effects_bridge_state(unit_type_null: bool, units_can_create: bool, solid_present: bool, unit_rotation: float, unit_x: float, unit_y: float, solid_solid: bool, unit_type_flying: bool, unit_physic_size: float, units_count: int, net_client: bool, range_x: float, range_y: float, unit_id: Variant, canonical_no_client_guard: Callable, canonical_spawn_side_effects: Callable) -> Dictionary:")
        generated_source = generated_payload.read_text(encoding="utf-8")
        dump_source = generated_source.split("func java_method_dump_13", 1)[1].split("func java_method_drawShadow_14", 1)[0]

        self._assert_runtime_bridge_moved_to_module(
            source,
            generated_bridge_source,
            "func generated_unit_payload_dump_spawn_side_effects_bridge_state(unit_type_null: bool, units_can_create: bool, solid_present: bool, unit_rotation: float, unit_x: float, unit_y: float, solid_solid: bool, unit_type_flying: bool, unit_physic_size: float, units_count: int, net_client: bool, range_x: float, range_y: float, unit_id: Variant) -> Dictionary:",
            "static func generated_spawn_side_effects_bridge_state(unit_type_null: bool, units_can_create: bool, solid_present: bool, unit_rotation: float, unit_x: float, unit_y: float, solid_solid: bool, unit_type_flying: bool, unit_physic_size: float, units_count: int, net_client: bool, range_x: float, range_y: float, unit_id: Variant, canonical_no_client_guard: Callable, canonical_spawn_side_effects: Callable) -> Dictionary:",
            "\treturn source_unit_payload_dump_state.generated_spawn_side_effects_bridge_state(unit_type_null, units_can_create, solid_present, unit_rotation, unit_x, unit_y, solid_solid, unit_type_flying, unit_physic_size, units_count, net_client, range_x, range_y, unit_id)",
            "res://src/generated/classes/mindustry/world/blocks/payloads/UnitPayload.gd",
            "java_method_dump_13",
            "unit_type_null, units_can_create, solid_present, unit_rotation, unit_x, unit_y, solid_solid, unit_type_flying, unit_physic_size, units_count, net_client, range_x, range_y, unit_id",
            "var canonical: Dictionary = canonical_spawn_side_effects.call(state, range_x, range_y, unit_id)",
            "source_runtime_owner_registry.PORT_GAME_SOURCE_UNIT_PAYLOAD_DUMP_SPAWN_SIDE_EFFECTS_STATE",
            "unit_payload.java_method_dump_13",
            source_owner_is_expression=True,
            generated_owner_expression="SOURCE_UNIT_PAYLOAD_DUMP_GENERATED_OWNER",
        )
        self.assertIn('\treturn source_unit_payload_dump_generated_bridge_state.generated_spawn_side_effects_bridge_state(unit_type_null, units_can_create, solid_present, unit_rotation, unit_x, unit_y, solid_solid, unit_type_flying, unit_physic_size, units_count, net_client, range_x, range_y, unit_id, Callable(source_unit_payload_dump_guard_state, "no_client_guard_state"), Callable(SourceUnitPayloadDumpState, "spawn_side_effects_state"))', helper_body)
        self.assertNotIn("source_generated_class_runtime.call_java_method", helper_body)
        self.assertIn("var state: Dictionary = canonical_no_client_guard.call(unit_type_null, units_can_create, solid_present, unit_rotation, unit_x, unit_y, solid_solid, unit_type_flying, unit_physic_size, units_count, net_client)", generated_bridge_body)
        self._assert_source_consts_in_helper_not_port(port_source + "\n" + helper_source, generated_bridge_source, [
            'const SOURCE_UNIT_PAYLOAD_DUMP_SPAWN_SIDE_EFFECTS_BRIDGE_IGNORED_KEYS := ["source_owner", "returned", "dump", "deferred_remaining_dump", "trns_vec"]',
        ])
        self.assertIn("var matches: bool = source_generated_class_runtime.generated_state_matches_canonical_subset(result, canonical, SOURCE_UNIT_PAYLOAD_DUMP_SPAWN_SIDE_EFFECTS_BRIDGE_IGNORED_KEYS)", generated_bridge_body)
        self.assertNotIn("static func generated_state_matches_generated_subset(result: Variant, canonical: Dictionary, ignored_keys: Array = []) -> bool:", generated_bridge_source)
        self.assertIn('"matches": matches', generated_bridge_body)
        self.assertIn('"source": source_unit_payload_basic_state.SOURCE_UNIT_PAYLOAD_SOURCE', dump_source)
        self.assertIn('"method": source_unit_payload_dump_state.SOURCE_UNIT_PAYLOAD_DUMP_METHOD', dump_source)
        self.assertIn('"overlap_guard_expr": source_unit_payload_dump_state.SOURCE_UNIT_PAYLOAD_DUMP_OVERLAP_GUARD_EXPR', dump_source)
        self.assertIn('"net_client_guard_expr": source_unit_payload_dump_state.SOURCE_UNIT_PAYLOAD_DUMP_NET_CLIENT_GUARD_EXPR', dump_source)
        self.assertIn('"prevents_stacking_comment_expr": source_unit_payload_dump_state.SOURCE_UNIT_PAYLOAD_DUMP_PREVENTS_STACKING_COMMENT_EXPR', dump_source)
        self.assertNotIn('"source": "core/src/mindustry/world/blocks/payloads/UnitPayload.java"', dump_source)
        self.assertNotIn('"method": "public boolean dump(){"', dump_source)
        self.assertNotIn('"overlap_guard_expr": "if(!unit.type.flying && Units.count(unit.x, unit.y, unit.physicSize() * 1.05f', dump_source)
        self.assertNotIn('"net_client_guard_expr": "if(Vars.net.client()) return true;"', dump_source)
        self.assertNotIn('"prevents_stacking_comment_expr": "//prevents stacking"', dump_source)

