    def test_source_block_producer_source_text_state_owns_set_bars_literals(self):
        owner = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockProducerSourceTextState.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockProducerState.gd"
        owner_source = owner.read_text(encoding="utf-8") if owner.exists() else ""
        module_source = module.read_text(encoding="utf-8") if module.exists() else ""

        self.assertTrue(owner.exists(), "SourceBlockProducerSourceTextState.gd must own BlockProducer source-text literals")
        self.assertIn("class_name SourceBlockProducerSourceTextState", owner_source)
        for const_name, const_value in {
            "SOURCE_BLOCK_PRODUCER_ICONS_METHOD": "public TextureRegion[] icons(){",
            "SOURCE_BLOCK_PRODUCER_ICONS_RETURN_EXPR": "return new TextureRegion[]{region, outRegion, topRegion};",
            "SOURCE_BLOCK_PRODUCER_DRAW_PLAN_REGION_METHOD": "public void drawPlanRegion(BuildPlan plan, Eachable<BuildPlan> list){",
            "SOURCE_BLOCK_PRODUCER_DRAW_PLAN_REGION_REGION_EXPR": "Draw.rect(region, plan.drawx(), plan.drawy());",
            "SOURCE_BLOCK_PRODUCER_DRAW_PLAN_REGION_OUT_REGION_EXPR": "Draw.rect(outRegion, plan.drawx(), plan.drawy(), plan.rotation * 90);",
            "SOURCE_BLOCK_PRODUCER_DRAW_PLAN_REGION_TOP_REGION_EXPR": "Draw.rect(topRegion, plan.drawx(), plan.drawy());",
            "SOURCE_BLOCK_PRODUCER_SET_BARS_ADD_BAR_EXPR": "addBar(\"progress\", (BlockProducerBuild entity) -> new Bar(\"bar.progress\", Pal.ammo, () -> entity.recipe() == null ? 0f : (entity.progress / entity.recipe().buildTime)));",
            "SOURCE_BLOCK_PRODUCER_SET_BARS_PROGRESS_EXPR": "entity.recipe() == null ? 0f : (entity.progress / entity.recipe().buildTime)",
            "SOURCE_BLOCK_PRODUCER_BUILD_ACCEPT_ITEM_METHOD": "public boolean acceptItem(Building source, Item item){",
            "SOURCE_BLOCK_PRODUCER_BUILD_ACCEPT_ITEM_RETURN_EXPR": "return items.get(item) < getMaximumAccepted(item);",
            "SOURCE_BLOCK_PRODUCER_BUILD_GET_MAXIMUM_ACCEPTED_METHOD": "public int getMaximumAccepted(Item item){",
            "SOURCE_BLOCK_PRODUCER_BUILD_GET_MAXIMUM_ACCEPTED_NULL_GUARD": "if(recipe() == null) return 0;",
            "SOURCE_BLOCK_PRODUCER_BUILD_GET_MAXIMUM_ACCEPTED_REQUIREMENT_LOOP": "for(ItemStack stack : recipe().requirements){",
            "SOURCE_BLOCK_PRODUCER_BUILD_GET_MAXIMUM_ACCEPTED_MATCH_EXPR": "if(stack.item == item) return stack.amount * 2;",
            "SOURCE_BLOCK_PRODUCER_BUILD_GET_MAXIMUM_ACCEPTED_FINAL_RETURN": "return 0;",
            "SOURCE_BLOCK_PRODUCER_BUILD_ACCEPT_PAYLOAD_METHOD": "public boolean acceptPayload(Building source, Payload payload){",
            "SOURCE_BLOCK_PRODUCER_BUILD_ACCEPT_PAYLOAD_RETURN_EXPR": "return false;",
            "SOURCE_BLOCK_PRODUCER_BUILD_SHOULD_CONSUME_METHOD": "public boolean shouldConsume(){",
            "SOURCE_BLOCK_PRODUCER_BUILD_SHOULD_CONSUME_RETURN_EXPR": "return super.shouldConsume() && recipe() != null;",
        }.items():
            gdscript_value = const_value.replace("\\", "\\\\").replace('"', '\\"')
            self.assertIn(f'const {const_name} := "{gdscript_value}"', owner_source)
            self.assertIn(f"const {const_name} := source_block_producer_source_text_state.{const_name}", module_source)
            self.assertNotIn(f'const {const_name} := "{gdscript_value}"', module_source)
        self.assertIn('const SOURCE_BLOCK_PRODUCER_SET_BARS_METHOD := "public void setBars(){"', owner_source)
        self.assertIn('const SOURCE_BLOCK_PRODUCER_SET_BARS_SUPER_EXPR := "super.setBars();"', owner_source)
        self.assertIn('const source_block_producer_source_text_state := preload("res://src/game/SourceBlockProducerSourceTextState.gd")', module_source)
        self.assertIn("const SOURCE_BLOCK_PRODUCER_SET_BARS_METHOD := source_block_producer_source_text_state.SOURCE_BLOCK_PRODUCER_SET_BARS_METHOD", module_source)
        self.assertIn("const SOURCE_BLOCK_PRODUCER_SET_BARS_SUPER_EXPR := source_block_producer_source_text_state.SOURCE_BLOCK_PRODUCER_SET_BARS_SUPER_EXPR", module_source)
        self.assertIn("const SOURCE_BLOCK_PRODUCER_SET_BARS_ADD_BAR_EXPR := source_block_producer_source_text_state.SOURCE_BLOCK_PRODUCER_SET_BARS_ADD_BAR_EXPR", module_source)
        self.assertIn("const SOURCE_BLOCK_PRODUCER_SET_BARS_PROGRESS_EXPR := source_block_producer_source_text_state.SOURCE_BLOCK_PRODUCER_SET_BARS_PROGRESS_EXPR", module_source)
        self.assertNotIn('const SOURCE_BLOCK_PRODUCER_SET_BARS_METHOD := "public void setBars(){"', module_source)
        self.assertNotIn('const SOURCE_BLOCK_PRODUCER_SET_BARS_SUPER_EXPR := "super.setBars();"', module_source)

