    def test_source_block_producer_move_out_payload_source_text_state_owns_move_out_payload_literals(self):
        owner = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockProducerMoveOutPayloadSourceTextState.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockProducerMoveOutPayloadState.gd"
